INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u5-C1','kor',1,2,'u5',1,'글자의 짜임 알기 — 글자를 첫 자음자·모음자·받침 세 자리로 나누어 보고, 받침이 없는 글자도 있음을 알기, 한 자리만 다른 비슷한 글자를 가려내기',ARRAY['2국04-01']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u5-C2','kor',1,2,'u5',3,'한글이 만들어진 까닭과 원리 알기 — 세종 대왕이 백성이 쉽게 읽고 쓰게 하려고 만든 글자, 누가·언제·왜 만들었는지 알려진 글자, 자음자는 획을 더해 소리를 세게·모음자는 짧은 획의 방향을 달리해 만든 원리',ARRAY['2국04-04']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u5-C3','kor',1,2,'u5',4,'글자의 한 자리를 바꾸어 뜻이 있는 낱말 만들기 — 첫 자음자·모음자·받침 가운데 한 자리만 바꾸고, 소리와 뜻이 함께 달라짐을 알기, 뜻이 없는 글자는 낱말이 아님을 가르기',ARRAY['2국04-01']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u5-C4','kor',1,2,'u5',6,'책에 흥미를 가지고 재미를 나누기 — 제목·그림·궁금한 것으로 읽고 싶은 책 고르기, 웃음·뭉클함·새로 앎 모두 책의 재미임을 알기, 재미있는 부분을 까닭과 함께 말하고 추천하기, 사람마다 다른 재미를 존중하기',ARRAY['2국02-05']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u5-C5','kor',1,2,'u5',8,'글쓴이가 한 일과 마음 찾기 — 글쓴이가 한 일을 차례대로 찾고, 「가슴이 철렁했다」 같은 마음을 알려 주는 말에서 그때의 마음을 짐작하기, 글에 없는 일은 넣지 않기',ARRAY['2국02-03']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u5-C6','kor',1,2,'u5',8,'글을 읽고 생각이나 느낌을 까닭과 함께 나누기 — 글의 어느 부분 때문인지 함께 말하기, 글쓴이의 말을 옮기지 않고 내 말로 말하기, 마음이 비슷한 내 경험 떠올리기, 다른 생각을 존중하기',ARRAY['2국02-03']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u5-C7','kor',1,2,'u5',10,'독서 계획 세우기 — 고르기→차례 정하기→한 권씩 끝까지 읽기 세 걸음, 계단 계획표 맨 아래 칸에 가장 읽고 싶고 쉬운 책, 다 읽으면 색칠, 어긋나면 고쳐서 이어 가기, 겨루기가 아님',ARRAY['2국02-05']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u5-C8','kor',1,2,'u5',12,'세는 낱말 알기 — 동물은 마리, 꽃은 송이, 나무는 그루, 책은 권처럼 물건에 따라 다른 세는 낱말 쓰기(기초 다지기)',ARRAY['2국04-02']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X01','kor',1,'u5',ARRAY['K1-2-u5-C1','K1-2-u5-C3']::text[],'첫 자음자·모음자·받침의 자리 이름을 서로 바꾸어 말한다(아래에 붙은 모음자를 받침으로 보기 등)','글자를 손가락으로 짚으며 「처음 소리 → 가운데 소리 → 끝소리」 차례로 자리 이름을 말하게 하기 — 「무」의 ㅜ는 가운데 소리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X02','kor',1,'u5',ARRAY['K1-2-u5-C1','K1-2-u5-C3']::text[],'두 자리 이상 다른 글자를 「한 자리만 다르다」고 하거나, 바꿀 때 두 자리를 한꺼번에 바꾼다','두 글자를 세 칸 표에 나란히 적고 다른 칸에 동그라미 — 동그라미가 하나일 때만 「한 자리만 다른 짝」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X03','kor',1,'u5',ARRAY['K1-2-u5-C1','K1-2-u5-C3']::text[],'한 자리만 바뀌면 모양만 달라지고 소리나 뜻은 그대로라고 여긴다','「공」과 「곰」을 소리 내어 읽고 그림을 짝지어 보게 하기 — 한 자리로 공이 동물이 된다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X04','kor',1,'u5',ARRAY['K1-2-u5-C2']::text[],'한글이 누가·언제·왜 만들었는지 알려진 글자라는 것을 모른다(저절로 생겼다·알 수 없다고 여기기)','「세종 대왕 · 백성을 위해 · 한글날」 세 낱말 카드를 들고 누가·왜·언제를 짝지어 말하게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X05','kor',1,'u5',ARRAY['K1-2-u5-C2']::text[],'한글을 만든 까닭과 한글이 있어 좋은 점을 백성(누구나)이 아닌 것에서 찾는다(임금 혼자 쓰려고·어렵게 하려고)','「한글이 없던 때엔 누가 글을 읽었을까?」 물은 뒤, 지금 우리 반 모두가 읽고 쓴다는 것과 견주어 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X06','kor',1,'u5',ARRAY['K1-2-u5-C2']::text[],'글자 모양이 아무렇게나 정해졌다고 여긴다(자음자의 획 더하기·모음자의 방향 원리를 모름)','ㄴ 위에 획을 하나씩 얹어 ㄷ·ㅌ을 만들고 소리 내어 세기를 느껴 보기, 모음자는 짧은 획 카드를 위·아래·좌·우에 붙여 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X07','kor',1,'u5',ARRAY['K1-2-u5-C3']::text[],'소리는 나지만 뜻이 없는 글자(곺·닽)를 낱말이라고 한다','「그게 무엇인지 그림으로 그릴 수 있나요?」 — 그릴 수도 설명할 수도 없으면 낱말이 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X08','kor',1,'u5',ARRAY['K1-2-u5-C4','K1-2-u5-C7']::text[],'책을 무게·값·두께·쪽수·글자 크기처럼 내용과 상관없는 것으로 고르거나 평가한다','「그걸 알면 무슨 이야기인지 알 수 있나요?」 제목·겉표지 그림·궁금한 것으로 눈을 돌리게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X09','kor',1,'u5',ARRAY['K1-2-u5-C4']::text[],'책의 재미를 웃긴 것만으로 여긴다(뭉클함·새로 앎은 재미가 아니라고 보기)','「웃음 · 뭉클 · 새로 앎」 세 칸 표에 읽은 책을 하나씩 넣어 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X10','kor',1,'u5',ARRAY['K1-2-u5-C4','K1-2-u5-C6']::text[],'「재미있었다·좋았다」 한마디만 하거나 쪽수만 말하고 어느 부분이 왜 그런지 까닭을 말하지 않는다','「어느 부분이? 왜?」 두 물음에 하나씩 답하게 하기 — 「~ 부분이 ~해서」 틀 쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X11','kor',1,'u5',ARRAY['K1-2-u5-C4','K1-2-u5-C6']::text[],'나와 다른 부분을 재미있다고 하거나 생각이 다른 친구를 틀렸다고 한다','「사람마다 마음이 움직이는 곳이 달라요」 — 친구에게 왜 그 부분인지 한 번 물어보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X12','kor',1,'u5',ARRAY['K1-2-u5-C4']::text[],'책과 다른 것(만화 영화·놀이)을 견주어 하나를 나쁘다고 정한다','「나쁜 것 찾기」 대신 「책이 잘하는 것」 한 가지 말하기 — 천천히 다시 읽을 수 있다, 상상할 수 있다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X13','kor',1,'u5',ARRAY['K1-2-u5-C5','K1-2-u5-C4']::text[],'글에 없는 일을 있었던 일로 넣거나, 다른 사람이 한 일과 바꾸거나, 한 일의 차례를 뒤집는다','「그 일이 글 몇째 줄에 있나요?」 줄을 손가락으로 짚게 하고, 차례는 「처음·그다음·마지막」 말을 찾아 줄 세우기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X14','kor',1,'u5',ARRAY['K1-2-u5-C5']::text[],'마음을 알려 주는 말(철렁했다·눈물이 났다·어깨가 으쓱했다)을 찾지 않고 겉일만 보고 마음을 짐작하거나 거꾸로 읽는다','글에서 몸이나 얼굴이 어떻게 되었다는 말에 밑줄 — 「그 몸짓은 어떤 마음일 때 나오나요?」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X15','kor',1,'u5',ARRAY['K1-2-u5-C6']::text[],'글쓴이가 쓴 문장을 그대로 옮겨 말하고 그것을 내 생각이라고 한다','「그건 글에 이미 있는 말이에요. 그 말을 읽고 네 마음은 어땠어?」 — 「~해 보였어」 「나라면 ~」 틀 주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X16','kor',1,'u5',ARRAY['K1-2-u5-C6']::text[],'비슷한 경험을 같은 물건이 나오는지로만 찾거나, 마음도 일도 닮지 않은 것을 비슷한 경험이라고 한다','「무슨 일이 있었고 그때 마음이 어땠나?」 두 칸을 글과 내 경험에 나란히 채워 마음이 닮았는지 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X17','kor',1,'u5',ARRAY['K1-2-u5-C7']::text[],'독서 계획표의 차례를 거꾸로 하거나(맨 위 칸이 먼저·어려운 책 먼저) 적을 것을 모른다(아직 안 읽은 책의 느낌 적기)','종이 계단을 아래에서 위로 손가락으로 오르며 「첫째 → 둘째 → 셋째」 소리 내기, 계획표엔 제목·차례만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X18','kor',1,'u5',ARRAY['K1-2-u5-C7']::text[],'독서 계획을 권수 세기·친구와 겨루기로 여긴다','「계획은 누구랑 겨루려고?」 — 어제의 나보다 한 칸 올라가는 것이 목표라고 짚어 주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X19','kor',1,'u5',ARRAY['K1-2-u5-C7']::text[],'한 권을 끝까지 이어 읽지 않는다(여러 권 건너뛰며 넘기기·어려우면 그만두기·계획을 못 고친다고 여기기)','「한 권을 끝까지 → 색칠 → 다음 칸」 고리를 보여 주고, 어려우면 읽을 수 있는 책으로 바꾸어도 된다고 먼저 말해 주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u5-X20','kor',1,'u5',ARRAY['K1-2-u5-C8']::text[],'물건에 맞지 않는 세는 낱말을 쓴다(꽃 한 마리·책 한 그루)','「살아서 움직이면 마리, 땅에 서 있는 나무는 그루, 꽃은 송이, 책은 권」 그림 카드와 짝짓기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_basic#1','kor',1,2,'u5','L01','g1_2_kor_u5_L01_basic','lesson_basic','K1-2-u5-C1',1,'mc','auto','「밤」에서 받침은 어느 것인가요?',ARRAY['K1-2-u5-X01']::text[],true,'{"seq":1,"concept":"K1-2-u5-C1","difficulty":1,"kind":"mc","stem":"「밤」에서 받침은 어느 것인가요?","options":[{"t":"ㅁ","correct":true},{"t":"ㅂ","mis":"K1-2-u5-X01"},{"t":"ㅏ","mis":"K1-2-u5-X01"}],"explanation":["「밤」은 ㅂ + ㅏ + ㅁ 이에요. 끝소리 ㅁ이 받침이에요.","ㅂ은 첫 자음자, ㅏ는 모음자예요.","처음 소리 → 가운데 소리 → 끝소리 차례로 짚어요."],"variant_rule":{"alt":[{"stem":"「솔」에서 첫 자음자는 어느 것인가요?","options":[{"t":"ㅅ","correct":true},{"t":"ㄹ","mis":"K1-2-u5-X01"},{"t":"ㅗ","mis":"K1-2-u5-X01"}],"explanation":["「솔」은 ㅅ + ㅗ + ㄹ 이에요. 처음 소리 ㅅ이 첫 자음자예요.","ㄹ은 받침, ㅗ는 모음자예요.","처음 소리부터 짚어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_basic#2','kor',1,2,'u5','L01','g1_2_kor_u5_L01_basic','lesson_basic','K1-2-u5-C1',1,'mc','auto','첫 자음자만 다른 짝은 어느 것인가요?',ARRAY['K1-2-u5-X01','K1-2-u5-X02']::text[],true,'{"seq":2,"concept":"K1-2-u5-C1","difficulty":1,"kind":"mc","stem":"첫 자음자만 다른 짝은 어느 것인가요?","options":[{"t":"솜 — 곰","correct":true},{"t":"솜 — 삼","mis":"K1-2-u5-X01"},{"t":"솜 — 곳","mis":"K1-2-u5-X02"}],"explanation":["솜과 곰은 ㅅ과 ㄱ, 첫 자음자만 달라요.","솜과 삼은 모음자가, 솜과 곳은 두 자리가 달라요.","다른 칸에 동그라미를 쳐 봐요."],"variant_rule":{"alt":[{"stem":"모음자만 다른 짝은 어느 것인가요?","options":[{"t":"달 — 돌","correct":true},{"t":"달 — 말","mis":"K1-2-u5-X01"},{"t":"달 — 곰","mis":"K1-2-u5-X02"}],"explanation":["달과 돌은 ㅏ와 ㅗ, 모음자만 달라요.","달과 말은 첫 자음자가, 달과 곰은 세 자리가 모두 달라요.","가운데 소리를 견주어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_basic#3','kor',1,2,'u5','L01','g1_2_kor_u5_L01_basic','lesson_basic','K1-2-u5-C4',1,'mc','auto','읽고 싶은 책을 고를 때 살펴보면 좋은 것은 어느 것인가요?',ARRAY['K1-2-u5-X08']::text[],true,'{"seq":3,"concept":"K1-2-u5-C4","difficulty":1,"kind":"mc","stem":"읽고 싶은 책을 고를 때 살펴보면 좋은 것은 어느 것인가요?","options":[{"t":"책 제목과 겉표지 그림","correct":true},{"t":"책의 무게","mis":"K1-2-u5-X08"},{"t":"책의 값","mis":"K1-2-u5-X08"}],"explanation":["제목과 그림을 보면 어떤 이야기인지 짐작할 수 있어요.","무게나 값은 내용과 관계가 없어요.","내가 궁금한 것이 담겼는지도 살펴요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 읽고 싶은 책을 고를 때 살펴보면 좋은 것은 어느 것인가요?","options":[{"t":"내가 궁금해하던 것이 나오는지","correct":true},{"t":"책이 얼마나 두꺼운지","mis":"K1-2-u5-X08"},{"t":"책을 어디에서 샀는지","mis":"K1-2-u5-X08"}],"explanation":["궁금한 것이 나오면 끝까지 읽고 싶어져요.","두께나 산 곳은 내용과 관계가 없어요.","제목과 그림도 함께 살펴요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_basic#4','kor',1,2,'u5','L01','g1_2_kor_u5_L01_basic','lesson_basic','K1-2-u5-C1',1,'mc','auto','글자 하나를 바꾸면 무엇이 달라지나요?',ARRAY['K1-2-u5-X03']::text[],false,'{"seq":4,"concept":"K1-2-u5-C1","difficulty":1,"kind":"mc","stem":"글자 하나를 바꾸면 무엇이 달라지나요?","options":[{"t":"소리와 뜻이 함께 달라진다","correct":true},{"t":"모양만 달라지고 뜻은 같다","mis":"K1-2-u5-X03"},{"t":"아무것도 달라지지 않는다","mis":"K1-2-u5-X03"}],"explanation":["「공」을 「곰」으로 바꾸면 소리도 뜻도 달라져요.","모양만 바뀌는 것이 아니에요.","소리 내어 읽고 뜻을 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_basic#5','kor',1,2,'u5','L01','g1_2_kor_u5_L01_basic','lesson_basic','K1-2-u5-C1',2,'mc','auto','「코」에는 어떤 자리가 있나요?',ARRAY['K1-2-u5-X01']::text[],true,'{"seq":5,"concept":"K1-2-u5-C1","difficulty":2,"kind":"mc","stem":"「코」에는 어떤 자리가 있나요?","options":[{"t":"첫 자음자와 모음자","correct":true},{"t":"첫 자음자, 모음자, 받침","mis":"K1-2-u5-X01"},{"t":"모음자와 받침","mis":"K1-2-u5-X01"}],"explanation":["「코」는 ㅋ + ㅗ 예요. 받침이 없는 글자예요.","ㅗ는 아래에 붙어 있어도 받침이 아니라 모음자예요.","끝소리가 있을 때만 받침이 있어요."],"variant_rule":{"alt":[{"stem":"「나무」의 「무」에는 어떤 자리가 있나요?","options":[{"t":"첫 자음자와 모음자","correct":true},{"t":"첫 자음자와 받침","mis":"K1-2-u5-X01"},{"t":"첫 자음자, 모음자, 받침","mis":"K1-2-u5-X01"}],"explanation":["「무」는 ㅁ + ㅜ 예요. 받침이 없어요.","아래에 붙은 ㅜ는 모음자예요.","끝소리가 있는지 살펴요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_basic#6','kor',1,2,'u5','L01','g1_2_kor_u5_L01_basic','lesson_basic','K1-2-u5-C1',2,'match','auto','글자와 그 글자의 받침을 선으로 이어 보세요.','{}'::text[],true,'{"seq":6,"concept":"K1-2-u5-C1","difficulty":2,"kind":"match","stem":"글자와 그 글자의 받침을 선으로 이어 보세요.","pairs":[{"l":"곰","r":"ㅁ"},{"l":"손","r":"ㄴ"},{"l":"달","r":"ㄹ"}],"mis":"K1-2-u5-X01","explanation":["곰의 받침은 ㅁ, 손의 받침은 ㄴ이에요.","달의 받침은 ㄹ이에요.","글자 맨 아래 끝소리를 봐요."],"variant_rule":{"alt":[{"stem":"글자와 그 글자의 모음자를 선으로 이어 보세요.","pairs":[{"l":"공","r":"ㅗ"},{"l":"눈","r":"ㅜ"},{"l":"밤","r":"ㅏ"}],"explanation":["공의 모음자는 ㅗ, 눈의 모음자는 ㅜ예요.","밤의 모음자는 ㅏ예요.","가운데 소리를 찾아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_basic#7','kor',1,2,'u5','L01','g1_2_kor_u5_L01_basic','lesson_basic','K1-2-u5-C1',2,'mc','auto','놀이터 안내판의 「공」과 「곰」은 어느 자리가 다른가요?',ARRAY['K1-2-u5-X01']::text[],true,'{"seq":7,"concept":"K1-2-u5-C1","difficulty":2,"kind":"mc","stem":"놀이터 안내판의 「공」과 「곰」은 어느 자리가 다른가요?","options":[{"t":"받침","correct":true},{"t":"첫 자음자","mis":"K1-2-u5-X01"},{"t":"모음자","mis":"K1-2-u5-X01"}],"explanation":["공은 받침이 ㅇ, 곰은 받침이 ㅁ이에요.","ㄱ과 ㅗ는 두 글자가 같아요.","끝소리만 달라요."],"asset":{"type":"passage","lines":["놀이터에서는 공을 살살 차요.","곰 인형은 그네에 두지 말아요."],"title":"놀이터 안내판","hi":["공","곰"]},"variant_rule":{"alt":[{"stem":"운동장 안내판의 「줄」과 「풀」은 어느 자리가 다른가요?","options":[{"t":"첫 자음자","correct":true},{"t":"모음자","mis":"K1-2-u5-X01"},{"t":"받침","mis":"K1-2-u5-X01"}],"explanation":["줄은 ㅈ, 풀은 ㅍ으로 시작해요.","ㅜ와 ㄹ은 두 글자가 같아요.","처음 소리만 달라요."],"asset":{"type":"passage","lines":["줄을 서서 기다려요.","풀밭에는 들어가지 말아요."],"title":"운동장 안내판","hi":["줄","풀"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_basic#8','kor',1,2,'u5','L01','g1_2_kor_u5_L01_basic','lesson_basic','K1-2-u5-C4',2,'ox','auto','책을 고를 때 내가 궁금해하던 것이 담긴 책을 고르면 좋아요.',ARRAY['K1-2-u5-X08']::text[],true,'{"seq":8,"concept":"K1-2-u5-C4","difficulty":2,"kind":"ox","stem":"책을 고를 때 내가 궁금해하던 것이 담긴 책을 고르면 좋아요.","answer":"O","reason_options":[{"t":"궁금한 것이 나오면 끝까지 읽고 싶어지니까","correct":true},{"t":"두꺼운 책일수록 궁금한 것이 많으니까","mis":"K1-2-u5-X08"}],"mis":"K1-2-u5-X08","explanation":["궁금한 것이 있으면 책장을 넘기고 싶어져요.","두께는 상관없어요.","제목과 그림으로 궁금한 것을 찾아요."],"variant_rule":{"alt":[{"stem":"책은 가장 무거운 것을 골라야 많이 배울 수 있어요.","answer":"X","reason_options":[{"t":"무게는 책 내용과 관계가 없으니까","correct":true},{"t":"무거운 책에 글자가 더 많으니까","mis":"K1-2-u5-X08"}],"explanation":["무게로는 무슨 이야기인지 알 수 없어요.","내가 궁금한 것이 담긴 책을 골라요.","제목과 그림을 살펴요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_basic#9','kor',1,2,'u5','L01','g1_2_kor_u5_L01_basic','lesson_basic','K1-2-u5-C4',2,'mc','auto','책을 고른 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u5-X08']::text[],false,'{"seq":9,"concept":"K1-2-u5-C4","difficulty":2,"kind":"mc","stem":"책을 고른 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"좋아하는 공룡이 나오는 책이라서","correct":true},{"t":"책이 가장 무거워서","mis":"K1-2-u5-X08"},{"t":"책값이 가장 싸서","mis":"K1-2-u5-X08"}],"explanation":["좋아하는 것이 나오면 재미있게 읽을 수 있어요.","무게나 값은 고른 까닭으로 알맞지 않아요.","내 마음이 끌리는 까닭을 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_basic#10','kor',1,2,'u5','L01','g1_2_kor_u5_L01_basic','lesson_basic','K1-2-u5-C1',3,'error','auto','「곰」을 이루는 자리를 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_challenge#1','kor',1,2,'u5','L01','g1_2_kor_u5_L01_challenge','lesson_challenge','K1-2-u5-C1',2,'mc','auto','「강」과 「공」은 어느 자리가 다른가요?',ARRAY['K1-2-u5-X01']::text[],true,'{"seq":1,"concept":"K1-2-u5-C1","difficulty":2,"kind":"mc","stem":"「강」과 「공」은 어느 자리가 다른가요?","options":[{"t":"모음자","correct":true},{"t":"첫 자음자","mis":"K1-2-u5-X01"},{"t":"받침","mis":"K1-2-u5-X01"}],"explanation":["강은 ㅏ, 공은 ㅗ — 가운데 소리만 달라요.","ㄱ과 ㅇ은 두 글자가 같아요.","다른 칸에 동그라미를 쳐요."],"variant_rule":{"alt":[{"stem":"「솜」과 「솔」은 어느 자리가 다른가요?","options":[{"t":"받침","correct":true},{"t":"첫 자음자","mis":"K1-2-u5-X01"},{"t":"모음자","mis":"K1-2-u5-X01"}],"explanation":["솜은 ㅁ, 솔은 ㄹ — 끝소리만 달라요.","ㅅ과 ㅗ는 두 글자가 같아요.","다른 칸에 동그라미를 쳐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_challenge#2','kor',1,2,'u5','L01','g1_2_kor_u5_L01_challenge','lesson_challenge','K1-2-u5-C4',2,'mc','auto','「바닷속 친구들」이라는 책 제목을 보고 짐작할 수 있는 것은 어느 것인가요?',ARRAY['K1-2-u5-X08']::text[],false,'{"seq":2,"concept":"K1-2-u5-C4","difficulty":2,"kind":"mc","stem":"「바닷속 친구들」이라는 책 제목을 보고 짐작할 수 있는 것은 어느 것인가요?","options":[{"t":"바다에 사는 동물이 나올 것 같다","correct":true},{"t":"책이 아주 무거울 것 같다","mis":"K1-2-u5-X08"},{"t":"책값이 쌀 것 같다","mis":"K1-2-u5-X08"}],"explanation":["제목에 「바닷속」이 있으니 바다 이야기일 것 같아요.","제목으로 무게나 값은 알 수 없어요.","제목은 내용을 알려 주는 첫 문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_challenge#3','kor',1,2,'u5','L01','g1_2_kor_u5_L01_challenge','lesson_challenge','K1-2-u5-C1',3,'error','auto','「밤」과 한 자리만 다른 짝을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_challenge#4','kor',1,2,'u5','L01','g1_2_kor_u5_L01_challenge','lesson_challenge','K1-2-u5-C1',3,'mc','auto','「나무」 두 글자에는 받침이 모두 몇 개 있나요?',ARRAY['K1-2-u5-X01']::text[],false,'{"seq":4,"concept":"K1-2-u5-C1","difficulty":3,"kind":"mc","stem":"「나무」 두 글자에는 받침이 모두 몇 개 있나요?","options":[{"t":"0개 — 두 글자 모두 받침이 없다","correct":true},{"t":"2개 — 글자마다 받침이 하나씩 있다","mis":"K1-2-u5-X01"},{"t":"1개 — 「무」의 ㅜ가 받침이다","mis":"K1-2-u5-X01"}],"explanation":["나 = ㄴ + ㅏ, 무 = ㅁ + ㅜ 예요.","아래에 붙은 ㅜ는 모음자예요.","끝소리가 있는지 하나씩 들어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_challenge#5','kor',1,2,'u5','L01','g1_2_kor_u5_L01_challenge','lesson_challenge','K1-2-u5-C1',3,'mc','auto','「곰」을 「곳」으로 바꾸었어요. 바르게 말한 것은 어느 것인가요?',ARRAY['K1-2-u5-X01','K1-2-u5-X03']::text[],false,'{"seq":5,"concept":"K1-2-u5-C1","difficulty":3,"kind":"mc","stem":"「곰」을 「곳」으로 바꾸었어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"받침이 바뀌어 소리와 뜻이 모두 달라졌다","correct":true},{"t":"첫 자음자가 바뀌어 소리만 달라졌다","mis":"K1-2-u5-X01"},{"t":"받침이 바뀌었지만 뜻은 그대로다","mis":"K1-2-u5-X03"}],"explanation":["ㅁ이 ㅅ으로, 받침이 바뀌었어요.","동물 곰이 장소를 뜻하는 곳이 되었으니 뜻도 달라졌어요.","바뀐 자리와 달라진 것을 함께 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_challenge#6','kor',1,2,'u5','L01','g1_2_kor_u5_L01_challenge','lesson_challenge','K1-2-u5-C4',3,'ox','auto','책을 고를 때 겉표지 그림을 살펴보면 어떤 이야기일지 짐작할 수 있어요.',ARRAY['K1-2-u5-X08']::text[],false,'{"seq":6,"concept":"K1-2-u5-C4","difficulty":3,"kind":"ox","stem":"책을 고를 때 겉표지 그림을 살펴보면 어떤 이야기일지 짐작할 수 있어요.","answer":"O","reason_options":[{"t":"그림에 인물이나 일이 담겨 있으니까","correct":true},{"t":"그림이 클수록 좋은 책이니까","mis":"K1-2-u5-X08"}],"mis":"K1-2-u5-X08","explanation":["겉표지 그림에는 이야기의 모습이 담겨 있어요.","그림 크기로 좋은 책을 가리지 않아요.","제목과 그림을 함께 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_challenge#7','kor',1,2,'u5','L01','g1_2_kor_u5_L01_challenge','lesson_challenge','K1-2-u5-C1',3,'match','auto','두 글자에서 달라진 자리를 선으로 이어 보세요.','{}'::text[],true,'{"seq":7,"concept":"K1-2-u5-C1","difficulty":3,"kind":"match","stem":"두 글자에서 달라진 자리를 선으로 이어 보세요.","pairs":[{"l":"공 — 콩","r":"첫 자음자"},{"l":"공 — 강","r":"모음자"},{"l":"공 — 곰","r":"받침"}],"mis":"K1-2-u5-X01","explanation":["콩은 처음 소리, 강은 가운데 소리가 달라요.","곰은 끝소리가 달라요.","다른 칸 하나를 찾아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 두 글자에서 달라진 자리를 선으로 이어 보세요.","pairs":[{"l":"물 — 불","r":"첫 자음자"},{"l":"물 — 말","r":"모음자"},{"l":"물 — 문","r":"받침"}],"explanation":["불은 처음 소리, 말은 가운데 소리가 달라요.","문은 끝소리가 달라요.","다른 칸 하나를 찾아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_challenge#8','kor',1,2,'u5','L01','g1_2_kor_u5_L01_challenge','lesson_challenge','K1-2-u5-C1',4,'sa','auto','「달」과 「돌」에서 달라진 자리의 이름을 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"K1-2-u5-C1","difficulty":4,"kind":"sa","stem":"「달」과 「돌」에서 달라진 자리의 이름을 쓰세요.","answer":["모음자","모음"],"explanation":["달은 ㅏ, 돌은 ㅗ — 가운데 소리가 달라요.","가운데 자리 이름은 모음자예요.","ㄷ과 ㄹ은 같아요."],"variant_rule":{"alt":[{"stem":"「줄」과 「풀」에서 달라진 자리의 이름을 쓰세요.","answer":["첫 자음자","첫자음자","첫 자음"],"explanation":["줄은 ㅈ, 풀은 ㅍ — 처음 소리가 달라요.","처음 자리 이름은 첫 자음자예요.","ㅜ와 ㄹ은 같아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_challenge#9','kor',1,2,'u5','L01','g1_2_kor_u5_L01_challenge','lesson_challenge','K1-2-u5-C4',4,'essay','teacher','읽고 싶은 책 한 권을 떠올려, 책 제목과 고른 까닭을 한 문장씩 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u5-C4","difficulty":4,"kind":"essay","stem":"읽고 싶은 책 한 권을 떠올려, 책 제목과 고른 까닭을 한 문장씩 쓰세요.","answer_guide":{"answer":"예: 「바닷속 친구들」을 읽고 싶다. 고래가 어떻게 숨을 쉬는지 궁금해서다. — 제목과 까닭(궁금한 것·좋아하는 것·그림)이 있으면 맞아요(어떤 책이든 좋아요).","scoring_points":["책 제목이 있는가","고른 까닭이 있는가","까닭이 무게·값이 아니라 내용·그림·궁금함에서 왔는가"]},"explanation":["제목 한 문장, 까닭 한 문장.","궁금한 것·좋아하는 것·그림에서 까닭을 찾아요.","어떤 책이든 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L01_challenge#10','kor',1,2,'u5','L01','g1_2_kor_u5_L01_challenge','lesson_challenge','K1-2-u5-C1',4,'essay','teacher','「공」의 첫 자음자·모음자·받침을 각각 쓰고, 받침을 바꾸면 무엇이 달라지는지 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u5-C1","difficulty":4,"kind":"essay","stem":"「공」의 첫 자음자·모음자·받침을 각각 쓰고, 받침을 바꾸면 무엇이 달라지는지 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 첫 자음자 ㄱ, 모음자 ㅗ, 받침 ㅇ. 받침을 ㅁ으로 바꾸면 「곰」이 되어 소리와 뜻이 모두 달라진다. — 세 자리가 맞고, 소리와 뜻이 달라진다는 말이 있으면 맞아요.","scoring_points":["세 자리를 바르게 썼는가","받침을 바꾼 예가 뜻이 있는 낱말인가","소리와 뜻이 달라진다고 썼는가"]},"explanation":["ㄱ · ㅗ · ㅇ 세 자리예요.","받침만 바꾸면 곰·곳·골처럼 다른 낱말이 돼요.","소리와 뜻이 함께 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L03_basic#1','kor',1,2,'u5','L03','g1_2_kor_u5_L03_basic','lesson_basic','K1-2-u5-C2',1,'mc','auto','우리가 날마다 읽고 쓰는 글자의 이름은 무엇인가요?',ARRAY['K1-2-u5-X04']::text[],false,'{"seq":1,"concept":"K1-2-u5-C2","difficulty":1,"kind":"mc","stem":"우리가 날마다 읽고 쓰는 글자의 이름은 무엇인가요?","options":[{"t":"한글","correct":true},{"t":"한자","mis":"K1-2-u5-X04"},{"t":"알파벳","mis":"K1-2-u5-X04"}],"explanation":["우리가 쓰는 글자는 한글이에요.","한자와 알파벳은 다른 글자예요.","지금 읽는 이 글자가 한글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L03_basic#2','kor',1,2,'u5','L03','g1_2_kor_u5_L03_basic','lesson_basic','K1-2-u5-C2',1,'mc','auto','한글을 만든 사람은 누구인가요?',ARRAY['K1-2-u5-X04']::text[],true,'{"seq":2,"concept":"K1-2-u5-C2","difficulty":1,"kind":"mc","stem":"한글을 만든 사람은 누구인가요?","options":[{"t":"세종 대왕","correct":true},{"t":"이순신 장군","mis":"K1-2-u5-X04"},{"t":"누가 만들었는지 알 수 없다","mis":"K1-2-u5-X04"}],"explanation":["한글은 세종 대왕이 만들었어요.","한글은 만든 사람이 알려진 글자예요.","누가·왜 만들었는지 알려져 있어요."],"variant_rule":{"alt":[{"stem":"세종 대왕이 만든 글자는 무엇인가요?","options":[{"t":"한글","correct":true},{"t":"한자","mis":"K1-2-u5-X04"},{"t":"그림 글자","mis":"K1-2-u5-X04"}],"explanation":["세종 대왕은 한글을 만들었어요.","한자는 다른 나라에서 들어온 글자예요.","우리가 쓰는 글자예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L03_basic#3','kor',1,2,'u5','L03','g1_2_kor_u5_L03_basic','lesson_basic','K1-2-u5-C2',1,'mc','auto','세종 대왕이 한글을 만든 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u5-X05']::text[],false,'{"seq":3,"concept":"K1-2-u5-C2","difficulty":1,"kind":"mc","stem":"세종 대왕이 한글을 만든 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"백성이 쉽게 읽고 쓰게 하려고","correct":true},{"t":"임금님 혼자만 쓰려고","mis":"K1-2-u5-X05"},{"t":"글을 더 어렵게 만들려고","mis":"K1-2-u5-X05"}],"explanation":["글을 몰라 어려움을 겪는 백성을 위해 만들었어요.","혼자 쓰거나 어렵게 하려던 것이 아니에요.","누구나 읽고 쓰게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L03_basic#4','kor',1,2,'u5','L03','g1_2_kor_u5_L03_basic','lesson_basic','K1-2-u5-C2',1,'mc','auto','「ㄴ」에 획을 하나 더하면 어떤 글자가 될까요?',ARRAY['K1-2-u5-X06']::text[],true,'{"seq":4,"concept":"K1-2-u5-C2","difficulty":1,"kind":"mc","stem":"「ㄴ」에 획을 하나 더하면 어떤 글자가 될까요?","options":[{"t":"ㄷ","correct":true},{"t":"ㄹ","mis":"K1-2-u5-X06"},{"t":"ㅁ","mis":"K1-2-u5-X06"}],"explanation":["ㄴ 위에 획을 하나 더하면 ㄷ이 돼요.","ㄹ과 ㅁ은 획을 하나 더해서 생기지 않아요.","획을 더하면 소리가 세져요."],"asset":{"type":"scene","icon":"ㄴ → ?","text":"획을 하나 더해요"},"variant_rule":{"alt":[{"stem":"「ㄱ」에 획을 하나 더하면 어떤 글자가 될까요?","options":[{"t":"ㅋ","correct":true},{"t":"ㄴ","mis":"K1-2-u5-X06"},{"t":"ㅎ","mis":"K1-2-u5-X06"}],"explanation":["ㄱ에 획을 하나 더하면 ㅋ이 돼요.","ㄴ과 ㅎ은 ㄱ에서 생기지 않아요.","획을 더하면 소리가 세져요."],"asset":{"type":"scene","icon":"ㄱ → ?","text":"획을 하나 더해요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L03_basic#5','kor',1,2,'u5','L03','g1_2_kor_u5_L03_basic','lesson_basic','K1-2-u5-C2',2,'mc','auto','「ㅗ」와 「ㅜ」는 무엇이 다른가요?',ARRAY['K1-2-u5-X06']::text[],true,'{"seq":5,"concept":"K1-2-u5-C2","difficulty":2,"kind":"mc","stem":"「ㅗ」와 「ㅜ」는 무엇이 다른가요?","options":[{"t":"짧은 획이 붙은 방향이 다르다","correct":true},{"t":"긴 획의 길이가 다르다","mis":"K1-2-u5-X06"},{"t":"두 글자는 아무 관계가 없다","mis":"K1-2-u5-X06"}],"explanation":["ㅗ는 짧은 획이 위에, ㅜ는 아래에 붙어요.","같은 획을 방향만 달리했어요.","짧은 획이 어디에 있나 봐요."],"asset":{"type":"scene","icon":"ㅗ   ㅜ   ㅏ   ㅓ","text":"같은 짧은 획이 붙은 자리를 살펴봐요"},"variant_rule":{"alt":[{"stem":"「ㅏ」와 「ㅓ」는 무엇이 다른가요?","options":[{"t":"짧은 획이 오른쪽과 왼쪽으로 붙은 방향이 다르다","correct":true},{"t":"긴 획이 서 있고 누워 있다","mis":"K1-2-u5-X06"},{"t":"두 글자는 아무 관계가 없다","mis":"K1-2-u5-X06"}],"explanation":["ㅏ는 오른쪽, ㅓ는 왼쪽에 짧은 획이 붙어요.","긴 획은 둘 다 서 있어요.","짧은 획이 어디에 있나 봐요."],"asset":{"type":"scene","icon":"ㅗ   ㅜ   ㅏ   ㅓ","text":"같은 짧은 획이 붙은 자리를 살펴봐요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L03_basic#6','kor',1,2,'u5','L03','g1_2_kor_u5_L03_basic','lesson_basic','K1-2-u5-C2',2,'mc','auto','한글이 생겨서 가장 크게 달라진 것은 무엇인가요?',ARRAY['K1-2-u5-X05']::text[],false,'{"seq":6,"concept":"K1-2-u5-C2","difficulty":2,"kind":"mc","stem":"한글이 생겨서 가장 크게 달라진 것은 무엇인가요?","options":[{"t":"누구나 자기 생각을 글로 적을 수 있게 되었다","correct":true},{"t":"글을 아는 사람이 더 적어졌다","mis":"K1-2-u5-X05"},{"t":"임금님만 편지를 쓸 수 있게 되었다","mis":"K1-2-u5-X05"}],"explanation":["배우기 쉬운 글자라 누구나 생각을 글로 적게 되었어요.","글을 아는 사람은 더 많아졌어요.","많은 사람의 삶이 어떻게 달라졌는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L03_basic#7','kor',1,2,'u5','L03','g1_2_kor_u5_L03_basic','lesson_basic','K1-2-u5-C2',2,'match','auto','획을 더하기 전 글자와 획을 하나 더한 글자를 선으로 이어 보세요.','{}'::text[],true,'{"seq":7,"concept":"K1-2-u5-C2","difficulty":2,"kind":"match","stem":"획을 더하기 전 글자와 획을 하나 더한 글자를 선으로 이어 보세요.","pairs":[{"l":"ㄱ","r":"ㅋ"},{"l":"ㄴ","r":"ㄷ"},{"l":"ㅅ","r":"ㅈ"}],"mis":"K1-2-u5-X06","explanation":["ㄱ→ㅋ, ㄴ→ㄷ, ㅅ→ㅈ 이에요.","획을 하나 더하면 소리가 세져요.","모양이 닮은 짝을 찾아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 획을 더하기 전 글자와 획을 하나 더한 글자를 선으로 이어 보세요.","pairs":[{"l":"ㄷ","r":"ㅌ"},{"l":"ㅂ","r":"ㅍ"},{"l":"ㅈ","r":"ㅊ"}],"explanation":["ㄷ→ㅌ, ㅂ→ㅍ, ㅈ→ㅊ 이에요.","획을 하나 더하면 소리가 세져요.","모양이 닮은 짝을 찾아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L03_basic#8','kor',1,2,'u5','L03','g1_2_kor_u5_L03_basic','lesson_basic','K1-2-u5-C2',2,'ox','auto','한글은 누가, 왜 만들었는지 알려져 있는 글자예요.',ARRAY['K1-2-u5-X04']::text[],false,'{"seq":8,"concept":"K1-2-u5-C2","difficulty":2,"kind":"ox","stem":"한글은 누가, 왜 만들었는지 알려져 있는 글자예요.","answer":"O","reason_options":[{"t":"세종 대왕이 백성을 위해 만들었다고 알려져 있으니까","correct":true},{"t":"오래된 글자는 모두 만든 사람이 알려져 있으니까","mis":"K1-2-u5-X04"}],"mis":"K1-2-u5-X04","explanation":["한글은 만든 사람과 까닭이 알려져 있어요.","많은 글자는 누가 만들었는지 알 수 없어요.","그래서 한글이 더 특별해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L03_basic#9','kor',1,2,'u5','L03','g1_2_kor_u5_L03_basic','lesson_basic','K1-2-u5-C2',2,'mc','auto','한글이 있어 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u5-X05']::text[],true,'{"seq":9,"concept":"K1-2-u5-C2","difficulty":2,"kind":"mc","stem":"한글이 있어 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"읽고 싶은 책을 스스로 읽을 수 있다","correct":true},{"t":"다른 나라 말을 저절로 알게 된다","mis":"K1-2-u5-X05"},{"t":"글씨 연습을 하지 않아도 된다","mis":"K1-2-u5-X05"}],"explanation":["한글을 알면 책을 스스로 읽을 수 있어요.","다른 나라 말이 저절로 되거나 연습이 필요 없어지지는 않아요.","읽고, 쓰고, 나눌 수 있어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 한글이 있어 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"멀리 있는 사람에게 편지로 마음을 전할 수 있다","correct":true},{"t":"말을 하지 않아도 된다","mis":"K1-2-u5-X05"},{"t":"그림을 그릴 수 없게 된다","mis":"K1-2-u5-X05"}],"explanation":["한글로 쓴 편지로 마음을 전할 수 있어요.","말이나 그림이 필요 없어지지 않아요.","읽고, 쓰고, 나눌 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
