INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L03_challenge#1','kor',1,2,'u5','L03','g1_2_kor_u5_L03_challenge','lesson_challenge','K1-2-u5-C2',2,'mc','auto','「ㅅ → ㅈ → ㅊ」처럼 획을 더하면 소리는 어떻게 되나요?',ARRAY['K1-2-u5-X06']::text[],true,'{"seq":1,"concept":"K1-2-u5-C2","difficulty":2,"kind":"mc","stem":"「ㅅ → ㅈ → ㅊ」처럼 획을 더하면 소리는 어떻게 되나요?","options":[{"t":"소리가 점점 세진다","correct":true},{"t":"소리가 점점 작아져 사라진다","mis":"K1-2-u5-X06"},{"t":"소리는 그대로이다","mis":"K1-2-u5-X06"}],"explanation":["획을 더할수록 소리가 세져요.","소리 내어 읽어 보면 느낄 수 있어요.","ㅅ, ㅈ, ㅊ을 차례로 말해 봐요."],"asset":{"type":"scene","icon":"ㅅ → ㅈ → ㅊ","text":"획을 하나씩 더했어요"},"variant_rule":{"alt":[{"stem":"「ㄴ → ㄷ → ㅌ」처럼 획을 더하면 소리는 어떻게 되나요?","options":[{"t":"소리가 점점 세진다","correct":true},{"t":"소리가 점점 작아진다","mis":"K1-2-u5-X06"},{"t":"소리는 그대로이다","mis":"K1-2-u5-X06"}],"explanation":["획을 더할수록 소리가 세져요.","소리 내어 읽어 보면 느낄 수 있어요.","ㄴ, ㄷ, ㅌ을 차례로 말해 봐요."],"asset":{"type":"scene","icon":"ㄴ → ㄷ → ㅌ","text":"획을 하나씩 더했어요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L03_challenge#2','kor',1,2,'u5','L03','g1_2_kor_u5_L03_challenge','lesson_challenge','K1-2-u5-C2',2,'mc','auto','한글이 생기기 전에는 어땠을까요?',ARRAY['K1-2-u5-X05','K1-2-u5-X04']::text[],false,'{"seq":2,"concept":"K1-2-u5-C2","difficulty":2,"kind":"mc","stem":"한글이 생기기 전에는 어땠을까요?","options":[{"t":"글을 읽고 쓸 줄 아는 사람이 아주 적었다","correct":true},{"t":"누구나 글을 쉽게 썼다","mis":"K1-2-u5-X05"},{"t":"모두 한글로 편지를 썼다","mis":"K1-2-u5-X04"}],"explanation":["그때 글자는 배우기 어려워 글을 아는 사람이 적었어요.","한글이 없었으니 한글 편지도 없었어요.","그래서 세종 대왕이 한글을 만들었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L03_challenge#3','kor',1,2,'u5','L03','g1_2_kor_u5_L03_challenge','lesson_challenge','K1-2-u5-C2',3,'mc','auto','짧은 획이 긴 획의 오른쪽에 붙은 모음자는 어느 것인가요?',ARRAY['K1-2-u5-X06']::text[],true,'{"seq":3,"concept":"K1-2-u5-C2","difficulty":3,"kind":"mc","stem":"짧은 획이 긴 획의 오른쪽에 붙은 모음자는 어느 것인가요?","options":[{"t":"ㅏ","correct":true},{"t":"ㅓ","mis":"K1-2-u5-X06"},{"t":"ㅗ","mis":"K1-2-u5-X06"}],"explanation":["ㅏ는 짧은 획이 오른쪽에 있어요.","ㅓ는 왼쪽, ㅗ는 위쪽이에요.","짧은 획이 붙은 방향을 봐요."],"asset":{"type":"scene","icon":"ㅗ   ㅜ   ㅏ   ㅓ","text":"같은 짧은 획이 붙은 자리를 살펴봐요"},"variant_rule":{"alt":[{"stem":"짧은 획이 긴 획의 아래쪽에 붙은 모음자는 어느 것인가요?","options":[{"t":"ㅜ","correct":true},{"t":"ㅗ","mis":"K1-2-u5-X06"},{"t":"ㅓ","mis":"K1-2-u5-X06"}],"explanation":["ㅜ는 짧은 획이 아래쪽에 있어요.","ㅗ는 위쪽, ㅓ는 왼쪽이에요.","짧은 획이 붙은 방향을 봐요."],"asset":{"type":"scene","icon":"ㅗ   ㅜ   ㅏ   ㅓ","text":"같은 짧은 획이 붙은 자리를 살펴봐요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L03_challenge#4','kor',1,2,'u5','L03','g1_2_kor_u5_L03_challenge','lesson_challenge','K1-2-u5-C2',3,'mc','auto','한글이 다른 많은 글자와 다른 점은 무엇인가요?',ARRAY['K1-2-u5-X04']::text[],false,'{"seq":4,"concept":"K1-2-u5-C2","difficulty":3,"kind":"mc","stem":"한글이 다른 많은 글자와 다른 점은 무엇인가요?","options":[{"t":"누가·언제·왜 만들었는지가 알려져 있다","correct":true},{"t":"아주 오래되어 만든 사람을 알 수 없다","mis":"K1-2-u5-X04"},{"t":"다른 나라에서 빌려 온 글자다","mis":"K1-2-u5-X04"}],"explanation":["한글은 만든 사람·때·까닭이 알려진 글자예요.","많은 글자는 누가 만들었는지 몰라요.","그래서 한글날도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L03_challenge#5','kor',1,2,'u5','L03','g1_2_kor_u5_L03_challenge','lesson_challenge','K1-2-u5-C2',3,'error','auto','획을 하나씩 더해 만든 글자를 차례로 늘어놓았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L03_challenge#6','kor',1,2,'u5','L03','g1_2_kor_u5_L03_challenge','lesson_challenge','K1-2-u5-C2',3,'ox','auto','한글 글자의 모양은 아무렇게나 정한 것이에요.',ARRAY['K1-2-u5-X06']::text[],true,'{"seq":6,"concept":"K1-2-u5-C2","difficulty":3,"kind":"ox","stem":"한글 글자의 모양은 아무렇게나 정한 것이에요.","answer":"X","reason_options":[{"t":"획을 더하거나 짧은 획의 방향을 바꾸는 규칙으로 만들었으니까","correct":true},{"t":"글자마다 모양이 다르니까","mis":"K1-2-u5-X06"}],"mis":"K1-2-u5-X06","explanation":["한글에는 모양을 만드는 규칙이 있어요.","다르게 생겨도 규칙에 따라 생겼어요.","ㄴ·ㄷ·ㅌ, ㅗ·ㅜ를 떠올려요."],"variant_rule":{"alt":[{"stem":"「ㅗ」와 「ㅜ」는 같은 짧은 획을 방향만 달리 붙여 만든 글자예요.","answer":"O","reason_options":[{"t":"짧은 획이 위에 붙으면 ㅗ, 아래에 붙으면 ㅜ이니까","correct":true},{"t":"두 글자는 소리가 아주 비슷하니까","mis":"K1-2-u5-X06"}],"explanation":["방향을 달리해 다른 모음자를 만들었어요.","소리가 비슷해서가 아니라 규칙이 있어서예요.","짧은 획의 자리를 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L03_challenge#7','kor',1,2,'u5','L03','g1_2_kor_u5_L03_challenge','lesson_challenge','K1-2-u5-C2',3,'mc','auto','「백성」은 누구를 말하나요?',ARRAY['K1-2-u5-X05']::text[],false,'{"seq":7,"concept":"K1-2-u5-C2","difficulty":3,"kind":"mc","stem":"「백성」은 누구를 말하나요?","options":[{"t":"나라에 사는 보통 사람들","correct":true},{"t":"임금님","mis":"K1-2-u5-X05"},{"t":"나라를 지키는 장군만","mis":"K1-2-u5-X05"}],"explanation":["백성은 나라에 사는 보통 사람들이에요.","임금님이나 장군만을 말하지 않아요.","한글은 이 사람들을 위한 글자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L03_challenge#8','kor',1,2,'u5','L03','g1_2_kor_u5_L03_challenge','lesson_challenge','K1-2-u5-C2',4,'sa','auto','「ㄷ」에 획을 하나 더하면 어떤 글자가 되는지 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"K1-2-u5-C2","difficulty":4,"kind":"sa","stem":"「ㄷ」에 획을 하나 더하면 어떤 글자가 되는지 쓰세요.","answer":["ㅌ"],"explanation":["ㄷ에 획을 하나 더하면 ㅌ이에요.","ㄴ → ㄷ → ㅌ 차례예요.","소리도 더 세져요."],"variant_rule":{"alt":[{"stem":"「ㅂ」에 획을 하나 더하면 어떤 글자가 되는지 쓰세요.","answer":["ㅍ"],"explanation":["ㅂ에 획을 더하면 ㅍ이에요.","ㅁ → ㅂ → ㅍ 차례예요.","소리도 더 세져요."],"asset":{"type":"scene","icon":"ㅂ → ?","text":"획을 하나 더해요"}},{"stem":"「ㅈ」에 획을 하나 더하면 어떤 글자가 되는지 쓰세요.","answer":["ㅊ"],"explanation":["ㅈ에 획을 더하면 ㅊ이에요.","ㅅ → ㅈ → ㅊ 차례예요.","소리도 더 세져요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L03_challenge#9','kor',1,2,'u5','L03','g1_2_kor_u5_L03_challenge','lesson_challenge','K1-2-u5-C2',4,'essay','teacher','세종 대왕이 한글을 만든 까닭을 「백성」이라는 말을 넣어 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u5-C2","difficulty":4,"kind":"essay","stem":"세종 대왕이 한글을 만든 까닭을 「백성」이라는 말을 넣어 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 세종 대왕은 백성이 글을 쉽게 읽고 쓸 수 있게 하려고 한글을 만들었다. — 「백성」과 「쉽게 읽고 쓰게」라는 뜻이 있으면 맞아요.","scoring_points":["「백성」이 들어갔는가","쉽게 읽고 쓰게 하려는 까닭이 있는가","한 문장인가"]},"explanation":["백성 + 쉽게 읽고 쓰게.","누구를 위해, 무엇을 하라고 만들었는지.","한 문장으로."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L03_challenge#10','kor',1,2,'u5','L03','g1_2_kor_u5_L03_challenge','lesson_challenge','K1-2-u5-C2',4,'essay','teacher','한글이 없다면 우리 생활에서 어떤 점이 어려울지 한 가지 쓰고, 한글을 소중히 여기는 방법을 한 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u5-C2","difficulty":4,"kind":"essay","stem":"한글이 없다면 우리 생활에서 어떤 점이 어려울지 한 가지 쓰고, 한글을 소중히 여기는 방법을 한 가지 쓰세요.","answer_guide":{"answer":"예: 한글이 없다면 친구에게 편지를 쓰기 어려울 것이다. 바르고 고운 말을 또박또박 써서 한글을 소중히 여긴다. — 어려운 점 하나와 소중히 여기는 방법 하나가 있으면 맞아요.","scoring_points":["한글이 없을 때 어려운 점이 있는가","소중히 여기는 방법이 있는가","내 생활과 이어서 썼는가"]},"explanation":["읽기·쓰기·나누기가 어려워져요.","바르고 고운 말, 또박또박 쓰기.","내 생활에서 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_basic#1','kor',1,2,'u5','L04','g1_2_kor_u5_L04_basic','lesson_basic','K1-2-u5-C3',1,'mc','auto','「공」의 첫 자음자만 바꾼 낱말은 어느 것인가요?',ARRAY['K1-2-u5-X01','K1-2-u5-X02']::text[],true,'{"seq":1,"concept":"K1-2-u5-C3","difficulty":1,"kind":"mc","stem":"「공」의 첫 자음자만 바꾼 낱말은 어느 것인가요?","options":[{"t":"콩","correct":true},{"t":"곰","mis":"K1-2-u5-X01"},{"t":"감","mis":"K1-2-u5-X02"}],"explanation":["ㄱ을 ㅋ으로 바꾸면 콩이에요.","곰은 받침을, 감은 두 자리를 바꾸었어요.","모음자 ㅗ와 받침 ㅇ은 그대로예요."],"variant_rule":{"alt":[{"stem":"「물」의 첫 자음자만 바꾼 낱말은 어느 것인가요?","options":[{"t":"불","correct":true},{"t":"문","mis":"K1-2-u5-X01"},{"t":"말","mis":"K1-2-u5-X01"}],"explanation":["ㅁ을 ㅂ으로 바꾸면 불이에요.","문은 받침을, 말은 모음자를 바꾸었어요.","ㅜ와 ㄹ은 그대로예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_basic#2','kor',1,2,'u5','L04','g1_2_kor_u5_L04_basic','lesson_basic','K1-2-u5-C3',1,'mc','auto','「손」의 모음자만 바꾼 낱말은 어느 것인가요?',ARRAY['K1-2-u5-X01']::text[],true,'{"seq":2,"concept":"K1-2-u5-C3","difficulty":1,"kind":"mc","stem":"「손」의 모음자만 바꾼 낱말은 어느 것인가요?","options":[{"t":"산","correct":true},{"t":"돈","mis":"K1-2-u5-X01"},{"t":"솜","mis":"K1-2-u5-X01"}],"explanation":["ㅗ를 ㅏ로 바꾸면 산이에요.","돈은 첫 자음자를, 솜은 받침을 바꾸었어요.","ㅅ과 ㄴ은 그대로예요."],"variant_rule":{"alt":[{"stem":"「곰」의 모음자만 바꾼 낱말은 어느 것인가요?","options":[{"t":"감","correct":true},{"t":"공","mis":"K1-2-u5-X01"},{"t":"솜","mis":"K1-2-u5-X01"}],"explanation":["ㅗ를 ㅏ로 바꾸면 감이에요.","공은 받침을, 솜은 첫 자음자를 바꾸었어요.","ㄱ과 ㅁ은 그대로예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_basic#3','kor',1,2,'u5','L04','g1_2_kor_u5_L04_basic','lesson_basic','K1-2-u5-C3',1,'mc','auto','글자를 바꾸어 낱말을 만들 때 꼭 지켜야 할 것은 어느 것인가요?',ARRAY['K1-2-u5-X07','K1-2-u5-X02']::text[],false,'{"seq":3,"concept":"K1-2-u5-C3","difficulty":1,"kind":"mc","stem":"글자를 바꾸어 낱말을 만들 때 꼭 지켜야 할 것은 어느 것인가요?","options":[{"t":"뜻이 있는 낱말이 되게 바꾼다","correct":true},{"t":"소리가 재미있게만 바꾼다","mis":"K1-2-u5-X07"},{"t":"세 자리를 한꺼번에 바꾼다","mis":"K1-2-u5-X02"}],"explanation":["소리만 나고 뜻이 없으면 낱말이 아니에요.","한 자리씩 바꾸어요.","뜻이 있는지 꼭 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_basic#4','kor',1,2,'u5','L04','g1_2_kor_u5_L04_basic','lesson_basic','K1-2-u5-C3',1,'mc','auto','「곰」의 받침만 바꾼 낱말은 어느 것인가요?',ARRAY['K1-2-u5-X01']::text[],true,'{"seq":4,"concept":"K1-2-u5-C3","difficulty":1,"kind":"mc","stem":"「곰」의 받침만 바꾼 낱말은 어느 것인가요?","options":[{"t":"공","correct":true},{"t":"솜","mis":"K1-2-u5-X01"},{"t":"검","mis":"K1-2-u5-X01"}],"explanation":["ㅁ을 ㅇ으로 바꾸면 공이에요.","솜은 첫 자음자를, 검은 모음자를 바꾸었어요.","ㄱ과 ㅗ는 그대로예요."],"variant_rule":{"alt":[{"stem":"「달」의 받침만 바꾼 낱말은 어느 것인가요?","options":[{"t":"담","correct":true},{"t":"말","mis":"K1-2-u5-X01"},{"t":"돌","mis":"K1-2-u5-X01"}],"explanation":["ㄹ을 ㅁ으로 바꾸면 담이에요.","말은 첫 자음자를, 돌은 모음자를 바꾸었어요.","ㄷ과 ㅏ는 그대로예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_basic#5','kor',1,2,'u5','L04','g1_2_kor_u5_L04_basic','lesson_basic','K1-2-u5-C3',2,'match','auto','낱말과 알맞은 뜻을 선으로 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K1-2-u5-C3","difficulty":2,"kind":"match","stem":"낱말과 알맞은 뜻을 선으로 이어 보세요.","pairs":[{"l":"콩","r":"밥에 넣어 먹는 작고 둥근 열매"},{"l":"곰","r":"몸집이 크고 털이 많은 동물"},{"l":"공","r":"차거나 던지며 노는 둥근 물건"}],"mis":"K1-2-u5-X03","explanation":["한 자리만 달라도 뜻이 아주 달라요.","콩은 먹고, 곰은 동물, 공은 놀잇감이에요.","소리 내어 읽고 떠올려요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 낱말과 알맞은 뜻을 선으로 이어 보세요.","pairs":[{"l":"물","r":"마시거나 씻을 때 쓰는 것"},{"l":"불","r":"뜨겁고 환하게 타는 것"},{"l":"풀","r":"들에 자라는 키 작은 식물"}],"explanation":["한 자리만 달라도 뜻이 아주 달라요.","물·불·풀은 첫 자음자만 달라요.","소리 내어 읽고 떠올려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_basic#6','kor',1,2,'u5','L04','g1_2_kor_u5_L04_basic','lesson_basic','K1-2-u5-C3',2,'ox','auto','「곰」의 받침을 바꾸어 「곺」을 만들었어요. 「곺」은 낱말이에요.',ARRAY['K1-2-u5-X07']::text[],true,'{"seq":6,"concept":"K1-2-u5-C3","difficulty":2,"kind":"ox","stem":"「곰」의 받침을 바꾸어 「곺」을 만들었어요. 「곺」은 낱말이에요.","answer":"X","reason_options":[{"t":"소리는 나지만 아무 뜻이 없으니까","correct":true},{"t":"「곰」에서 한 자리만 바꾸었으니까","mis":"K1-2-u5-X07"}],"mis":"K1-2-u5-X07","explanation":["「곺」은 아무 뜻이 없어 낱말이 아니에요.","한 자리만 바꾸어도 뜻이 없으면 낱말이 아니에요.","곰·공·곳처럼 뜻이 있어야 해요."],"variant_rule":{"alt":[{"stem":"「물」의 첫 자음자를 바꾸어 「풀」을 만들었어요. 「풀」은 낱말이에요.","answer":"O","reason_options":[{"t":"들에 자라는 식물이라는 뜻이 있으니까","correct":true},{"t":"「물」과 받침이 같으니까","mis":"K1-2-u5-X07"}],"explanation":["「풀」은 뜻이 있는 낱말이에요.","받침이 같아서가 아니라 뜻이 있어서 낱말이에요.","뜻이 있는지 살펴요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_basic#7','kor',1,2,'u5','L04','g1_2_kor_u5_L04_basic','lesson_basic','K1-2-u5-C3',2,'mc','auto','「달」의 첫 자음자만 바꾼 낱말을 모두 고른 것은 어느 것인가요?',ARRAY['K1-2-u5-X01','K1-2-u5-X07']::text[],false,'{"seq":7,"concept":"K1-2-u5-C3","difficulty":2,"kind":"mc","stem":"「달」의 첫 자음자만 바꾼 낱말을 모두 고른 것은 어느 것인가요?","options":[{"t":"말, 발, 탈","correct":true},{"t":"말, 돌, 담","mis":"K1-2-u5-X01"},{"t":"말, 발, 닽","mis":"K1-2-u5-X07"}],"explanation":["ㄷ만 ㅁ·ㅂ·ㅌ으로 바꾸면 말·발·탈이에요.","돌·담은 다른 자리를, 닽은 뜻이 없어요.","ㅏ와 ㄹ이 그대로인지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_basic#8','kor',1,2,'u5','L04','g1_2_kor_u5_L04_basic','lesson_basic','K1-2-u5-C3',2,'mc','auto','「곰」을 「솜」으로 바꾸었어요. 어느 자리를 바꾸었나요?',ARRAY['K1-2-u5-X01']::text[],true,'{"seq":8,"concept":"K1-2-u5-C3","difficulty":2,"kind":"mc","stem":"「곰」을 「솜」으로 바꾸었어요. 어느 자리를 바꾸었나요?","options":[{"t":"첫 자음자","correct":true},{"t":"모음자","mis":"K1-2-u5-X01"},{"t":"받침","mis":"K1-2-u5-X01"}],"explanation":["ㄱ을 ㅅ으로, 처음 소리를 바꾸었어요.","ㅗ와 ㅁ은 그대로예요.","처음 소리를 들어 봐요."],"variant_rule":{"alt":[{"stem":"「손」을 「솔」로 바꾸었어요. 어느 자리를 바꾸었나요?","options":[{"t":"받침","correct":true},{"t":"첫 자음자","mis":"K1-2-u5-X01"},{"t":"모음자","mis":"K1-2-u5-X01"}],"explanation":["ㄴ을 ㄹ로, 끝소리를 바꾸었어요.","ㅅ과 ㅗ는 그대로예요.","끝소리를 들어 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
