INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_challenge#1','kor',1,2,'u5','L04','g1_2_kor_u5_L04_challenge','lesson_challenge','K1-2-u5-C3',2,'mc','auto','「물」의 한 자리를 바꾸어 만든 글자 가운데 뜻이 없는 것은 어느 것인가요?',ARRAY['K1-2-u5-X07']::text[],false,'{"seq":1,"concept":"K1-2-u5-C3","difficulty":2,"kind":"mc","stem":"「물」의 한 자리를 바꾸어 만든 글자 가운데 뜻이 없는 것은 어느 것인가요?","options":[{"t":"뭏","correct":true},{"t":"불","mis":"K1-2-u5-X07"},{"t":"줄","mis":"K1-2-u5-X07"}],"explanation":["「뭏」은 소리만 나고 뜻이 없어요.","불과 줄은 뜻이 있는 낱말이에요.","그 낱말을 그림으로 그릴 수 있나 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
