INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_challenge#3','kor',1,2,'u5','L04','g1_2_kor_u5_L04_challenge','lesson_challenge','K1-2-u5-C3',3,'mc','auto','「공」을 「콩」으로 바꾸었더니 무엇이 달라졌나요?',ARRAY['K1-2-u5-X03']::text[],false,'{"seq":3,"concept":"K1-2-u5-C3","difficulty":3,"kind":"mc","stem":"「공」을 「콩」으로 바꾸었더니 무엇이 달라졌나요?","options":[{"t":"소리와 뜻이 모두 달라졌다","correct":true},{"t":"소리만 달라지고 뜻은 같다","mis":"K1-2-u5-X03"},{"t":"뜻만 달라지고 소리는 같다","mis":"K1-2-u5-X03"}],"explanation":["놀이하는 공이 먹는 콩이 되었어요.","소리도 [공]에서 [콩]으로 달라졌어요.","한 자리가 소리와 뜻을 모두 바꾸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_challenge#4','kor',1,2,'u5','L04','g1_2_kor_u5_L04_challenge','lesson_challenge','K1-2-u5-C3',3,'error','auto','「손」의 한 자리만 바꾼 낱말을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_challenge#5','kor',1,2,'u5','L04','g1_2_kor_u5_L04_challenge','lesson_challenge','K1-2-u5-C3',3,'ox','auto','「솜」을 「솥」으로 바꾸면 소리만 달라지고 뜻은 같아요.',ARRAY['K1-2-u5-X03']::text[],false,'{"seq":5,"concept":"K1-2-u5-C3","difficulty":3,"kind":"ox","stem":"「솜」을 「솥」으로 바꾸면 소리만 달라지고 뜻은 같아요.","answer":"X","reason_options":[{"t":"솜은 부드러운 것이고 솥은 밥을 짓는 그릇이라 뜻도 달라지니까","correct":true},{"t":"받침 하나만 바꾸었으니까","mis":"K1-2-u5-X03"}],"mis":"K1-2-u5-X03","explanation":["받침 하나로 뜻이 아주 달라졌어요.","한 자리만 바꾸어도 뜻은 달라져요.","두 낱말을 그림으로 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_challenge#6','kor',1,2,'u5','L04','g1_2_kor_u5_L04_challenge','lesson_challenge','K1-2-u5-C3',3,'mc','auto','「풀」에서 한 자리를 바꾸어 「불」이 되었고, 다시 한 자리를 바꾸어 「발」이 되었어요. 두 번째에 바꾼 자리는 어느 것인가요?',ARRAY['K1-2-u5-X01']::text[],true,'{"seq":6,"concept":"K1-2-u5-C3","difficulty":3,"kind":"mc","stem":"「풀」에서 한 자리를 바꾸어 「불」이 되었고, 다시 한 자리를 바꾸어 「발」이 되었어요. 두 번째에 바꾼 자리는 어느 것인가요?","options":[{"t":"모음자","correct":true},{"t":"첫 자음자","mis":"K1-2-u5-X01"},{"t":"받침","mis":"K1-2-u5-X01"}],"explanation":["불 → 발은 ㅜ가 ㅏ로 바뀌었어요.","첫 번째(풀 → 불)는 첫 자음자를 바꾸었어요.","두 글자씩 나누어 견주어요."],"variant_rule":{"alt":[{"stem":"「달」에서 한 자리를 바꾸어 「돌」이 되었고, 다시 한 자리를 바꾸어 「돈」이 되었어요. 두 번째에 바꾼 자리는 어느 것인가요?","options":[{"t":"받침","correct":true},{"t":"모음자","mis":"K1-2-u5-X01"},{"t":"첫 자음자","mis":"K1-2-u5-X01"}],"explanation":["돌 → 돈은 ㄹ이 ㄴ으로 바뀌었어요.","첫 번째(달 → 돌)는 모음자를 바꾸었어요.","두 글자씩 나누어 견주어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_challenge#7','kor',1,2,'u5','L04','g1_2_kor_u5_L04_challenge','lesson_challenge','K1-2-u5-C3',3,'match','auto','바꾼 자리와 「달」로 만든 낱말을 선으로 이어 보세요.','{}'::text[],true,'{"seq":7,"concept":"K1-2-u5-C3","difficulty":3,"kind":"match","stem":"바꾼 자리와 「달」로 만든 낱말을 선으로 이어 보세요.","pairs":[{"l":"첫 자음자를 바꾸면","r":"말"},{"l":"모음자를 바꾸면","r":"돌"},{"l":"받침을 바꾸면","r":"담"}],"mis":"K1-2-u5-X01","explanation":["ㄷ→ㅁ 말, ㅏ→ㅗ 돌이에요.","ㄹ→ㅁ 은 담이에요.","어느 칸이 바뀌었나 봐요."],"variant_rule":{"alt":[{"stem":"바꾼 자리와 「곰」으로 만든 낱말을 선으로 이어 보세요.","pairs":[{"l":"첫 자음자를 바꾸면","r":"솜"},{"l":"모음자를 바꾸면","r":"감"},{"l":"받침을 바꾸면","r":"공"}],"explanation":["ㄱ→ㅅ 솜, ㅗ→ㅏ 감이에요.","ㅁ→ㅇ 은 공이에요.","어느 칸이 바뀌었나 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_challenge#8','kor',1,2,'u5','L04','g1_2_kor_u5_L04_challenge','lesson_challenge','K1-2-u5-C3',4,'sa','auto','「곰」의 받침만 바꾸어 뜻이 있는 낱말을 하나 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"K1-2-u5-C3","difficulty":4,"kind":"sa","stem":"「곰」의 받침만 바꾸어 뜻이 있는 낱말을 하나 쓰세요.","answer":["공","곳","골","곱","곧","곡"],"explanation":["공·곳·골 들이 될 수 있어요.","ㄱ과 ㅗ는 그대로 두어요.","뜻이 있는지 꼭 살펴요."],"variant_rule":{"alt":[{"stem":"「물」의 첫 자음자만 바꾸어 뜻이 있는 낱말을 하나 쓰세요.","answer":["불","줄","풀","굴","꿀","술"],"explanation":["불·줄·풀·굴 들이 될 수 있어요.","ㅜ와 ㄹ은 그대로 두어요.","뜻이 있는지 꼭 살펴요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_challenge#9','kor',1,2,'u5','L04','g1_2_kor_u5_L04_challenge','lesson_challenge','K1-2-u5-C3',4,'sa','auto','「손」의 모음자만 바꾸어 뜻이 있는 낱말을 하나 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"K1-2-u5-C3","difficulty":4,"kind":"sa","stem":"「손」의 모음자만 바꾸어 뜻이 있는 낱말을 하나 쓰세요.","answer":["산","선","순"],"explanation":["산·선이 될 수 있어요.","ㅅ과 ㄴ은 그대로 두어요.","가운데 소리만 바꾸어요."],"variant_rule":{"alt":[{"stem":"「달」의 모음자만 바꾸어 뜻이 있는 낱말을 하나 쓰세요.","answer":["돌","들"],"explanation":["돌·들이 될 수 있어요.","ㄷ과 ㄹ은 그대로 두어요.","가운데 소리만 바꾸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_challenge#10','kor',1,2,'u5','L04','g1_2_kor_u5_L04_challenge','lesson_challenge','K1-2-u5-C3',4,'essay','teacher','「공」의 첫 자음자, 모음자, 받침을 하나씩 바꾸어 뜻이 있는 낱말을 세 개 만들고, 그 가운데 하나로 짧은 문장을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u5-C3","difficulty":4,"kind":"essay","stem":"「공」의 첫 자음자, 모음자, 받침을 하나씩 바꾸어 뜻이 있는 낱말을 세 개 만들고, 그 가운데 하나로 짧은 문장을 쓰세요.","answer_guide":{"answer":"예: 콩(첫 자음자), 강(모음자), 곰(받침). 곰이 꿀을 먹는다. — 바꾼 자리마다 뜻이 있는 낱말이 하나씩 있고 문장이 있으면 맞아요.","scoring_points":["자리마다 한 자리만 바꾸었는가","세 낱말 모두 뜻이 있는가","그 낱말로 문장을 썼는가"]},"explanation":["콩·종(첫 자음자), 강(모음자), 곰·곳(받침) 들이 있어요.","한 번에 한 자리만.","문장으로 뜻을 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_basic#1','kor',1,2,'u5','L06','g1_2_kor_u5_L06_basic','lesson_basic','K1-2-u5-C4',1,'mc','auto','「박쥐가 나오는 책」에서 예준이가 새로 알게 된 것은 무엇인가요?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":1,"concept":"K1-2-u5-C4","difficulty":1,"kind":"mc","stem":"「박쥐가 나오는 책」에서 예준이가 새로 알게 된 것은 무엇인가요?","options":[{"t":"박쥐는 거꾸로 매달려 잠을 잔다","correct":true},{"t":"박쥐는 동굴 밖에서 잠을 잔다","mis":"K1-2-u5-X13"},{"t":"박쥐는 낮에만 날아다닌다","mis":"K1-2-u5-X13"}],"explanation":["책에 「거꾸로 매달려 잠을 잔다」고 적혀 있었어요.","나머지는 글에 없는 일이에요.","예준이가 「처음 알았어!」 한 까닭이에요."],"asset":{"type":"passage","lines":["쉬는 시간에 예준이는 도서관에서 동굴 그림이 있는 책을 골랐다.","책에는 박쥐가 거꾸로 매달려 잠을 잔다고 적혀 있었다.","예준이는 \"우아, 처음 알았어!\" 하고 말했다.","책장을 넘기다 보니 수업 종이 울린 것도 몰랐다.","집에 간 예준이는 동생에게 박쥐 이야기를 들려주었다."],"title":"「박쥐가 나오는 책」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_basic#2','kor',1,2,'u5','L06','g1_2_kor_u5_L06_basic','lesson_basic','K1-2-u5-C4',1,'mc','auto','책에서 느끼는 재미로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u5-X08']::text[],false,'{"seq":2,"concept":"K1-2-u5-C4","difficulty":1,"kind":"mc","stem":"책에서 느끼는 재미로 알맞은 것은 어느 것인가요?","options":[{"t":"몰랐던 것을 새로 알게 되는 것","correct":true},{"t":"글자가 아주 큰 것","mis":"K1-2-u5-X08"},{"t":"쪽수가 아주 적은 것","mis":"K1-2-u5-X08"}],"explanation":["새로 알게 되는 것도 책의 재미예요.","글자 크기나 쪽수는 재미와 상관없어요.","웃음·뭉클함·새로 앎을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_basic#3','kor',1,2,'u5','L06','g1_2_kor_u5_L06_basic','lesson_basic','K1-2-u5-C4',1,'mc','auto','재미있었던 부분을 말할 때 함께 말할 것은 어느 것인가요?',ARRAY['K1-2-u5-X10']::text[],false,'{"seq":3,"concept":"K1-2-u5-C4","difficulty":1,"kind":"mc","stem":"재미있었던 부분을 말할 때 함께 말할 것은 어느 것인가요?","options":[{"t":"그 부분이 재미있었던 까닭","correct":true},{"t":"그 부분이 몇 쪽인지","mis":"K1-2-u5-X10"},{"t":"책을 산 날짜","mis":"K1-2-u5-X10"}],"explanation":["어느 부분이 왜 재미있었는지 함께 말해요.","쪽수나 날짜로는 내 마음이 전해지지 않아요.","「~해서 재미있었어」."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_basic#4','kor',1,2,'u5','L06','g1_2_kor_u5_L06_basic','lesson_basic','K1-2-u5-C4',1,'mc','auto','「늙은 강아지 이야기」에서 채윤이가 코끝이 찡했던 장면은 어느 것인가요?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":4,"concept":"K1-2-u5-C4","difficulty":1,"kind":"mc","stem":"「늙은 강아지 이야기」에서 채윤이가 코끝이 찡했던 장면은 어느 것인가요?","options":[{"t":"강아지가 다리가 아파도 할아버지 곁을 떠나지 않는 장면","correct":true},{"t":"강아지가 공원에서 공을 쫓는 장면","mis":"K1-2-u5-X13"},{"t":"할아버지가 강아지를 두고 떠나는 장면","mis":"K1-2-u5-X13"}],"explanation":["「그 장면」은 바로 앞 줄의 장면이에요.","나머지는 글에 없는 일이에요.","「그 장면에서」 앞을 봐요."],"asset":{"type":"passage","lines":["채윤이는 할아버지와 늙은 강아지가 나오는 책을 읽었다.","강아지는 다리가 아파도 할아버지 곁을 떠나지 않았다.","그 장면에서 채윤이는 코끝이 찡했다.","책을 덮은 채윤이는 집에 있는 강아지를 꼭 안아 주었다."],"title":"「늙은 강아지 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_basic#5','kor',1,2,'u5','L06','g1_2_kor_u5_L06_basic','lesson_basic','K1-2-u5-C4',2,'mc','auto','「늙은 강아지 이야기」를 읽은 채윤이가 느낀 재미는 어떤 재미인가요?',ARRAY['K1-2-u5-X09','K1-2-u5-X08']::text[],true,'{"seq":5,"concept":"K1-2-u5-C4","difficulty":2,"kind":"mc","stem":"「늙은 강아지 이야기」를 읽은 채윤이가 느낀 재미는 어떤 재미인가요?","options":[{"t":"마음이 뭉클해지는 재미","correct":true},{"t":"배를 잡고 웃는 재미","mis":"K1-2-u5-X09"},{"t":"글자가 커서 읽기 쉬운 재미","mis":"K1-2-u5-X08"}],"explanation":["코끝이 찡한 것은 마음이 뭉클한 거예요.","웃음만 재미가 아니에요.","채윤이의 몸짓에서 찾아요."],"asset":{"type":"passage","lines":["채윤이는 할아버지와 늙은 강아지가 나오는 책을 읽었다.","강아지는 다리가 아파도 할아버지 곁을 떠나지 않았다.","그 장면에서 채윤이는 코끝이 찡했다.","책을 덮은 채윤이는 집에 있는 강아지를 꼭 안아 주었다."],"title":"「늙은 강아지 이야기」"},"variant_rule":{"alt":[{"stem":"「모자를 쫓는 곰」을 읽은 윤슬이가 느낀 재미는 어떤 재미인가요?","options":[{"t":"웃음이 나는 재미","correct":true},{"t":"마음이 뭉클해지는 재미","mis":"K1-2-u5-X13"},{"t":"쪽수가 적어 빨리 끝나는 재미","mis":"K1-2-u5-X08"}],"explanation":["배를 잡고 깔깔 웃었어요.","뭉클한 장면은 이 글에 없어요.","윤슬이의 몸짓에서 찾아요."],"asset":{"type":"passage","lines":["윤슬이는 바람에 날아간 모자를 쫓는 곰이 나오는 책을 읽었다.","곰은 모자만 보고 달리다가 연못에 풍덩 빠졌다.","윤슬이는 배를 잡고 깔깔 웃었다.","윤슬이는 그 장면을 짝에게 소리 내어 읽어 주었다."],"title":"「모자를 쫓는 곰」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_basic#6','kor',1,2,'u5','L06','g1_2_kor_u5_L06_basic','lesson_basic','K1-2-u5-C4',2,'ox','auto','재미있는 책은 웃긴 책뿐이에요.',ARRAY['K1-2-u5-X09']::text[],false,'{"seq":6,"concept":"K1-2-u5-C4","difficulty":2,"kind":"ox","stem":"재미있는 책은 웃긴 책뿐이에요.","answer":"X","reason_options":[{"t":"마음이 뭉클하거나 새로 알게 되는 것도 재미니까","correct":true},{"t":"웃음이 나야 끝까지 읽으니까","mis":"K1-2-u5-X09"}],"mis":"K1-2-u5-X09","explanation":["뭉클함, 새로 앎도 재미예요.","웃긴 책만 끝까지 읽는 것이 아니에요.","세 가지 재미를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_basic#7','kor',1,2,'u5','L06','g1_2_kor_u5_L06_basic','lesson_basic','K1-2-u5-C4',2,'mc','auto','채윤이와 하람이가 재미있다고 한 부분이 달라요. 채윤이가 한 일로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u5-X11']::text[],false,'{"seq":7,"concept":"K1-2-u5-C4","difficulty":2,"kind":"mc","stem":"채윤이와 하람이가 재미있다고 한 부분이 달라요. 채윤이가 한 일로 알맞은 것은 어느 것인가요?","options":[{"t":"하람이에게 왜 그 부분이 좋았는지 물었다","correct":true},{"t":"하람이가 잘못 골랐다고 말했다","mis":"K1-2-u5-X11"},{"t":"하람이에게 자기 부분으로 바꾸라고 했다","mis":"K1-2-u5-X11"}],"explanation":["채윤이는 「그 부분은 왜 좋았어?」 하고 물었어요.","다른 부분을 골라도 틀린 게 아니에요.","까닭을 물어봐요."],"asset":{"type":"speech","turns":[{"who":"채윤","text":"나는 박쥐가 거꾸로 자는 부분이 제일 재미있었어."},{"who":"하람","text":"나는 예준이가 동생에게 이야기해 주는 부분이 좋았는데."},{"who":"채윤","text":"그 부분은 왜 좋았어?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_basic#8','kor',1,2,'u5','L06','g1_2_kor_u5_L06_basic','lesson_basic','K1-2-u5-C4',2,'match','auto','책을 읽은 친구와 그 친구가 느낀 재미를 선으로 이어 보세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u5-C4","difficulty":2,"kind":"match","stem":"책을 읽은 친구와 그 친구가 느낀 재미를 선으로 이어 보세요.","pairs":[{"l":"예준 — 박쥐가 거꾸로 잔다는 것을 알았다","r":"새로 알게 되는 재미"},{"l":"채윤 — 강아지 장면에서 코끝이 찡했다","r":"마음이 뭉클해지는 재미"},{"l":"윤슬 — 곰이 연못에 빠져 깔깔 웃었다","r":"웃음이 나는 재미"}],"mis":"K1-2-u5-X09","explanation":["책의 재미는 한 가지가 아니에요.","새로 앎·뭉클함·웃음 모두 재미예요.","친구가 한 몸짓과 말을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_basic#9','kor',1,2,'u5','L06','g1_2_kor_u5_L06_basic','lesson_basic','K1-2-u5-C4',2,'mc','auto','「박쥐가 나오는 책」에서 예준이가 수업 종이 울린 것도 몰랐던 까닭은 무엇인가요?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":9,"concept":"K1-2-u5-C4","difficulty":2,"kind":"mc","stem":"「박쥐가 나오는 책」에서 예준이가 수업 종이 울린 것도 몰랐던 까닭은 무엇인가요?","options":[{"t":"책에 푹 빠져 시간 가는 줄 몰랐기 때문에","correct":true},{"t":"종이 고장 났기 때문에","mis":"K1-2-u5-X13"},{"t":"도서관이 너무 시끄러웠기 때문에","mis":"K1-2-u5-X13"}],"explanation":["책이 재미있으면 시간 가는 줄 몰라요.","종이 고장 나거나 시끄러웠다는 말은 글에 없어요.","책장을 넘기다 보니."],"asset":{"type":"passage","lines":["쉬는 시간에 예준이는 도서관에서 동굴 그림이 있는 책을 골랐다.","책에는 박쥐가 거꾸로 매달려 잠을 잔다고 적혀 있었다.","예준이는 \"우아, 처음 알았어!\" 하고 말했다.","책장을 넘기다 보니 수업 종이 울린 것도 몰랐다.","집에 간 예준이는 동생에게 박쥐 이야기를 들려주었다."],"title":"「박쥐가 나오는 책」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_basic#10','kor',1,2,'u5','L06','g1_2_kor_u5_L06_basic','lesson_basic','K1-2-u5-C4',3,'error','auto','친구에게 책을 추천할 때 말할 것을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_challenge#1','kor',1,2,'u5','L06','g1_2_kor_u5_L06_challenge','lesson_challenge','K1-2-u5-C4',2,'mc','auto','책을 추천하는 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u5-X08','K1-2-u5-X10']::text[],false,'{"seq":1,"concept":"K1-2-u5-C4","difficulty":2,"kind":"mc","stem":"책을 추천하는 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"이 책은 「모자를 쫓는 곰」이야. 곰이 연못에 빠지는 장면이 웃겨서 추천해.","correct":true},{"t":"이 책 읽어 봐. 엄청 두꺼워.","mis":"K1-2-u5-X08"},{"t":"이 책 좋아. 그냥 읽어.","mis":"K1-2-u5-X10"}],"explanation":["제목과 추천하는 까닭이 다 있어요.","두께나 「그냥」은 까닭이 되지 못해요.","듣는 친구가 읽고 싶어지게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_challenge#2','kor',1,2,'u5','L06','g1_2_kor_u5_L06_challenge','lesson_challenge','K1-2-u5-C4',2,'mc','auto','책에 대한 생각으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u5-X12']::text[],false,'{"seq":2,"concept":"K1-2-u5-C4","difficulty":2,"kind":"mc","stem":"책에 대한 생각으로 알맞은 것은 어느 것인가요?","options":[{"t":"책에는 책만의 좋은 점이 있다","correct":true},{"t":"책이 아닌 것은 모두 나쁘다","mis":"K1-2-u5-X12"},{"t":"책은 만화 영화보다 언제나 더 좋다","mis":"K1-2-u5-X12"}],"explanation":["다른 것을 나쁘다 하지 않고 책이 잘하는 것을 찾아요.","견주어 하나를 나쁘다고 정하지 않아요.","천천히 다시 읽을 수 있는 것도 책의 좋은 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_challenge#3','kor',1,2,'u5','L06','g1_2_kor_u5_L06_challenge','lesson_challenge','K1-2-u5-C4',3,'mc','auto','가은이와 하람이 가운데 책에 대해 알맞게 말한 친구는 누구인가요?',ARRAY['K1-2-u5-X12']::text[],false,'{"seq":3,"concept":"K1-2-u5-C4","difficulty":3,"kind":"mc","stem":"가은이와 하람이 가운데 책에 대해 알맞게 말한 친구는 누구인가요?","options":[{"t":"가은 — 책만의 좋은 점을 말했다","correct":true},{"t":"하람 — 책만 좋다고 했다","mis":"K1-2-u5-X12"},{"t":"둘 다 알맞게 말했다","mis":"K1-2-u5-X12"}],"explanation":["가은이는 책이 잘하는 것을 말했어요.","하람이는 만화 영화를 나쁘다고 했어요.","나쁜 것 찾기가 아니에요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"만화 영화는 나쁘고 책만 좋아."},{"who":"가은","text":"책은 내가 천천히 다시 읽을 수 있어서 좋아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_challenge#4','kor',1,2,'u5','L06','g1_2_kor_u5_L06_challenge','lesson_challenge','K1-2-u5-C4',3,'mc','auto','예준이가 「왜 재미있는데?」 하고 물은 까닭은 무엇인가요?',ARRAY['K1-2-u5-X10','K1-2-u5-X08']::text[],true,'{"seq":4,"concept":"K1-2-u5-C4","difficulty":3,"kind":"mc","stem":"예준이가 「왜 재미있는데?」 하고 물은 까닭은 무엇인가요?","options":[{"t":"태오가 추천하는 까닭을 말하지 않았기 때문에","correct":true},{"t":"태오가 책 제목을 너무 길게 말했기 때문에","mis":"K1-2-u5-X10"},{"t":"두꺼운 책은 재미없기 때문에","mis":"K1-2-u5-X08"}],"explanation":["「엄청 두꺼워」는 재미의 까닭이 아니에요.","태오는 제목도 까닭도 말하지 않았어요.","추천에는 까닭이 있어야 해요."],"asset":{"type":"speech","turns":[{"who":"태오","text":"이 책 읽어 봐. 엄청 두꺼워."},{"who":"예준","text":"왜 재미있는데?"}]},"variant_rule":{"alt":[{"stem":"가은이의 추천이 알맞은 까닭은 무엇인가요?","options":[{"t":"제목과 추천하는 까닭을 함께 말했기 때문에","correct":true},{"t":"책이 아주 두껍다고 말했기 때문에","mis":"K1-2-u5-X08"},{"t":"「좋아」 한마디로 짧게 말했기 때문에","mis":"K1-2-u5-X10"}],"explanation":["가은이는 제목과 웃긴 장면을 함께 말했어요.","두께나 한마디는 까닭이 아니에요.","듣는 친구가 읽고 싶어지게."],"asset":{"type":"speech","turns":[{"who":"가은","text":"이 책은 「모자를 쫓는 곰」이야."},{"who":"가은","text":"곰이 모자만 보고 달리다 연못에 빠지는 장면이 웃겨서 너도 좋아할 것 같아."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_challenge#5','kor',1,2,'u5','L06','g1_2_kor_u5_L06_challenge','lesson_challenge','K1-2-u5-C4',3,'error','auto','책에서 느끼는 재미를 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_challenge#6','kor',1,2,'u5','L06','g1_2_kor_u5_L06_challenge','lesson_challenge','K1-2-u5-C4',3,'ox','auto','친구가 재미있다고 한 부분이 나와 다르면 친구가 잘못 읽은 것이에요.',ARRAY['K1-2-u5-X11']::text[],true,'{"seq":6,"concept":"K1-2-u5-C4","difficulty":3,"kind":"ox","stem":"친구가 재미있다고 한 부분이 나와 다르면 친구가 잘못 읽은 것이에요.","answer":"X","reason_options":[{"t":"사람마다 재미있는 부분이 다를 수 있으니까","correct":true},{"t":"같은 책을 읽었으니 재미있는 부분도 같아야 하니까","mis":"K1-2-u5-X11"}],"mis":"K1-2-u5-X11","explanation":["같은 책도 마음이 움직이는 곳은 달라요.","틀린 것이 아니라 다른 거예요.","왜 그 부분인지 물어봐요."],"variant_rule":{"alt":[{"stem":"윤슬이가 소율이에게 한 말은 알맞아요.","answer":"X","reason_options":[{"t":"다른 부분을 좋아한 것은 잘못 고른 것이 아니니까","correct":true},{"t":"책을 덮는 부분이 가장 중요하니까","mis":"K1-2-u5-X11"}],"explanation":["소율이는 잘못 고르지 않았어요.","사람마다 좋은 부분이 달라요.","「왜 좋았어?」 하고 물으면 돼요."],"asset":{"type":"speech","turns":[{"who":"소율","text":"나는 강아지가 할아버지 곁을 지키는 부분이 좋았어."},{"who":"윤슬","text":"그건 잘못 고른 거야. 책을 덮는 부분이 제일이야."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_challenge#7','kor',1,2,'u5','L06','g1_2_kor_u5_L06_challenge','lesson_challenge','K1-2-u5-C4',3,'mc','auto','「박쥐가 나오는 책」에서 예준이가 책의 재미를 다른 사람과 나눈 일은 어느 것인가요?',ARRAY['K1-2-u5-X13']::text[],true,'{"seq":7,"concept":"K1-2-u5-C4","difficulty":3,"kind":"mc","stem":"「박쥐가 나오는 책」에서 예준이가 책의 재미를 다른 사람과 나눈 일은 어느 것인가요?","options":[{"t":"동생에게 박쥐 이야기를 들려주었다","correct":true},{"t":"수업 종이 울린 것도 몰랐다","mis":"K1-2-u5-X13"},{"t":"도서관에서 책을 골랐다","mis":"K1-2-u5-X13"}],"explanation":["알게 된 것을 동생에게 들려준 것이 나눈 일이에요.","종을 몰랐던 것, 책을 고른 것은 혼자 한 일이에요.","다른 사람이 나오는 줄을 찾아요."],"asset":{"type":"passage","lines":["쉬는 시간에 예준이는 도서관에서 동굴 그림이 있는 책을 골랐다.","책에는 박쥐가 거꾸로 매달려 잠을 잔다고 적혀 있었다.","예준이는 \"우아, 처음 알았어!\" 하고 말했다.","책장을 넘기다 보니 수업 종이 울린 것도 몰랐다.","집에 간 예준이는 동생에게 박쥐 이야기를 들려주었다."],"title":"「박쥐가 나오는 책」"},"variant_rule":{"alt":[{"stem":"「모자를 쫓는 곰」에서 윤슬이가 책의 재미를 다른 사람과 나눈 일은 어느 것인가요?","options":[{"t":"웃긴 장면을 짝에게 읽어 주었다","correct":true},{"t":"배를 잡고 깔깔 웃었다","mis":"K1-2-u5-X13"},{"t":"곰이 나오는 책을 읽었다","mis":"K1-2-u5-X13"}],"explanation":["짝에게 읽어 준 것이 나눈 일이에요.","웃은 것, 읽은 것은 혼자 한 일이에요.","다른 사람이 나오는 줄을 찾아요."],"asset":{"type":"passage","lines":["윤슬이는 바람에 날아간 모자를 쫓는 곰이 나오는 책을 읽었다.","곰은 모자만 보고 달리다가 연못에 풍덩 빠졌다.","윤슬이는 배를 잡고 깔깔 웃었다.","윤슬이는 그 장면을 짝에게 소리 내어 읽어 주었다."],"title":"「모자를 쫓는 곰」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_challenge#8','kor',1,2,'u5','L06','g1_2_kor_u5_L06_challenge','lesson_challenge','K1-2-u5-C4',4,'sa','auto','「박쥐가 나오는 책」에서 예준이가 알게 된 것을 글에서 찾아 빈칸에 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_challenge#9','kor',1,2,'u5','L06','g1_2_kor_u5_L06_challenge','lesson_challenge','K1-2-u5-C4',4,'essay','teacher','「늙은 강아지 이야기」를 친구에게 추천하는 말을 써 보세요. 책 제목과 추천하는 까닭이 들어가게 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u5-C4","difficulty":4,"kind":"essay","stem":"「늙은 강아지 이야기」를 친구에게 추천하는 말을 써 보세요. 책 제목과 추천하는 까닭이 들어가게 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 이 책은 「늙은 강아지 이야기」야. 아픈 강아지가 할아버지 곁을 끝까지 지키는 장면이 뭉클해서 추천해. — 제목과 까닭이 있으면 맞아요.","scoring_points":["책 제목이 있는가","추천하는 까닭이 있는가","까닭이 책의 내용(장면·재미)에서 왔는가"]},"explanation":["제목 + 까닭.","까닭은 장면이나 재미에서.","듣는 친구가 읽고 싶어지게."],"asset":{"type":"passage","lines":["채윤이는 할아버지와 늙은 강아지가 나오는 책을 읽었다.","강아지는 다리가 아파도 할아버지 곁을 떠나지 않았다.","그 장면에서 채윤이는 코끝이 찡했다.","책을 덮은 채윤이는 집에 있는 강아지를 꼭 안아 주었다."],"title":"「늙은 강아지 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L06_challenge#10','kor',1,2,'u5','L06','g1_2_kor_u5_L06_challenge','lesson_challenge','K1-2-u5-C4',4,'essay','teacher','내가 읽은 책 가운데 재미있었던 부분 하나를 고르고, 왜 재미있었는지 까닭과 함께 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u5-C4","difficulty":4,"kind":"essay","stem":"내가 읽은 책 가운데 재미있었던 부분 하나를 고르고, 왜 재미있었는지 까닭과 함께 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 「모자를 쫓는 곰」에서 곰이 연못에 빠지는 부분이 재미있었다. 모자만 보고 달리다 빠지는 모습이 우스웠기 때문이다. — 부분 하나와 까닭이 있으면 맞아요(어떤 책이든 좋아요).","scoring_points":["어느 부분인지 있는가","왜 재미있었는지 까닭이 있는가","웃음·뭉클함·새로 앎 등 내 느낌으로 썼는가"]},"explanation":["어느 부분 + 왜.","어떤 책이든 좋아요.","내 말로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_basic#1','kor',1,2,'u5','L08','g1_2_kor_u5_L08_basic','lesson_basic','K1-2-u5-C5',1,'mc','auto','「강낭콩 화분」에서 가은이가 맡은 일은 무엇인가요?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":1,"concept":"K1-2-u5-C5","difficulty":1,"kind":"mc","stem":"「강낭콩 화분」에서 가은이가 맡은 일은 무엇인가요?","options":[{"t":"물 주는 당번","correct":true},{"t":"화분을 사 오는 당번","mis":"K1-2-u5-X13"},{"t":"꽃을 그리는 당번","mis":"K1-2-u5-X13"}],"explanation":["「나는 물 주는 당번이 되었다」고 했어요.","화분을 사 오거나 꽃을 그린 일은 글에 없어요.","「나는」으로 시작하는 줄을 찾아요."],"asset":{"type":"passage","lines":["우리 반 창가에 강낭콩 화분이 놓였다.","나는 물 주는 당번이 되었다.","어느 날 깜빡하고 물을 주지 않았다.","잎이 축 처진 것을 보고 가슴이 철렁했다.","그날부터 나는 달력에 물 준 날을 표시했다.","두 주일 뒤, 줄기 끝에 작은 꽃이 피었다.","나도 모르게 웃음이 났다."],"title":"「강낭콩 화분」 — 가은이가 쓴 글(「나」는 가은)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_basic#2','kor',1,2,'u5','L08','g1_2_kor_u5_L08_basic','lesson_basic','K1-2-u5-C5',1,'mc','auto','잎이 축 처진 것을 본 가은이의 마음을 알려 주는 말은 어느 것인가요?',ARRAY['K1-2-u5-X14']::text[],false,'{"seq":2,"concept":"K1-2-u5-C5","difficulty":1,"kind":"mc","stem":"잎이 축 처진 것을 본 가은이의 마음을 알려 주는 말은 어느 것인가요?","options":[{"t":"가슴이 철렁했다","correct":true},{"t":"달력에 물 준 날을 표시했다","mis":"K1-2-u5-X14"},{"t":"창가에 화분이 놓였다","mis":"K1-2-u5-X14"}],"explanation":["「가슴이 철렁했다」는 깜짝 놀라고 걱정되는 마음이에요.","달력 표시는 한 일, 화분이 놓인 것은 있었던 일이에요.","몸이 어떻게 되었다는 말을 찾아요."],"asset":{"type":"passage","lines":["우리 반 창가에 강낭콩 화분이 놓였다.","나는 물 주는 당번이 되었다.","어느 날 깜빡하고 물을 주지 않았다.","잎이 축 처진 것을 보고 가슴이 철렁했다.","그날부터 나는 달력에 물 준 날을 표시했다.","두 주일 뒤, 줄기 끝에 작은 꽃이 피었다.","나도 모르게 웃음이 났다."],"title":"「강낭콩 화분」 — 가은이가 쓴 글(「나」는 가은)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_basic#3','kor',1,2,'u5','L08','g1_2_kor_u5_L08_basic','lesson_basic','K1-2-u5-C6',1,'mc','auto','글을 읽고 생각이나 느낌을 말하는 알맞은 방법은 어느 것인가요?',ARRAY['K1-2-u5-X15','K1-2-u5-X10']::text[],false,'{"seq":3,"concept":"K1-2-u5-C6","difficulty":1,"kind":"mc","stem":"글을 읽고 생각이나 느낌을 말하는 알맞은 방법은 어느 것인가요?","options":[{"t":"글을 읽고 내가 든 생각을 내 말로 말한다","correct":true},{"t":"글에 적힌 글쓴이의 말을 그대로 옮긴다","mis":"K1-2-u5-X15"},{"t":"「좋았다」 한마디로 끝낸다","mis":"K1-2-u5-X10"}],"explanation":["내 생각은 내 말로 말해요.","옮기거나 한마디로 끝내면 내 생각이 보이지 않아요.","어느 부분 때문인지도 함께."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_basic#4','kor',1,2,'u5','L08','g1_2_kor_u5_L08_basic','lesson_basic','K1-2-u5-C5',1,'mc','auto','「두발자전거」에서 태오가 처음에 겪은 일은 무엇인가요?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":4,"concept":"K1-2-u5-C5","difficulty":1,"kind":"mc","stem":"「두발자전거」에서 태오가 처음에 겪은 일은 무엇인가요?","options":[{"t":"자꾸 넘어져서 무릎이 까졌다","correct":true},{"t":"처음부터 혼자 끝까지 달렸다","mis":"K1-2-u5-X13"},{"t":"아빠가 대신 자전거를 탔다","mis":"K1-2-u5-X13"}],"explanation":["「처음에는 자꾸 넘어져서」라고 했어요.","혼자 달린 것은 세 번째 토요일 일이에요.","「처음에는」을 찾아요."],"asset":{"type":"passage","lines":["나는 토요일마다 아빠와 두발자전거를 연습했다.","처음에는 자꾸 넘어져서 무릎이 까졌다.","속이 상해서 눈물이 났다.","아빠가 \"발밑 말고 앞을 보고 달려 봐.\" 하고 말씀하셨다.","나는 먼 나무를 보며 페달을 밟았다.","세 번째 토요일, 나는 혼자 끝까지 달렸다.","바람이 얼굴에 닿자 가슴이 두근두근 뛰었다."],"title":"「두발자전거」 — 태오가 쓴 글(「나」는 태오)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_basic#5','kor',1,2,'u5','L08','g1_2_kor_u5_L08_basic','lesson_basic','K1-2-u5-C5',2,'match','auto','「강낭콩 화분」에서 차례와 가은이가 한 일을 선으로 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K1-2-u5-C5","difficulty":2,"kind":"match","stem":"「강낭콩 화분」에서 차례와 가은이가 한 일을 선으로 이어 보세요.","pairs":[{"l":"첫째","r":"물 주는 당번이 되었다"},{"l":"둘째","r":"깜빡하고 물을 주지 않았다"},{"l":"셋째","r":"달력에 물 준 날을 표시했다"}],"mis":"K1-2-u5-X13","explanation":["당번이 되고, 깜빡하고, 표시했어요.","「어느 날」, 「그날부터」가 차례를 알려 줘요.","글의 줄 차례를 따라가요."],"asset":{"type":"passage","lines":["우리 반 창가에 강낭콩 화분이 놓였다.","나는 물 주는 당번이 되었다.","어느 날 깜빡하고 물을 주지 않았다.","잎이 축 처진 것을 보고 가슴이 철렁했다.","그날부터 나는 달력에 물 준 날을 표시했다.","두 주일 뒤, 줄기 끝에 작은 꽃이 피었다.","나도 모르게 웃음이 났다."],"title":"「강낭콩 화분」 — 가은이가 쓴 글(「나」는 가은)"},"variant_rule":{"alt":[{"stem":"「두발자전거」에서 차례와 태오가 한 일을 선으로 이어 보세요.","pairs":[{"l":"첫째","r":"넘어져서 무릎이 까졌다"},{"l":"둘째","r":"먼 나무를 보며 페달을 밟았다"},{"l":"셋째","r":"혼자 끝까지 달렸다"}],"explanation":["넘어지고, 앞을 보고, 혼자 달렸어요.","「처음에는」, 「세 번째 토요일」이 차례를 알려 줘요.","글의 줄 차례를 따라가요."],"asset":{"type":"passage","lines":["나는 토요일마다 아빠와 두발자전거를 연습했다.","처음에는 자꾸 넘어져서 무릎이 까졌다.","속이 상해서 눈물이 났다.","아빠가 \"발밑 말고 앞을 보고 달려 봐.\" 하고 말씀하셨다.","나는 먼 나무를 보며 페달을 밟았다.","세 번째 토요일, 나는 혼자 끝까지 달렸다.","바람이 얼굴에 닿자 가슴이 두근두근 뛰었다."],"title":"「두발자전거」 — 태오가 쓴 글(「나」는 태오)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_basic#6','kor',1,2,'u5','L08','g1_2_kor_u5_L08_basic','lesson_basic','K1-2-u5-C5',2,'mc','auto','마지막 줄 「나도 모르게 웃음이 났다」에서 알 수 있는 가은이의 마음은 어느 것인가요?',ARRAY['K1-2-u5-X14']::text[],true,'{"seq":6,"concept":"K1-2-u5-C5","difficulty":2,"kind":"mc","stem":"마지막 줄 「나도 모르게 웃음이 났다」에서 알 수 있는 가은이의 마음은 어느 것인가요?","options":[{"t":"꽃이 피어 기쁜 마음","correct":true},{"t":"물을 못 줘서 미안한 마음","mis":"K1-2-u5-X14"},{"t":"화분이 귀찮은 마음","mis":"K1-2-u5-X14"}],"explanation":["꽃이 핀 것을 보고 웃음이 났어요.","미안한 마음은 앞의 일이고, 귀찮다는 말은 없어요.","웃음은 기쁠 때 나와요."],"asset":{"type":"passage","lines":["우리 반 창가에 강낭콩 화분이 놓였다.","나는 물 주는 당번이 되었다.","어느 날 깜빡하고 물을 주지 않았다.","잎이 축 처진 것을 보고 가슴이 철렁했다.","그날부터 나는 달력에 물 준 날을 표시했다.","두 주일 뒤, 줄기 끝에 작은 꽃이 피었다.","나도 모르게 웃음이 났다."],"title":"「강낭콩 화분」 — 가은이가 쓴 글(「나」는 가은)"},"variant_rule":{"alt":[{"stem":"「가슴이 두근두근 뛰었다」에서 알 수 있는 태오의 마음은 어느 것인가요?","options":[{"t":"혼자 달려서 신나고 설레는 마음","correct":true},{"t":"넘어질까 봐 화난 마음","mis":"K1-2-u5-X14"},{"t":"아빠에게 서운한 마음","mis":"K1-2-u5-X14"}],"explanation":["혼자 끝까지 달려서 가슴이 뛰었어요.","화나거나 서운하다는 말은 없어요.","바로 앞 일과 함께 봐요."],"asset":{"type":"passage","lines":["나는 토요일마다 아빠와 두발자전거를 연습했다.","처음에는 자꾸 넘어져서 무릎이 까졌다.","속이 상해서 눈물이 났다.","아빠가 \"발밑 말고 앞을 보고 달려 봐.\" 하고 말씀하셨다.","나는 먼 나무를 보며 페달을 밟았다.","세 번째 토요일, 나는 혼자 끝까지 달렸다.","바람이 얼굴에 닿자 가슴이 두근두근 뛰었다."],"title":"「두발자전거」 — 태오가 쓴 글(「나」는 태오)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_basic#7','kor',1,2,'u5','L08','g1_2_kor_u5_L08_basic','lesson_basic','K1-2-u5-C6',2,'mc','auto','「강낭콩 화분」을 읽고 생각이나 느낌을 말한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u5-X10','K1-2-u5-X15']::text[],false,'{"seq":7,"concept":"K1-2-u5-C6","difficulty":2,"kind":"mc","stem":"「강낭콩 화분」을 읽고 생각이나 느낌을 말한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"물 준 날을 달력에 표시한 것이 참 꼼꼼해 보였다.","correct":true},{"t":"좋았다.","mis":"K1-2-u5-X10"},{"t":"우리 반 창가에 강낭콩 화분이 놓였다.","mis":"K1-2-u5-X15"}],"explanation":["어느 부분 때문인지와 내 생각이 함께 있어요.","「좋았다」는 까닭이 없고, 셋째는 글을 옮긴 거예요.","「~해 보였다」로 내 생각을 말해요."],"asset":{"type":"passage","lines":["우리 반 창가에 강낭콩 화분이 놓였다.","나는 물 주는 당번이 되었다.","어느 날 깜빡하고 물을 주지 않았다.","잎이 축 처진 것을 보고 가슴이 철렁했다.","그날부터 나는 달력에 물 준 날을 표시했다.","두 주일 뒤, 줄기 끝에 작은 꽃이 피었다.","나도 모르게 웃음이 났다."],"title":"「강낭콩 화분」 — 가은이가 쓴 글(「나」는 가은)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_basic#8','kor',1,2,'u5','L08','g1_2_kor_u5_L08_basic','lesson_basic','K1-2-u5-C6',2,'ox','auto','생각이나 느낌을 말할 때에는 글의 어느 부분 때문인지 함께 말하면 좋아요.',ARRAY['K1-2-u5-X10']::text[],false,'{"seq":8,"concept":"K1-2-u5-C6","difficulty":2,"kind":"ox","stem":"생각이나 느낌을 말할 때에는 글의 어느 부분 때문인지 함께 말하면 좋아요.","answer":"O","reason_options":[{"t":"어느 부분 때문인지 알아야 내 생각이 잘 전해지니까","correct":true},{"t":"말이 길어야 잘한 것이니까","mis":"K1-2-u5-X10"}],"mis":"K1-2-u5-X10","explanation":["어느 부분 때문인지 함께 말해요.","길이가 아니라 까닭이 중요해요.","「~한 것이 ~해 보였어」."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_basic#9','kor',1,2,'u5','L08','g1_2_kor_u5_L08_basic','lesson_basic','K1-2-u5-C5',2,'mc','auto','「두발자전거」에서 아빠가 해 주신 말은 어느 것인가요?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":9,"concept":"K1-2-u5-C5","difficulty":2,"kind":"mc","stem":"「두발자전거」에서 아빠가 해 주신 말은 어느 것인가요?","options":[{"t":"발밑 말고 앞을 보고 달려 봐.","correct":true},{"t":"넘어지면 그만 타자.","mis":"K1-2-u5-X13"},{"t":"무릎이 까졌으니 쉬자.","mis":"K1-2-u5-X13"}],"explanation":["아빠는 앞을 보고 달리라고 알려 주셨어요.","그만 타자, 쉬자는 말은 글에 없어요.","큰따옴표 안의 말을 봐요."],"asset":{"type":"passage","lines":["나는 토요일마다 아빠와 두발자전거를 연습했다.","처음에는 자꾸 넘어져서 무릎이 까졌다.","속이 상해서 눈물이 났다.","아빠가 \"발밑 말고 앞을 보고 달려 봐.\" 하고 말씀하셨다.","나는 먼 나무를 보며 페달을 밟았다.","세 번째 토요일, 나는 혼자 끝까지 달렸다.","바람이 얼굴에 닿자 가슴이 두근두근 뛰었다."],"title":"「두발자전거」 — 태오가 쓴 글(「나」는 태오)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_basic#10','kor',1,2,'u5','L08','g1_2_kor_u5_L08_basic','lesson_basic','K1-2-u5-C6',3,'error','auto','「강낭콩 화분」과 비슷한 경험을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_challenge#1','kor',1,2,'u5','L08','g1_2_kor_u5_L08_challenge','lesson_challenge','K1-2-u5-C5',2,'mc','auto','「할머니께 쓴 편지」에서 소율이가 처음 쓴 편지는 어땠나요?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":1,"concept":"K1-2-u5-C5","difficulty":2,"kind":"mc","stem":"「할머니께 쓴 편지」에서 소율이가 처음 쓴 편지는 어땠나요?","options":[{"t":"글씨가 삐뚤빼뚤했다","correct":true},{"t":"글씨가 아주 반듯했다","mis":"K1-2-u5-X13"},{"t":"할머니께서 대신 써 주셨다","mis":"K1-2-u5-X13"}],"explanation":["「처음 쓴 편지는 글씨가 삐뚤빼뚤했다」예요.","반듯했다거나 대신 썼다는 말은 없어요.","둘째 줄을 봐요."],"asset":{"type":"passage","lines":["할머니 생신이 다가와서 나는 편지를 쓰기로 했다.","처음 쓴 편지는 글씨가 삐뚤빼뚤했다.","다시 읽어 보니 조금 창피했다.","나는 연필을 바르게 쥐고 한 글자씩 천천히 다시 썼다.","할머니께서 편지를 읽으시고 내 손을 꼭 잡아 주셨다.","내 마음이 할머니께 닿은 것 같아 뿌듯했다."],"title":"「할머니께 쓴 편지」 — 소율이가 쓴 글(「나」는 소율)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_challenge#2','kor',1,2,'u5','L08','g1_2_kor_u5_L08_challenge','lesson_challenge','K1-2-u5-C6',2,'mc','auto','윤슬이의 말이 윤슬이의 생각이 아닌 까닭은 무엇인가요?',ARRAY['K1-2-u5-X10']::text[],false,'{"seq":2,"concept":"K1-2-u5-C6","difficulty":2,"kind":"mc","stem":"윤슬이의 말이 윤슬이의 생각이 아닌 까닭은 무엇인가요?","options":[{"t":"글에 적힌 문장을 그대로 옮겨 말했기 때문에","correct":true},{"t":"말이 너무 짧았기 때문에","mis":"K1-2-u5-X10"},{"t":"목소리가 작았기 때문에","mis":"K1-2-u5-X10"}],"explanation":["윤슬이는 글의 마지막 줄을 그대로 말했어요.","짧거나 목소리가 작아서가 아니에요.","그 말을 읽고 든 내 마음을 말해요."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"「두발자전거」를 읽고 어떤 생각이 들었나요?"},{"who":"윤슬","text":"바람이 얼굴에 닿자 가슴이 두근두근 뛰었다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_challenge#3','kor',1,2,'u5','L08','g1_2_kor_u5_L08_challenge','lesson_challenge','K1-2-u5-C5',3,'mc','auto','소율이의 마음이 「창피했다」에서 「뿌듯했다」로 바뀐 까닭은 무엇인가요?',ARRAY['K1-2-u5-X13']::text[],true,'{"seq":3,"concept":"K1-2-u5-C5","difficulty":3,"kind":"mc","stem":"소율이의 마음이 「창피했다」에서 「뿌듯했다」로 바뀐 까닭은 무엇인가요?","options":[{"t":"천천히 다시 써서 할머니께 마음을 전했기 때문에","correct":true},{"t":"할머니께서 편지를 돌려주셨기 때문에","mis":"K1-2-u5-X13"},{"t":"편지를 쓰지 않기로 했기 때문에","mis":"K1-2-u5-X13"}],"explanation":["다시 쓴 편지에 할머니께서 손을 잡아 주셨어요.","돌려주거나 안 쓰기로 한 일은 없어요.","마음이 바뀐 사이의 일을 봐요."],"asset":{"type":"passage","lines":["할머니 생신이 다가와서 나는 편지를 쓰기로 했다.","처음 쓴 편지는 글씨가 삐뚤빼뚤했다.","다시 읽어 보니 조금 창피했다.","나는 연필을 바르게 쥐고 한 글자씩 천천히 다시 썼다.","할머니께서 편지를 읽으시고 내 손을 꼭 잡아 주셨다.","내 마음이 할머니께 닿은 것 같아 뿌듯했다."],"title":"「할머니께 쓴 편지」 — 소율이가 쓴 글(「나」는 소율)"},"variant_rule":{"alt":[{"stem":"하람이의 마음이 「짜증이 났다」에서 「어깨가 으쓱했다」로 바뀐 까닭은 무엇인가요?","options":[{"t":"형이 알려 준 대로 묶어 끈이 풀리지 않았기 때문에","correct":true},{"t":"형이 대신 끈을 묶어 주었기 때문에","mis":"K1-2-u5-X13"},{"t":"끈이 없는 신발을 신었기 때문에","mis":"K1-2-u5-X13"}],"explanation":["스스로 묶은 끈이 학교까지 풀리지 않았어요.","형은 방법만 알려 주었어요.","마음이 바뀐 사이의 일을 봐요."],"asset":{"type":"passage","lines":["나는 혼자 운동화 끈을 묶어 보기로 했다.","처음에는 끈이 자꾸 풀려서 짜증이 났다.","형이 \"고리를 두 개 만들어 봐.\" 하고 알려 주었다.","나는 고리 두 개를 만들어 천천히 엇갈려 묶었다.","다음 날 아침, 끈이 한 번도 풀리지 않고 학교까지 갔다.","신발을 내려다볼 때마다 어깨가 으쓱했다."],"title":"「운동화 끈」 — 하람이가 쓴 글(「나」는 하람)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_challenge#4','kor',1,2,'u5','L08','g1_2_kor_u5_L08_challenge','lesson_challenge','K1-2-u5-C6',3,'mc','auto','채윤이의 말이 생각을 잘 나눈 말인 까닭은 무엇인가요?',ARRAY['K1-2-u5-X15','K1-2-u5-X10']::text[],false,'{"seq":4,"concept":"K1-2-u5-C6","difficulty":3,"kind":"mc","stem":"채윤이의 말이 생각을 잘 나눈 말인 까닭은 무엇인가요?","options":[{"t":"어느 부분 때문인지와 비슷한 내 다짐을 함께 말했기 때문에","correct":true},{"t":"글의 문장을 그대로 옮겼기 때문에","mis":"K1-2-u5-X15"},{"t":"말이 길었기 때문에","mis":"K1-2-u5-X10"}],"explanation":["「세 번째 토요일까지 연습한 것」이라는 부분과 내 다짐이 있어요.","옮긴 말이 아니에요. 길이도 상관없어요.","어느 부분 + 내 생각."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"「두발자전거」를 읽고 어떤 생각이 들었나요?"},{"who":"채윤","text":"눈물이 나도 세 번째 토요일까지 연습한 것이 대단해 보였어요. 나도 줄넘기를 그만두지 말아야겠어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_challenge#5','kor',1,2,'u5','L08','g1_2_kor_u5_L08_challenge','lesson_challenge','K1-2-u5-C5',3,'error','auto','「두발자전거」에서 태오가 한 일을 차례대로 늘어놓았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_challenge#6','kor',1,2,'u5','L08','g1_2_kor_u5_L08_challenge','lesson_challenge','K1-2-u5-C5',3,'ox','auto','「속이 상해서 눈물이 났다」에서 태오가 속상했다는 것을 알 수 있어요.',ARRAY['K1-2-u5-X14']::text[],true,'{"seq":6,"concept":"K1-2-u5-C5","difficulty":3,"kind":"ox","stem":"「속이 상해서 눈물이 났다」에서 태오가 속상했다는 것을 알 수 있어요.","answer":"O","reason_options":[{"t":"「속이 상해서」, 「눈물이 났다」가 마음을 알려 주는 말이니까","correct":true},{"t":"무릎이 까지면 누구나 우니까","mis":"K1-2-u5-X14"}],"mis":"K1-2-u5-X14","explanation":["마음을 알려 주는 말이 글에 있어요.","누구나 그렇다고 짐작하는 것이 아니라 글에서 찾아요.","몸과 얼굴이 어떻게 되었는지 봐요."],"asset":{"type":"passage","lines":["나는 토요일마다 아빠와 두발자전거를 연습했다.","처음에는 자꾸 넘어져서 무릎이 까졌다.","속이 상해서 눈물이 났다.","아빠가 \"발밑 말고 앞을 보고 달려 봐.\" 하고 말씀하셨다.","나는 먼 나무를 보며 페달을 밟았다.","세 번째 토요일, 나는 혼자 끝까지 달렸다.","바람이 얼굴에 닿자 가슴이 두근두근 뛰었다."],"title":"「두발자전거」 — 태오가 쓴 글(「나」는 태오)"},"variant_rule":{"alt":[{"stem":"「신발을 내려다볼 때마다 어깨가 으쓱했다」에서 하람이가 부끄러웠다는 것을 알 수 있어요.","answer":"X","reason_options":[{"t":"어깨가 으쓱한 것은 스스로 해내어 자랑스러운 마음이니까","correct":true},{"t":"신발을 내려다보면 부끄러운 것이니까","mis":"K1-2-u5-X14"}],"explanation":["「어깨가 으쓱했다」는 뿌듯한 마음이에요.","몸짓을 거꾸로 읽으면 안 돼요.","바로 앞 일과 함께 봐요."],"asset":{"type":"passage","lines":["나는 혼자 운동화 끈을 묶어 보기로 했다.","처음에는 끈이 자꾸 풀려서 짜증이 났다.","형이 \"고리를 두 개 만들어 봐.\" 하고 알려 주었다.","나는 고리 두 개를 만들어 천천히 엇갈려 묶었다.","다음 날 아침, 끈이 한 번도 풀리지 않고 학교까지 갔다.","신발을 내려다볼 때마다 어깨가 으쓱했다."],"title":"「운동화 끈」 — 하람이가 쓴 글(「나」는 하람)"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_challenge#7','kor',1,2,'u5','L08','g1_2_kor_u5_L08_challenge','lesson_challenge','K1-2-u5-C6',3,'mc','auto','「할머니께 쓴 편지」와 비슷한 경험으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u5-X16']::text[],false,'{"seq":7,"concept":"K1-2-u5-C6","difficulty":3,"kind":"mc","stem":"「할머니께 쓴 편지」와 비슷한 경험으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"처음엔 서툴렀지만 다시 해서 마음을 전했던 일","correct":true},{"t":"할머니 댁 가는 길에 본 간판","mis":"K1-2-u5-X16"},{"t":"편지 봉투 색깔을 고른 일","mis":"K1-2-u5-X16"}],"explanation":["서툴렀다가 다시 해서 마음을 전한 일과 마음이 닮았어요.","편지가 나와도 일과 마음이 닮지 않으면 비슷한 경험이 아니에요.","무슨 일, 어떤 마음을 견주어요."],"asset":{"type":"passage","lines":["할머니 생신이 다가와서 나는 편지를 쓰기로 했다.","처음 쓴 편지는 글씨가 삐뚤빼뚤했다.","다시 읽어 보니 조금 창피했다.","나는 연필을 바르게 쥐고 한 글자씩 천천히 다시 썼다.","할머니께서 편지를 읽으시고 내 손을 꼭 잡아 주셨다.","내 마음이 할머니께 닿은 것 같아 뿌듯했다."],"title":"「할머니께 쓴 편지」 — 소율이가 쓴 글(「나」는 소율)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_challenge#8','kor',1,2,'u5','L08','g1_2_kor_u5_L08_challenge','lesson_challenge','K1-2-u5-C5',4,'sa','auto','「강낭콩 화분」에서 가은이가 물을 깜빡하지 않으려고 한 일을 찾아 빈칸에 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_challenge#9','kor',1,2,'u5','L08','g1_2_kor_u5_L08_challenge','lesson_challenge','K1-2-u5-C6',4,'essay','teacher','「두발자전거」를 읽고 태오에게 하고 싶은 말을 쓰세요. 글의 어느 부분 때문인지 함께 넣어 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u5-C6","difficulty":4,"kind":"essay","stem":"「두발자전거」를 읽고 태오에게 하고 싶은 말을 쓰세요. 글의 어느 부분 때문인지 함께 넣어 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 태오야, 눈물이 나도 세 번째 토요일까지 연습한 것이 대단해 보였어. 나도 줄넘기를 끝까지 연습해 볼래. — 글의 한 부분과 내 생각이 있으면 맞아요(어느 부분을 골라도 좋아요).","scoring_points":["글의 어느 부분인지 있는가","그 부분에 대한 내 생각이 있는가","글을 옮기지 않고 내 말로 썼는가"]},"explanation":["어느 부분 + 내 생각.","정해진 답은 없어요.","「~한 것이 ~해 보였어」."],"asset":{"type":"passage","lines":["나는 토요일마다 아빠와 두발자전거를 연습했다.","처음에는 자꾸 넘어져서 무릎이 까졌다.","속이 상해서 눈물이 났다.","아빠가 \"발밑 말고 앞을 보고 달려 봐.\" 하고 말씀하셨다.","나는 먼 나무를 보며 페달을 밟았다.","세 번째 토요일, 나는 혼자 끝까지 달렸다.","바람이 얼굴에 닿자 가슴이 두근두근 뛰었다."],"title":"「두발자전거」 — 태오가 쓴 글(「나」는 태오)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L08_challenge#10','kor',1,2,'u5','L08','g1_2_kor_u5_L08_challenge','lesson_challenge','K1-2-u5-C6',4,'essay','teacher','「할머니께 쓴 편지」를 읽고 떠오른 비슷한 내 경험을 한 가지 쓰고, 그때 내 마음이 어땠는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u5-C6","difficulty":4,"kind":"essay","stem":"「할머니께 쓴 편지」를 읽고 떠오른 비슷한 내 경험을 한 가지 쓰고, 그때 내 마음이 어땠는지 쓰세요.","answer_guide":{"answer":"예: 나도 처음 줄넘기를 할 때 자꾸 걸려서 창피했다. 그래도 계속 연습해서 열 번을 넘었을 때 뿌듯했다. — 소율이와 일이나 마음이 닮은 경험과 그때 마음이 있으면 맞아요.","scoring_points":["내 경험이 있는가","소율이와 일이나 마음이 닮았는가","그때 마음을 썼는가"]},"explanation":["편지가 아니어도 돼요.","서툴다가 해낸 일, 마음을 전한 일.","그때 마음도 함께."],"asset":{"type":"passage","lines":["할머니 생신이 다가와서 나는 편지를 쓰기로 했다.","처음 쓴 편지는 글씨가 삐뚤빼뚤했다.","다시 읽어 보니 조금 창피했다.","나는 연필을 바르게 쥐고 한 글자씩 천천히 다시 썼다.","할머니께서 편지를 읽으시고 내 손을 꼭 잡아 주셨다.","내 마음이 할머니께 닿은 것 같아 뿌듯했다."],"title":"「할머니께 쓴 편지」 — 소율이가 쓴 글(「나」는 소율)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_basic#1','kor',1,2,'u5','L10','g1_2_kor_u5_L10_basic','lesson_basic','K1-2-u5-C7',1,'mc','auto','독서 계획을 세우는 세 걸음 가운데 첫째 걸음은 무엇인가요?',ARRAY['K1-2-u5-X17']::text[],false,'{"seq":1,"concept":"K1-2-u5-C7","difficulty":1,"kind":"mc","stem":"독서 계획을 세우는 세 걸음 가운데 첫째 걸음은 무엇인가요?","options":[{"t":"읽고 싶은 책 고르기","correct":true},{"t":"한 권씩 끝까지 읽기","mis":"K1-2-u5-X17"},{"t":"다 읽은 칸 색칠하기","mis":"K1-2-u5-X17"}],"explanation":["먼저 읽고 싶은 책을 골라요.","고르기 → 차례 정하기 → 끝까지 읽기예요.","책이 있어야 계획을 세워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_basic#2','kor',1,2,'u5','L10','g1_2_kor_u5_L10_basic','lesson_basic','K1-2-u5-C7',1,'mc','auto','계단 독서 계획표에서 가장 먼저 읽을 책은 어느 칸에 적나요?',ARRAY['K1-2-u5-X17']::text[],false,'{"seq":2,"concept":"K1-2-u5-C7","difficulty":1,"kind":"mc","stem":"계단 독서 계획표에서 가장 먼저 읽을 책은 어느 칸에 적나요?","options":[{"t":"맨 아래 칸","correct":true},{"t":"맨 위 칸","mis":"K1-2-u5-X17"},{"t":"아무 칸에나","mis":"K1-2-u5-X17"}],"explanation":["계단은 아래에서 위로 올라가요.","맨 아래 칸이 첫째예요.","다 읽으면 한 칸씩 올라가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_basic#3','kor',1,2,'u5','L10','g1_2_kor_u5_L10_basic','lesson_basic','K1-2-u5-C7',1,'mc','auto','책을 읽는 알맞은 방법은 어느 것인가요?',ARRAY['K1-2-u5-X19']::text[],false,'{"seq":3,"concept":"K1-2-u5-C7","difficulty":1,"kind":"mc","stem":"책을 읽는 알맞은 방법은 어느 것인가요?","options":[{"t":"한 권을 처음부터 끝까지 읽는다","correct":true},{"t":"여러 권을 조금씩 건너뛰며 넘긴다","mis":"K1-2-u5-X19"},{"t":"그림만 보고 넘긴다","mis":"K1-2-u5-X19"}],"explanation":["한 권을 끝까지 읽어야 이야기가 이어져요.","건너뛰면 무슨 이야기인지 알 수 없어요.","다 읽으면 칸을 색칠해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_basic#4','kor',1,2,'u5','L10','g1_2_kor_u5_L10_basic','lesson_basic','K1-2-u5-C7',1,'mc','auto','가은이의 계획표에서 가은이가 다 읽은 책은 어느 것인가요?',ARRAY['K1-2-u5-X17']::text[],false,'{"seq":4,"concept":"K1-2-u5-C7","difficulty":1,"kind":"mc","stem":"가은이의 계획표에서 가은이가 다 읽은 책은 어느 것인가요?","options":[{"t":"「꼬마 기차 뿡뿡」","correct":true},{"t":"「바닷속 친구들」","mis":"K1-2-u5-X17"},{"t":"「우주로 간 고양이」","mis":"K1-2-u5-X17"}],"explanation":["맨 아래 칸 「꼬마 기차 뿡뿡」이 색칠되어 있어요.","나머지는 아직 읽을 책이에요.","「다 읽어서 색칠함」을 찾아요."],"asset":{"type":"passage","lines":["③ 맨 위 칸 — 「바닷속 친구들」","② 가운데 칸 — 「우주로 간 고양이」","① 맨 아래 칸 — 「꼬마 기차 뿡뿡」 (다 읽어서 색칠함)"],"title":"가은이의 계단 독서 계획표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_basic#5','kor',1,2,'u5','L10','g1_2_kor_u5_L10_basic','lesson_basic','K1-2-u5-C7',2,'mc','auto','가은이가 다음에 읽을 책은 어느 것인가요?',ARRAY['K1-2-u5-X17','K1-2-u5-X19']::text[],false,'{"seq":5,"concept":"K1-2-u5-C7","difficulty":2,"kind":"mc","stem":"가은이가 다음에 읽을 책은 어느 것인가요?","options":[{"t":"「우주로 간 고양이」","correct":true},{"t":"「바닷속 친구들」","mis":"K1-2-u5-X17"},{"t":"「꼬마 기차 뿡뿡」","mis":"K1-2-u5-X19"}],"explanation":["첫 칸을 다 읽었으니 가운데 칸으로 올라가요.","맨 위 칸은 가장 나중이고, 첫 칸은 다 읽었어요.","한 칸씩 올라가요."],"asset":{"type":"passage","lines":["③ 맨 위 칸 — 「바닷속 친구들」","② 가운데 칸 — 「우주로 간 고양이」","① 맨 아래 칸 — 「꼬마 기차 뿡뿡」 (다 읽어서 색칠함)"],"title":"가은이의 계단 독서 계획표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_basic#6','kor',1,2,'u5','L10','g1_2_kor_u5_L10_basic','lesson_basic','K1-2-u5-C7',2,'mc','auto','계단 맨 아래 첫 칸에 놓으면 좋은 책은 어느 것인가요?',ARRAY['K1-2-u5-X17','K1-2-u5-X08']::text[],false,'{"seq":6,"concept":"K1-2-u5-C7","difficulty":2,"kind":"mc","stem":"계단 맨 아래 첫 칸에 놓으면 좋은 책은 어느 것인가요?","options":[{"t":"가장 읽고 싶고 읽기 쉬운 책","correct":true},{"t":"가장 어렵고 긴 책","mis":"K1-2-u5-X17"},{"t":"가장 무거운 책","mis":"K1-2-u5-X08"}],"explanation":["첫 책을 끝까지 읽으면 다음 책도 읽고 싶어져요.","어렵거나 무거운 책은 첫 칸에 맞지 않아요.","처음엔 쉽고 재미있게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_basic#7','kor',1,2,'u5','L10','g1_2_kor_u5_L10_basic','lesson_basic','K1-2-u5-C7',2,'ox','auto','독서 계획은 친구보다 많이 읽었는지 겨루려고 세워요.',ARRAY['K1-2-u5-X18']::text[],false,'{"seq":7,"concept":"K1-2-u5-C7","difficulty":2,"kind":"ox","stem":"독서 계획은 친구보다 많이 읽었는지 겨루려고 세워요.","answer":"X","reason_options":[{"t":"계획은 내가 꾸준히 읽어 가려고 세우는 것이니까","correct":true},{"t":"권수가 많아야 잘 읽은 것이니까","mis":"K1-2-u5-X18"}],"mis":"K1-2-u5-X18","explanation":["계획은 겨루기가 아니에요.","나만의 계단을 한 칸씩 올라가요.","권수보다 끝까지 읽기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_basic#8','kor',1,2,'u5','L10','g1_2_kor_u5_L10_basic','lesson_basic','K1-2-u5-C7',2,'match','auto','독서 계획 세 걸음을 차례대로 선으로 이어 보세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u5-C7","difficulty":2,"kind":"match","stem":"독서 계획 세 걸음을 차례대로 선으로 이어 보세요.","pairs":[{"l":"첫째","r":"읽고 싶은 책 고르기"},{"l":"둘째","r":"읽을 차례 정하기"},{"l":"셋째","r":"한 권씩 끝까지 읽기"}],"mis":"K1-2-u5-X17","explanation":["고르고, 차례를 정하고, 끝까지 읽어요.","차례가 바뀌면 계획이 되지 않아요.","세 걸음을 소리 내어 말해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_basic#9','kor',1,2,'u5','L10','g1_2_kor_u5_L10_basic','lesson_basic','K1-2-u5-C7',2,'mc','auto','첫 책이 너무 어려워요. 어떻게 하면 좋을까요?',ARRAY['K1-2-u5-X19']::text[],false,'{"seq":9,"concept":"K1-2-u5-C7","difficulty":2,"kind":"mc","stem":"첫 책이 너무 어려워요. 어떻게 하면 좋을까요?","options":[{"t":"읽을 수 있는 책으로 바꾸어 이어 간다","correct":true},{"t":"읽기를 그만둔다","mis":"K1-2-u5-X19"},{"t":"어려운 곳은 건너뛰며 넘긴다","mis":"K1-2-u5-X19"}],"explanation":["계획은 고쳐도 좋아요.","그만두거나 건너뛰지 말고 이어 가요.","이어 가는 것이 더 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
