INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_challenge#1','kor',1,2,'u5','L10','g1_2_kor_u5_L10_challenge','lesson_challenge','K1-2-u5-C7',2,'mc','auto','책을 다 읽은 뒤에 하면 좋은 것은 어느 것인가요?',ARRAY['K1-2-u5-X18','K1-2-u5-X19']::text[],false,'{"seq":1,"concept":"K1-2-u5-C7","difficulty":2,"kind":"mc","stem":"책을 다 읽은 뒤에 하면 좋은 것은 어느 것인가요?","options":[{"t":"기억에 남는 부분을 친구와 나눈다","correct":true},{"t":"읽은 권수만 세어 둔다","mis":"K1-2-u5-X18"},{"t":"다른 책을 건너뛰며 넘긴다","mis":"K1-2-u5-X19"}],"explanation":["나누면 책이 더 재미있어져요.","권수만 세거나 건너뛰지 않아요.","다 읽은 칸은 색칠해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_challenge#2','kor',1,2,'u5','L10','g1_2_kor_u5_L10_challenge','lesson_challenge','K1-2-u5-C7',2,'mc','auto','태오의 계획표에서 고치면 좋은 것은 어느 것인가요?',ARRAY['K1-2-u5-X17']::text[],false,'{"seq":2,"concept":"K1-2-u5-C7","difficulty":2,"kind":"mc","stem":"태오의 계획표에서 고치면 좋은 것은 어느 것인가요?","options":[{"t":"가장 두껍고 어려운 책을 맨 아래 첫 칸에 놓은 것","correct":true},{"t":"책 제목을 적은 것","mis":"K1-2-u5-X17"},{"t":"칸을 세 개 그린 것","mis":"K1-2-u5-X17"}],"explanation":["첫 칸에는 가장 읽고 싶고 쉬운 책을 놓아요.","제목을 적고 칸을 그린 것은 잘했어요.","맨 아래 칸을 봐요."],"asset":{"type":"passage","lines":["③ 맨 위 칸 — 「숲속 빵집」 (얇고 그림이 많은 책)","② 가운데 칸 — 「별빛 우체통」","① 맨 아래 칸 — 「공룡 큰 사전」 (가장 두껍고 어려운 책)"],"title":"태오의 계단 독서 계획표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_challenge#3','kor',1,2,'u5','L10','g1_2_kor_u5_L10_challenge','lesson_challenge','K1-2-u5-C7',3,'mc','auto','태오가 첫 칸 책을 끝까지 읽지 못하면 어떻게 될까요?',ARRAY['K1-2-u5-X17','K1-2-u5-X18']::text[],false,'{"seq":3,"concept":"K1-2-u5-C7","difficulty":3,"kind":"mc","stem":"태오가 첫 칸 책을 끝까지 읽지 못하면 어떻게 될까요?","options":[{"t":"다음 칸으로 올라가지 못해 읽기를 이어 가기 어렵다","correct":true},{"t":"더 빨리 위 칸으로 올라간다","mis":"K1-2-u5-X17"},{"t":"권수가 늘어 친구를 이긴다","mis":"K1-2-u5-X18"}],"explanation":["첫 칸을 다 읽어야 다음 칸으로 가요.","건너뛰거나 겨루는 것이 아니에요.","그래서 첫 칸이 중요해요."],"asset":{"type":"passage","lines":["③ 맨 위 칸 — 「숲속 빵집」 (얇고 그림이 많은 책)","② 가운데 칸 — 「별빛 우체통」","① 맨 아래 칸 — 「공룡 큰 사전」 (가장 두껍고 어려운 책)"],"title":"태오의 계단 독서 계획표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
