INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_challenge#5','kor',1,2,'u5','L10','g1_2_kor_u5_L10_challenge','lesson_challenge','K1-2-u5-C7',3,'ox','auto','독서 계획을 세운 뒤에는 한 번도 고치면 안 돼요.',ARRAY['K1-2-u5-X19']::text[],false,'{"seq":5,"concept":"K1-2-u5-C7","difficulty":3,"kind":"ox","stem":"독서 계획을 세운 뒤에는 한 번도 고치면 안 돼요.","answer":"X","reason_options":[{"t":"어긋나면 고쳐서라도 이어 가는 것이 더 중요하니까","correct":true},{"t":"계획은 처음 정한 대로만 해야 하니까","mis":"K1-2-u5-X19"}],"mis":"K1-2-u5-X19","explanation":["계획은 언제든 고쳐도 좋아요.","이어 가는 것이 더 중요해요.","어려우면 바꾸어서 계속."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_challenge#6','kor',1,2,'u5','L10','g1_2_kor_u5_L10_challenge','lesson_challenge','K1-2-u5-C7',3,'mc','auto','읽을 책을 고르는 기준으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u5-X08','K1-2-u5-X18']::text[],false,'{"seq":6,"concept":"K1-2-u5-C7","difficulty":3,"kind":"mc","stem":"읽을 책을 고르는 기준으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"내가 궁금해하는 것이 담긴 책","correct":true},{"t":"겉표지가 가장 두꺼운 책","mis":"K1-2-u5-X08"},{"t":"친구에게 이기려고 쪽수가 가장 적은 책","mis":"K1-2-u5-X18"}],"explanation":["궁금한 것이 있으면 끝까지 읽고 싶어요.","두께나 이기기는 기준이 아니에요.","제목과 그림으로 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_challenge#7','kor',1,2,'u5','L10','g1_2_kor_u5_L10_challenge','lesson_challenge','K1-2-u5-C7',3,'mc','auto','「한 권을 다 읽으면 그 칸을 색칠해요」를 하는 까닭은 무엇인가요?',ARRAY['K1-2-u5-X17','K1-2-u5-X18']::text[],false,'{"seq":7,"concept":"K1-2-u5-C7","difficulty":3,"kind":"mc","stem":"「한 권을 다 읽으면 그 칸을 색칠해요」를 하는 까닭은 무엇인가요?","options":[{"t":"내가 어디까지 읽었는지 한눈에 볼 수 있어서","correct":true},{"t":"계획표를 예쁘게 꾸미려고","mis":"K1-2-u5-X17"},{"t":"친구에게 많이 읽었다고 자랑하려고","mis":"K1-2-u5-X18"}],"explanation":["색칠한 칸을 보면 어디까지 왔는지 알아요.","꾸미기나 자랑이 아니에요.","다음 칸이 어디인지도 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_challenge#8','kor',1,2,'u5','L10','g1_2_kor_u5_L10_challenge','lesson_challenge','K1-2-u5-C7',4,'sa','auto','가은이의 계획표에서 가장 나중에 읽을 책의 제목을 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"K1-2-u5-C7","difficulty":4,"kind":"sa","stem":"가은이의 계획표에서 가장 나중에 읽을 책의 제목을 쓰세요.","answer":["바닷속 친구들","「바닷속 친구들」"],"explanation":["맨 위 칸 「바닷속 친구들」이 가장 나중이에요.","계단은 아래에서 위로 올라가요.","③ 칸을 봐요."],"asset":{"type":"passage","lines":["③ 맨 위 칸 — 「바닷속 친구들」","② 가운데 칸 — 「우주로 간 고양이」","① 맨 아래 칸 — 「꼬마 기차 뿡뿡」 (다 읽어서 색칠함)"],"title":"가은이의 계단 독서 계획표"},"variant_rule":{"alt":[{"stem":"태오의 계획표에서 맨 아래 첫 칸으로 옮기면 좋은 책의 제목을 쓰세요.","answer":["숲속 빵집","「숲속 빵집」"],"explanation":["얇고 그림이 많은 「숲속 빵집」이 첫 칸에 알맞아요.","첫 칸엔 읽기 쉬운 책을 놓아요.","괄호 안 설명을 봐요."],"asset":{"type":"passage","lines":["③ 맨 위 칸 — 「숲속 빵집」 (얇고 그림이 많은 책)","② 가운데 칸 — 「별빛 우체통」","① 맨 아래 칸 — 「공룡 큰 사전」 (가장 두껍고 어려운 책)"],"title":"태오의 계단 독서 계획표"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_challenge#9','kor',1,2,'u5','L10','g1_2_kor_u5_L10_challenge','lesson_challenge','K1-2-u5-C7',4,'essay','teacher','읽고 싶은 책 세 권으로 계단 독서 계획을 세워, 맨 아래 칸부터 차례대로 쓰고 첫 칸에 그 책을 놓은 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u5-C7","difficulty":4,"kind":"essay","stem":"읽고 싶은 책 세 권으로 계단 독서 계획을 세워, 맨 아래 칸부터 차례대로 쓰고 첫 칸에 그 책을 놓은 까닭을 쓰세요.","answer_guide":{"answer":"예: ① 「숲속 빵집」 ② 「별빛 우체통」 ③ 「공룡 큰 사전」. 「숲속 빵집」은 가장 읽고 싶고 그림이 많아 끝까지 읽을 수 있을 것 같아서 첫 칸에 놓았다. — 세 권의 차례와 첫 칸의 까닭이 있으면 맞아요(어떤 책이든 좋아요).","scoring_points":["책 세 권이 차례대로 있는가","첫 칸에 놓은 까닭이 있는가","까닭이 읽고 싶음·쉬움에서 왔는가"]},"explanation":["맨 아래부터 ①②③.","첫 칸은 가장 읽고 싶고 쉬운 책.","어떤 책이든 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L10_challenge#10','kor',1,2,'u5','L10','g1_2_kor_u5_L10_challenge','lesson_challenge','K1-2-u5-C7',4,'essay','teacher','태오에게 계획표를 어떻게 고치면 좋을지 알려 주는 말을 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u5-C7","difficulty":4,"kind":"essay","stem":"태오에게 계획표를 어떻게 고치면 좋을지 알려 주는 말을 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 태오야, 가장 두껍고 어려운 「공룡 큰 사전」은 위 칸으로 옮겨 봐. 맨 아래 칸에는 얇고 그림이 많은 「숲속 빵집」을 놓으면 끝까지 읽을 수 있을 거야. — 어려운 책을 위로, 쉬운 책을 첫 칸으로 옮기는 말이 있으면 맞아요.","scoring_points":["어려운 책을 첫 칸에서 빼라고 했는가","쉬운 책을 첫 칸에 놓으라고 했는가","고치는 까닭(끝까지 읽기)이 있는가"]},"explanation":["첫 칸엔 쉬운 책.","어려운 책은 위로.","끝까지 읽으려고."],"asset":{"type":"passage","lines":["③ 맨 위 칸 — 「숲속 빵집」 (얇고 그림이 많은 책)","② 가운데 칸 — 「별빛 우체통」","① 맨 아래 칸 — 「공룡 큰 사전」 (가장 두껍고 어려운 책)"],"title":"태오의 계단 독서 계획표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#1','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C1',1,'mc','auto','「감」에서 받침은 어느 것인가요?',ARRAY['K1-2-u5-X01']::text[],false,'{"seq":1,"concept":"K1-2-u5-C1","difficulty":1,"kind":"mc","stem":"「감」에서 받침은 어느 것인가요?","options":[{"t":"ㅁ","correct":true},{"t":"ㄱ","mis":"K1-2-u5-X01"},{"t":"ㅏ","mis":"K1-2-u5-X01"}],"explanation":["감 = ㄱ + ㅏ + ㅁ.","ㄱ은 첫 자음자, ㅏ는 모음자예요.","끝소리."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#2','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C2',1,'mc','auto','한글을 만든 사람은 누구인가요?',ARRAY['K1-2-u5-X04']::text[],false,'{"seq":2,"concept":"K1-2-u5-C2","difficulty":1,"kind":"mc","stem":"한글을 만든 사람은 누구인가요?","options":[{"t":"세종 대왕","correct":true},{"t":"이순신 장군","mis":"K1-2-u5-X04"},{"t":"누가 만들었는지 알 수 없다","mis":"K1-2-u5-X04"}],"explanation":["세종 대왕이 만들었어요.","만든 사람이 알려진 글자예요.","누가."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#3','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C3',1,'mc','auto','「공」의 첫 자음자만 바꾼 낱말은 어느 것인가요?',ARRAY['K1-2-u5-X01']::text[],false,'{"seq":3,"concept":"K1-2-u5-C3","difficulty":1,"kind":"mc","stem":"「공」의 첫 자음자만 바꾼 낱말은 어느 것인가요?","options":[{"t":"콩","correct":true},{"t":"곰","mis":"K1-2-u5-X01"},{"t":"강","mis":"K1-2-u5-X01"}],"explanation":["ㄱ → ㅋ.","곰은 받침, 강은 모음자를 바꾸었어요.","처음 소리만."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#4','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C4',1,'mc','auto','읽고 싶은 책을 고를 때 살펴보면 좋은 것은 어느 것인가요?',ARRAY['K1-2-u5-X08']::text[],false,'{"seq":4,"concept":"K1-2-u5-C4","difficulty":1,"kind":"mc","stem":"읽고 싶은 책을 고를 때 살펴보면 좋은 것은 어느 것인가요?","options":[{"t":"책 제목과 겉표지 그림","correct":true},{"t":"책의 무게","mis":"K1-2-u5-X08"},{"t":"책의 값","mis":"K1-2-u5-X08"}],"explanation":["제목과 그림으로 내용을 짐작해요.","무게·값은 내용과 상관없어요.","제목·그림·궁금한 것."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#5','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C5',1,'mc','auto','「강낭콩 화분」에서 가은이가 맡은 일은 무엇인가요?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":5,"concept":"K1-2-u5-C5","difficulty":1,"kind":"mc","stem":"「강낭콩 화분」에서 가은이가 맡은 일은 무엇인가요?","options":[{"t":"물 주는 당번","correct":true},{"t":"화분을 사 오는 당번","mis":"K1-2-u5-X13"},{"t":"꽃을 그리는 당번","mis":"K1-2-u5-X13"}],"explanation":["「물 주는 당번이 되었다」.","나머지는 글에 없어요.","「나는」 줄."],"asset":{"type":"passage","lines":["우리 반 창가에 강낭콩 화분이 놓였다.","나는 물 주는 당번이 되었다.","어느 날 깜빡하고 물을 주지 않았다.","잎이 축 처진 것을 보고 가슴이 철렁했다.","그날부터 나는 달력에 물 준 날을 표시했다.","두 주일 뒤, 줄기 끝에 작은 꽃이 피었다.","나도 모르게 웃음이 났다."],"title":"「강낭콩 화분」 — 가은이가 쓴 글(「나」는 가은)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#6','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C6',1,'mc','auto','글을 읽고 느낌을 말하는 알맞은 방법은 어느 것인가요?',ARRAY['K1-2-u5-X10','K1-2-u5-X15']::text[],false,'{"seq":6,"concept":"K1-2-u5-C6","difficulty":1,"kind":"mc","stem":"글을 읽고 느낌을 말하는 알맞은 방법은 어느 것인가요?","options":[{"t":"글의 어느 부분 때문인지 함께 말한다","correct":true},{"t":"「좋았다」 한마디로 끝낸다","mis":"K1-2-u5-X10"},{"t":"글쓴이가 쓴 말을 그대로 옮긴다","mis":"K1-2-u5-X15"}],"explanation":["어느 부분 때문인지 함께.","한마디나 옮긴 말은 내 느낌이 안 보여요.","내 말로."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#7','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C7',1,'mc','auto','독서 계획 세 걸음 가운데 첫째 걸음은 무엇인가요?',ARRAY['K1-2-u5-X17']::text[],false,'{"seq":7,"concept":"K1-2-u5-C7","difficulty":1,"kind":"mc","stem":"독서 계획 세 걸음 가운데 첫째 걸음은 무엇인가요?","options":[{"t":"읽고 싶은 책 고르기","correct":true},{"t":"한 권씩 끝까지 읽기","mis":"K1-2-u5-X17"},{"t":"다 읽은 칸 색칠하기","mis":"K1-2-u5-X17"}],"explanation":["먼저 고르기.","고르기 → 차례 → 끝까지.","세 걸음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#8','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C8',1,'blank','auto','빈칸에 알맞은 세는 낱말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#9','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C3',2,'match','auto','낱말과 알맞은 뜻을 선으로 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u5-C3","difficulty":2,"kind":"match","stem":"낱말과 알맞은 뜻을 선으로 이어 보세요.","pairs":[{"l":"공","r":"차거나 던지며 노는 둥근 물건"},{"l":"곰","r":"몸집이 크고 털이 많은 동물"},{"l":"콩","r":"밥에 넣어 먹는 작고 둥근 열매"}],"mis":"K1-2-u5-X03","explanation":["한 자리만 달라도 뜻이 달라요.","공·곰·콩.","소리 내어 읽고 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#10','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C5',2,'match','auto','「강낭콩 화분」에서 차례와 가은이가 한 일을 선으로 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u5-C5","difficulty":2,"kind":"match","stem":"「강낭콩 화분」에서 차례와 가은이가 한 일을 선으로 이어 보세요.","pairs":[{"l":"첫째","r":"물 주는 당번이 되었다"},{"l":"둘째","r":"깜빡하고 물을 주지 않았다"},{"l":"셋째","r":"달력에 물 준 날을 표시했다"}],"mis":"K1-2-u5-X13","explanation":["당번 → 깜빡 → 표시.","「어느 날」, 「그날부터」.","줄 차례."],"asset":{"type":"passage","lines":["우리 반 창가에 강낭콩 화분이 놓였다.","나는 물 주는 당번이 되었다.","어느 날 깜빡하고 물을 주지 않았다.","잎이 축 처진 것을 보고 가슴이 철렁했다.","그날부터 나는 달력에 물 준 날을 표시했다.","두 주일 뒤, 줄기 끝에 작은 꽃이 피었다.","나도 모르게 웃음이 났다."],"title":"「강낭콩 화분」 — 가은이가 쓴 글(「나」는 가은)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#11','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C1',2,'mc','auto','첫 자음자만 다른 짝은 어느 것인가요?',ARRAY['K1-2-u5-X01','K1-2-u5-X02']::text[],false,'{"seq":11,"concept":"K1-2-u5-C1","difficulty":2,"kind":"mc","stem":"첫 자음자만 다른 짝은 어느 것인가요?","options":[{"t":"줄 — 풀","correct":true},{"t":"줄 — 절","mis":"K1-2-u5-X01"},{"t":"줄 — 팔","mis":"K1-2-u5-X02"}],"explanation":["ㅈ과 ㅍ만 달라요.","절은 모음자가, 팔은 두 자리가 달라요.","다른 칸 하나."],"asset":{"type":"passage","lines":["줄을 서서 기다려요.","풀밭에는 들어가지 말아요."],"title":"운동장 안내판","hi":["줄","풀"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#12','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C2',2,'mc','auto','「ㄴ → ㄷ → ㅌ」처럼 획을 더하면 소리는 어떻게 되나요?',ARRAY['K1-2-u5-X06']::text[],false,'{"seq":12,"concept":"K1-2-u5-C2","difficulty":2,"kind":"mc","stem":"「ㄴ → ㄷ → ㅌ」처럼 획을 더하면 소리는 어떻게 되나요?","options":[{"t":"소리가 점점 세진다","correct":true},{"t":"소리가 점점 작아진다","mis":"K1-2-u5-X06"},{"t":"소리는 그대로이다","mis":"K1-2-u5-X06"}],"explanation":["획을 더할수록 세져요.","소리 내어 느껴 봐요.","획 더하기."],"asset":{"type":"scene","icon":"ㄴ → ㄷ → ㅌ","text":"획을 하나씩 더했어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#13','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C4',2,'mc','auto','「박쥐가 나오는 책」을 읽은 예준이가 느낀 재미는 어떤 재미인가요?',ARRAY['K1-2-u5-X09','K1-2-u5-X08']::text[],false,'{"seq":13,"concept":"K1-2-u5-C4","difficulty":2,"kind":"mc","stem":"「박쥐가 나오는 책」을 읽은 예준이가 느낀 재미는 어떤 재미인가요?","options":[{"t":"몰랐던 것을 새로 알게 되는 재미","correct":true},{"t":"배를 잡고 웃는 재미","mis":"K1-2-u5-X09"},{"t":"쪽수가 적어 빨리 끝나는 재미","mis":"K1-2-u5-X08"}],"explanation":["「처음 알았어!」 — 새로 앎.","웃음만 재미가 아니에요.","예준이의 말."],"asset":{"type":"passage","lines":["쉬는 시간에 예준이는 도서관에서 동굴 그림이 있는 책을 골랐다.","책에는 박쥐가 거꾸로 매달려 잠을 잔다고 적혀 있었다.","예준이는 \"우아, 처음 알았어!\" 하고 말했다.","책장을 넘기다 보니 수업 종이 울린 것도 몰랐다.","집에 간 예준이는 동생에게 박쥐 이야기를 들려주었다."],"title":"「박쥐가 나오는 책」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#14','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C7',2,'mc','auto','가은이가 다음에 읽을 책은 어느 것인가요?',ARRAY['K1-2-u5-X17','K1-2-u5-X19']::text[],false,'{"seq":14,"concept":"K1-2-u5-C7","difficulty":2,"kind":"mc","stem":"가은이가 다음에 읽을 책은 어느 것인가요?","options":[{"t":"「우주로 간 고양이」","correct":true},{"t":"「바닷속 친구들」","mis":"K1-2-u5-X17"},{"t":"「꼬마 기차 뿡뿡」","mis":"K1-2-u5-X19"}],"explanation":["첫 칸을 다 읽었으니 가운데 칸.","맨 위는 가장 나중이에요.","한 칸씩."],"asset":{"type":"passage","lines":["③ 맨 위 칸 — 「바닷속 친구들」","② 가운데 칸 — 「우주로 간 고양이」","① 맨 아래 칸 — 「꼬마 기차 뿡뿡」 (다 읽어서 색칠함)"],"title":"가은이의 계단 독서 계획표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#15','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C3',2,'ox','auto','「곰」의 받침을 바꾸어 만든 「곺」은 낱말이에요.',ARRAY['K1-2-u5-X07']::text[],false,'{"seq":15,"concept":"K1-2-u5-C3","difficulty":2,"kind":"ox","stem":"「곰」의 받침을 바꾸어 만든 「곺」은 낱말이에요.","answer":"X","reason_options":[{"t":"소리는 나지만 아무 뜻이 없으니까","correct":true},{"t":"한 자리만 바꾸었으니까","mis":"K1-2-u5-X07"}],"mis":"K1-2-u5-X07","explanation":["뜻이 없으면 낱말이 아니에요.","한 자리만 바꾸어도 마찬가지예요.","뜻이 있는지."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#16','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C5',2,'mc','auto','「잎이 축 처진 것을 보고 가슴이 철렁했다」에서 알 수 있는 가은이의 마음은 어느 것인가요?',ARRAY['K1-2-u5-X14']::text[],false,'{"seq":16,"concept":"K1-2-u5-C5","difficulty":2,"kind":"mc","stem":"「잎이 축 처진 것을 보고 가슴이 철렁했다」에서 알 수 있는 가은이의 마음은 어느 것인가요?","options":[{"t":"깜짝 놀라고 걱정되는 마음","correct":true},{"t":"신나고 즐거운 마음","mis":"K1-2-u5-X14"},{"t":"심심한 마음","mis":"K1-2-u5-X14"}],"explanation":["「가슴이 철렁」은 놀람·걱정.","잎이 처진 일과 함께 봐요.","마음을 알려 주는 말."],"asset":{"type":"passage","lines":["우리 반 창가에 강낭콩 화분이 놓였다.","나는 물 주는 당번이 되었다.","어느 날 깜빡하고 물을 주지 않았다.","잎이 축 처진 것을 보고 가슴이 철렁했다.","그날부터 나는 달력에 물 준 날을 표시했다.","두 주일 뒤, 줄기 끝에 작은 꽃이 피었다.","나도 모르게 웃음이 났다."],"title":"「강낭콩 화분」 — 가은이가 쓴 글(「나」는 가은)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
