INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#18','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C3',3,'error','auto','「밤」의 받침만 바꾼 낱말을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#19','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C6',3,'ox','auto','글에 적힌 글쓴이의 말을 그대로 옮기면 그것이 내 생각이에요.',ARRAY['K1-2-u5-X15']::text[],false,'{"seq":19,"concept":"K1-2-u5-C6","difficulty":3,"kind":"ox","stem":"글에 적힌 글쓴이의 말을 그대로 옮기면 그것이 내 생각이에요.","answer":"X","reason_options":[{"t":"내 생각은 글을 읽고 내 마음에 든 것을 내 말로 말하는 것이니까","correct":true},{"t":"글쓴이의 말이 가장 정확하니까","mis":"K1-2-u5-X15"}],"mis":"K1-2-u5-X15","explanation":["옮긴 말은 글쓴이의 말이에요.","내 마음을 내 말로.","「~해 보였어」."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#20','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C2',3,'mc','auto','한글이 생겨서 가장 크게 달라진 것은 무엇인가요?',ARRAY['K1-2-u5-X05']::text[],false,'{"seq":20,"concept":"K1-2-u5-C2","difficulty":3,"kind":"mc","stem":"한글이 생겨서 가장 크게 달라진 것은 무엇인가요?","options":[{"t":"누구나 자기 생각을 글로 적을 수 있게 되었다","correct":true},{"t":"글을 아는 사람이 더 적어졌다","mis":"K1-2-u5-X05"},{"t":"임금님만 글을 쓸 수 있게 되었다","mis":"K1-2-u5-X05"}],"explanation":["누구나 글을 쓰게 되었어요.","글을 아는 사람은 많아졌어요.","많은 사람의 삶."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#21','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C7',3,'error','auto','독서 계획표에 적을 것을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#22','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C6',3,'mc','auto','「강낭콩 화분」과 비슷한 경험으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u5-X16']::text[],false,'{"seq":22,"concept":"K1-2-u5-C6","difficulty":3,"kind":"mc","stem":"「강낭콩 화분」과 비슷한 경험으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"맡은 일을 깜빡했다가 다시 잘 해내서 기뻤던 일","correct":true},{"t":"강낭콩 가격을 알아본 일","mis":"K1-2-u5-X16"},{"t":"창가 자리에 앉았던 일","mis":"K1-2-u5-X16"}],"explanation":["깜빡 → 다시 → 기쁨, 일과 마음이 닮았어요.","물건이나 자리만 같은 것은 비슷한 경험이 아니에요.","일과 마음."],"asset":{"type":"passage","lines":["우리 반 창가에 강낭콩 화분이 놓였다.","나는 물 주는 당번이 되었다.","어느 날 깜빡하고 물을 주지 않았다.","잎이 축 처진 것을 보고 가슴이 철렁했다.","그날부터 나는 달력에 물 준 날을 표시했다.","두 주일 뒤, 줄기 끝에 작은 꽃이 피었다.","나도 모르게 웃음이 났다."],"title":"「강낭콩 화분」 — 가은이가 쓴 글(「나」는 가은)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#23','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C8',4,'sa','auto','그림을 보고 빈칸에 알맞은 세는 낱말을 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#24','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C4',4,'essay','teacher','「박쥐가 나오는 책」을 친구에게 추천하는 말을 쓰세요. 책 제목과 추천하는 까닭이 들어가게 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u5-C4","difficulty":4,"kind":"essay","stem":"「박쥐가 나오는 책」을 친구에게 추천하는 말을 쓰세요. 책 제목과 추천하는 까닭이 들어가게 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 이 책은 「박쥐가 나오는 책」이야. 박쥐가 거꾸로 매달려 잔다는 것처럼 몰랐던 것을 알 수 있어서 추천해. — 제목과 내용에서 온 까닭이 있으면 맞아요.","scoring_points":["책 제목이 있는가","추천하는 까닭이 있는가","까닭이 책의 내용(장면·재미)에서 왔는가"]},"explanation":["제목 + 까닭.","새로 앎도 재미.","읽고 싶어지게."],"asset":{"type":"passage","lines":["쉬는 시간에 예준이는 도서관에서 동굴 그림이 있는 책을 골랐다.","책에는 박쥐가 거꾸로 매달려 잠을 잔다고 적혀 있었다.","예준이는 \"우아, 처음 알았어!\" 하고 말했다.","책장을 넘기다 보니 수업 종이 울린 것도 몰랐다.","집에 간 예준이는 동생에게 박쥐 이야기를 들려주었다."],"title":"「박쥐가 나오는 책」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_a#25','kor',1,2,'u5','','g1_2_kor_u5_review_a','unit_review','K1-2-u5-C6',4,'essay','teacher','「강낭콩 화분」을 읽고 든 생각이나 느낌을 글의 어느 부분 때문인지 넣어 한 문장, 비슷한 내 경험을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u5-C6","difficulty":4,"kind":"essay","stem":"「강낭콩 화분」을 읽고 든 생각이나 느낌을 글의 어느 부분 때문인지 넣어 한 문장, 비슷한 내 경험을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 깜빡한 뒤 달력에 표시한 것이 참 꼼꼼해 보였다. 나도 숙제를 잊은 뒤로 알림장에 표시하고 있다. — 글의 부분과 내 생각, 일이나 마음이 닮은 경험이 있으면 맞아요.","scoring_points":["글의 어느 부분인지 있는가","내 생각·느낌을 내 말로 썼는가","일이나 마음이 닮은 경험인가"]},"explanation":["어느 부분 + 내 생각.","닮은 경험 하나.","옮기지 말고 내 말로."],"asset":{"type":"passage","lines":["우리 반 창가에 강낭콩 화분이 놓였다.","나는 물 주는 당번이 되었다.","어느 날 깜빡하고 물을 주지 않았다.","잎이 축 처진 것을 보고 가슴이 철렁했다.","그날부터 나는 달력에 물 준 날을 표시했다.","두 주일 뒤, 줄기 끝에 작은 꽃이 피었다.","나도 모르게 웃음이 났다."],"title":"「강낭콩 화분」 — 가은이가 쓴 글(「나」는 가은)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#1','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C1',1,'mc','auto','「눈」에서 모음자는 어느 것인가요?',ARRAY['K1-2-u5-X01','K1-2-u5-X02']::text[],false,'{"seq":1,"concept":"K1-2-u5-C1","difficulty":1,"kind":"mc","stem":"「눈」에서 모음자는 어느 것인가요?","options":[{"t":"ㅜ","correct":true},{"t":"ㄴ","mis":"K1-2-u5-X01"},{"t":"ㅗ","mis":"K1-2-u5-X02"}],"explanation":["눈 = ㄴ + ㅜ + ㄴ.","ㄴ은 첫 자음자이자 받침이고, ㅗ는 눈에 없어요.","가운데 소리."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#2','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C2',1,'mc','auto','세종 대왕이 한글을 만든 까닭은 무엇인가요?',ARRAY['K1-2-u5-X05']::text[],false,'{"seq":2,"concept":"K1-2-u5-C2","difficulty":1,"kind":"mc","stem":"세종 대왕이 한글을 만든 까닭은 무엇인가요?","options":[{"t":"백성이 쉽게 읽고 쓰게 하려고","correct":true},{"t":"임금님 혼자만 쓰려고","mis":"K1-2-u5-X05"},{"t":"글을 더 어렵게 하려고","mis":"K1-2-u5-X05"}],"explanation":["백성을 위해 만들었어요.","혼자 쓰거나 어렵게 하려던 것이 아니에요.","왜."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#3','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C3',1,'mc','auto','「물」의 받침만 바꾼 낱말은 어느 것인가요?',ARRAY['K1-2-u5-X01']::text[],false,'{"seq":3,"concept":"K1-2-u5-C3","difficulty":1,"kind":"mc","stem":"「물」의 받침만 바꾼 낱말은 어느 것인가요?","options":[{"t":"문","correct":true},{"t":"불","mis":"K1-2-u5-X01"},{"t":"말","mis":"K1-2-u5-X01"}],"explanation":["ㄹ → ㄴ.","불은 첫 자음자, 말은 모음자를 바꾸었어요.","끝소리만."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#4','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C4',1,'mc','auto','책을 고른 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u5-X08']::text[],false,'{"seq":4,"concept":"K1-2-u5-C4","difficulty":1,"kind":"mc","stem":"책을 고른 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"궁금했던 우주 이야기가 나와서","correct":true},{"t":"가장 두꺼워서","mis":"K1-2-u5-X08"},{"t":"가장 값이 싸서","mis":"K1-2-u5-X08"}],"explanation":["궁금한 것이 나오면 끝까지 읽고 싶어요.","두께나 값은 까닭이 되지 못해요.","내용에서 까닭을."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#5','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C5',1,'mc','auto','「두발자전거」에서 태오가 토요일마다 한 일은 무엇인가요?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":5,"concept":"K1-2-u5-C5","difficulty":1,"kind":"mc","stem":"「두발자전거」에서 태오가 토요일마다 한 일은 무엇인가요?","options":[{"t":"아빠와 두발자전거를 연습했다","correct":true},{"t":"아빠와 공원에서 공을 찼다","mis":"K1-2-u5-X13"},{"t":"혼자 자전거를 고쳤다","mis":"K1-2-u5-X13"}],"explanation":["첫 줄에 있어요.","나머지는 글에 없어요.","「토요일마다」."],"asset":{"type":"passage","lines":["나는 토요일마다 아빠와 두발자전거를 연습했다.","처음에는 자꾸 넘어져서 무릎이 까졌다.","속이 상해서 눈물이 났다.","아빠가 \"발밑 말고 앞을 보고 달려 봐.\" 하고 말씀하셨다.","나는 먼 나무를 보며 페달을 밟았다.","세 번째 토요일, 나는 혼자 끝까지 달렸다.","바람이 얼굴에 닿자 가슴이 두근두근 뛰었다."],"title":"「두발자전거」 — 태오가 쓴 글(「나」는 태오)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#6','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C6',1,'mc','auto','글을 읽고 생각을 말하는 알맞은 방법은 어느 것인가요?',ARRAY['K1-2-u5-X15','K1-2-u5-X10']::text[],false,'{"seq":6,"concept":"K1-2-u5-C6","difficulty":1,"kind":"mc","stem":"글을 읽고 생각을 말하는 알맞은 방법은 어느 것인가요?","options":[{"t":"글을 읽고 내가 든 생각을 내 말로 말한다","correct":true},{"t":"글에 적힌 문장을 그대로 읽는다","mis":"K1-2-u5-X15"},{"t":"「재미있었다」만 말한다","mis":"K1-2-u5-X10"}],"explanation":["내 생각은 내 말로.","읽기나 한마디는 생각이 아니에요.","어느 부분 + 내 생각."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#7','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C7',1,'mc','auto','계단 독서 계획표에서 가장 먼저 읽을 책은 어느 칸에 적나요?',ARRAY['K1-2-u5-X17']::text[],false,'{"seq":7,"concept":"K1-2-u5-C7","difficulty":1,"kind":"mc","stem":"계단 독서 계획표에서 가장 먼저 읽을 책은 어느 칸에 적나요?","options":[{"t":"맨 아래 칸","correct":true},{"t":"맨 위 칸","mis":"K1-2-u5-X17"},{"t":"아무 칸에나","mis":"K1-2-u5-X17"}],"explanation":["아래에서 위로 올라가요.","맨 아래 칸이 첫째예요.","계단."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#8','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C8',1,'blank','auto','빈칸에 알맞은 세는 낱말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#9','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C3',2,'match','auto','낱말과 알맞은 뜻을 선으로 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u5-C3","difficulty":2,"kind":"match","stem":"낱말과 알맞은 뜻을 선으로 이어 보세요.","pairs":[{"l":"물","r":"마시거나 씻을 때 쓰는 것"},{"l":"불","r":"뜨겁고 환하게 타는 것"},{"l":"풀","r":"들에 자라는 키 작은 식물"}],"mis":"K1-2-u5-X03","explanation":["첫 자음자만 달라도 뜻이 달라요.","물·불·풀.","소리 내어 읽고 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#10','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C5',2,'match','auto','「두발자전거」에서 차례와 태오가 한 일을 선으로 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u5-C5","difficulty":2,"kind":"match","stem":"「두발자전거」에서 차례와 태오가 한 일을 선으로 이어 보세요.","pairs":[{"l":"첫째","r":"넘어져서 무릎이 까졌다"},{"l":"둘째","r":"먼 나무를 보며 페달을 밟았다"},{"l":"셋째","r":"혼자 끝까지 달렸다"}],"mis":"K1-2-u5-X13","explanation":["넘어짐 → 앞 보기 → 혼자 달림.","「처음에는」, 「세 번째 토요일」.","줄 차례."],"asset":{"type":"passage","lines":["나는 토요일마다 아빠와 두발자전거를 연습했다.","처음에는 자꾸 넘어져서 무릎이 까졌다.","속이 상해서 눈물이 났다.","아빠가 \"발밑 말고 앞을 보고 달려 봐.\" 하고 말씀하셨다.","나는 먼 나무를 보며 페달을 밟았다.","세 번째 토요일, 나는 혼자 끝까지 달렸다.","바람이 얼굴에 닿자 가슴이 두근두근 뛰었다."],"title":"「두발자전거」 — 태오가 쓴 글(「나」는 태오)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#11','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C1',2,'mc','auto','모음자만 다른 짝은 어느 것인가요?',ARRAY['K1-2-u5-X01','K1-2-u5-X02']::text[],false,'{"seq":11,"concept":"K1-2-u5-C1","difficulty":2,"kind":"mc","stem":"모음자만 다른 짝은 어느 것인가요?","options":[{"t":"손 — 산","correct":true},{"t":"손 — 돈","mis":"K1-2-u5-X01"},{"t":"손 — 곰","mis":"K1-2-u5-X02"}],"explanation":["ㅗ와 ㅏ만 달라요.","돈은 첫 자음자가, 곰은 두 자리가 달라요.","다른 칸 하나."],"asset":{"type":"passage","lines":["손을 깨끗이 씻어요.","산에 갈 때에는 모자를 써요."],"title":"보건실 안내문","hi":["손","산"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#12','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C2',2,'mc','auto','「ㅗ」와 「ㅜ」는 무엇이 다른가요?',ARRAY['K1-2-u5-X06']::text[],false,'{"seq":12,"concept":"K1-2-u5-C2","difficulty":2,"kind":"mc","stem":"「ㅗ」와 「ㅜ」는 무엇이 다른가요?","options":[{"t":"짧은 획이 붙은 방향이 다르다","correct":true},{"t":"긴 획의 길이가 다르다","mis":"K1-2-u5-X06"},{"t":"아무 관계가 없다","mis":"K1-2-u5-X06"}],"explanation":["ㅗ는 위, ㅜ는 아래.","같은 획을 방향만 달리했어요.","방향."],"asset":{"type":"scene","icon":"ㅗ   ㅜ   ㅏ   ㅓ","text":"같은 짧은 획이 붙은 자리를 살펴봐요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#13','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C4',2,'mc','auto','「늙은 강아지 이야기」를 읽은 채윤이가 느낀 재미는 어떤 재미인가요?',ARRAY['K1-2-u5-X09','K1-2-u5-X08']::text[],false,'{"seq":13,"concept":"K1-2-u5-C4","difficulty":2,"kind":"mc","stem":"「늙은 강아지 이야기」를 읽은 채윤이가 느낀 재미는 어떤 재미인가요?","options":[{"t":"마음이 뭉클해지는 재미","correct":true},{"t":"배를 잡고 웃는 재미","mis":"K1-2-u5-X09"},{"t":"글자가 커서 읽기 쉬운 재미","mis":"K1-2-u5-X08"}],"explanation":["코끝이 찡 — 뭉클함.","웃음만 재미가 아니에요.","채윤이의 몸짓."],"asset":{"type":"passage","lines":["채윤이는 할아버지와 늙은 강아지가 나오는 책을 읽었다.","강아지는 다리가 아파도 할아버지 곁을 떠나지 않았다.","그 장면에서 채윤이는 코끝이 찡했다.","책을 덮은 채윤이는 집에 있는 강아지를 꼭 안아 주었다."],"title":"「늙은 강아지 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#14','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C7',2,'mc','auto','맨 아래 첫 칸에 놓으면 좋은 책은 어느 것인가요?',ARRAY['K1-2-u5-X17','K1-2-u5-X08']::text[],false,'{"seq":14,"concept":"K1-2-u5-C7","difficulty":2,"kind":"mc","stem":"맨 아래 첫 칸에 놓으면 좋은 책은 어느 것인가요?","options":[{"t":"가장 읽고 싶고 읽기 쉬운 책","correct":true},{"t":"가장 어렵고 긴 책","mis":"K1-2-u5-X17"},{"t":"가장 무거운 책","mis":"K1-2-u5-X08"}],"explanation":["첫 책을 끝까지 읽게.","어렵거나 무거운 책은 맞지 않아요.","첫 칸."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#15','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C3',2,'ox','auto','「물」의 첫 자음자를 바꾸어 만든 「풀」은 낱말이에요.',ARRAY['K1-2-u5-X07']::text[],false,'{"seq":15,"concept":"K1-2-u5-C3","difficulty":2,"kind":"ox","stem":"「물」의 첫 자음자를 바꾸어 만든 「풀」은 낱말이에요.","answer":"O","reason_options":[{"t":"들에 자라는 식물이라는 뜻이 있으니까","correct":true},{"t":"「물」과 받침이 같으니까","mis":"K1-2-u5-X07"}],"mis":"K1-2-u5-X07","explanation":["뜻이 있으니 낱말이에요.","받침이 같아서가 아니에요.","뜻이 있는지."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#16','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C5',2,'mc','auto','「속이 상해서 눈물이 났다」에서 알 수 있는 태오의 마음은 어느 것인가요?',ARRAY['K1-2-u5-X14']::text[],false,'{"seq":16,"concept":"K1-2-u5-C5","difficulty":2,"kind":"mc","stem":"「속이 상해서 눈물이 났다」에서 알 수 있는 태오의 마음은 어느 것인가요?","options":[{"t":"넘어져서 속상한 마음","correct":true},{"t":"혼자 달려서 신난 마음","mis":"K1-2-u5-X14"},{"t":"아빠에게 고마운 마음","mis":"K1-2-u5-X14"}],"explanation":["「속이 상해서」, 「눈물」.","신난 것은 나중 일이에요.","마음을 알려 주는 말."],"asset":{"type":"passage","lines":["나는 토요일마다 아빠와 두발자전거를 연습했다.","처음에는 자꾸 넘어져서 무릎이 까졌다.","속이 상해서 눈물이 났다.","아빠가 \"발밑 말고 앞을 보고 달려 봐.\" 하고 말씀하셨다.","나는 먼 나무를 보며 페달을 밟았다.","세 번째 토요일, 나는 혼자 끝까지 달렸다.","바람이 얼굴에 닿자 가슴이 두근두근 뛰었다."],"title":"「두발자전거」 — 태오가 쓴 글(「나」는 태오)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
