INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#18','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C3',3,'error','auto','「솔」의 받침만 바꾼 낱말을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#19','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C6',3,'ox','auto','비슷한 경험은 꼭 글에 나온 물건과 같은 물건이 나와야 해요.',ARRAY['K1-2-u5-X16']::text[],false,'{"seq":19,"concept":"K1-2-u5-C6","difficulty":3,"kind":"ox","stem":"비슷한 경험은 꼭 글에 나온 물건과 같은 물건이 나와야 해요.","answer":"X","reason_options":[{"t":"물건이 달라도 일이나 마음이 닮으면 비슷한 경험이니까","correct":true},{"t":"같은 물건이 나와야 떠올리기 쉬우니까","mis":"K1-2-u5-X16"}],"mis":"K1-2-u5-X16","explanation":["일과 마음이 닮으면 돼요.","물건만 같다고 비슷한 것이 아니에요.","무슨 일, 어떤 마음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#20','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C2',3,'mc','auto','한글이 다른 많은 글자와 다른 점은 무엇인가요?',ARRAY['K1-2-u5-X04']::text[],false,'{"seq":20,"concept":"K1-2-u5-C2","difficulty":3,"kind":"mc","stem":"한글이 다른 많은 글자와 다른 점은 무엇인가요?","options":[{"t":"누가·언제·왜 만들었는지가 알려져 있다","correct":true},{"t":"아주 오래되어 만든 사람을 알 수 없다","mis":"K1-2-u5-X04"},{"t":"다른 나라에서 빌려 온 글자다","mis":"K1-2-u5-X04"}],"explanation":["만든 사람·때·까닭이 알려져 있어요.","많은 글자는 그렇지 않아요.","특별한 글자."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#21','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C7',3,'error','auto','독서 계획을 세우면 좋은 점을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#22','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C6',3,'mc','auto','「두발자전거」와 비슷한 경험으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u5-X16']::text[],false,'{"seq":22,"concept":"K1-2-u5-C6","difficulty":3,"kind":"mc","stem":"「두발자전거」와 비슷한 경험으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"여러 번 실패했지만 연습해서 해냈던 일","correct":true},{"t":"자전거 가게 앞을 지나간 일","mis":"K1-2-u5-X16"},{"t":"토요일에 늦잠을 잔 일","mis":"K1-2-u5-X16"}],"explanation":["실패 → 연습 → 해냄, 일과 마음이 닮았어요.","자전거나 토요일만 같은 것은 비슷한 경험이 아니에요.","일과 마음."],"asset":{"type":"passage","lines":["나는 토요일마다 아빠와 두발자전거를 연습했다.","처음에는 자꾸 넘어져서 무릎이 까졌다.","속이 상해서 눈물이 났다.","아빠가 \"발밑 말고 앞을 보고 달려 봐.\" 하고 말씀하셨다.","나는 먼 나무를 보며 페달을 밟았다.","세 번째 토요일, 나는 혼자 끝까지 달렸다.","바람이 얼굴에 닿자 가슴이 두근두근 뛰었다."],"title":"「두발자전거」 — 태오가 쓴 글(「나」는 태오)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#23','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C8',4,'sa','auto','그림을 보고 빈칸에 알맞은 세는 낱말을 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#24','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C4',4,'essay','teacher','「늙은 강아지 이야기」를 친구에게 추천하는 말을 쓰세요. 책 제목과 추천하는 까닭이 들어가게 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u5-C4","difficulty":4,"kind":"essay","stem":"「늙은 강아지 이야기」를 친구에게 추천하는 말을 쓰세요. 책 제목과 추천하는 까닭이 들어가게 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 이 책은 「늙은 강아지 이야기」야. 아픈 강아지가 할아버지 곁을 지키는 장면이 뭉클해서 추천해. — 제목과 내용에서 온 까닭이 있으면 맞아요.","scoring_points":["책 제목이 있는가","추천하는 까닭이 있는가","까닭이 책의 내용(장면·재미)에서 왔는가"]},"explanation":["제목 + 까닭.","뭉클함도 재미.","읽고 싶어지게."],"asset":{"type":"passage","lines":["채윤이는 할아버지와 늙은 강아지가 나오는 책을 읽었다.","강아지는 다리가 아파도 할아버지 곁을 떠나지 않았다.","그 장면에서 채윤이는 코끝이 찡했다.","책을 덮은 채윤이는 집에 있는 강아지를 꼭 안아 주었다."],"title":"「늙은 강아지 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_b#25','kor',1,2,'u5','','g1_2_kor_u5_review_b','unit_review','K1-2-u5-C6',4,'essay','teacher','「두발자전거」를 읽고 든 생각이나 느낌을 글의 어느 부분 때문인지 넣어 한 문장, 비슷한 내 경험을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u5-C6","difficulty":4,"kind":"essay","stem":"「두발자전거」를 읽고 든 생각이나 느낌을 글의 어느 부분 때문인지 넣어 한 문장, 비슷한 내 경험을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 무릎이 까져도 세 번째 토요일까지 연습한 것이 대단해 보였다. 나도 수영을 무서워했지만 계속 해서 물에 뜰 수 있게 되었다. — 글의 부분과 내 생각, 일이나 마음이 닮은 경험이 있으면 맞아요.","scoring_points":["글의 어느 부분인지 있는가","내 생각·느낌을 내 말로 썼는가","일이나 마음이 닮은 경험인가"]},"explanation":["어느 부분 + 내 생각.","닮은 경험 하나.","옮기지 말고 내 말로."],"asset":{"type":"passage","lines":["나는 토요일마다 아빠와 두발자전거를 연습했다.","처음에는 자꾸 넘어져서 무릎이 까졌다.","속이 상해서 눈물이 났다.","아빠가 \"발밑 말고 앞을 보고 달려 봐.\" 하고 말씀하셨다.","나는 먼 나무를 보며 페달을 밟았다.","세 번째 토요일, 나는 혼자 끝까지 달렸다.","바람이 얼굴에 닿자 가슴이 두근두근 뛰었다."],"title":"「두발자전거」 — 태오가 쓴 글(「나」는 태오)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#1','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C1',1,'mc','auto','「발」에서 첫 자음자는 어느 것인가요?',ARRAY['K1-2-u5-X01']::text[],false,'{"seq":1,"concept":"K1-2-u5-C1","difficulty":1,"kind":"mc","stem":"「발」에서 첫 자음자는 어느 것인가요?","options":[{"t":"ㅂ","correct":true},{"t":"ㄹ","mis":"K1-2-u5-X01"},{"t":"ㅏ","mis":"K1-2-u5-X01"}],"explanation":["발 = ㅂ + ㅏ + ㄹ.","ㄹ은 받침, ㅏ는 모음자예요.","처음 소리."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#2','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C2',1,'mc','auto','한글은 누구를 위해 만든 글자인가요?',ARRAY['K1-2-u5-X05']::text[],false,'{"seq":2,"concept":"K1-2-u5-C2","difficulty":1,"kind":"mc","stem":"한글은 누구를 위해 만든 글자인가요?","options":[{"t":"글을 몰라 어려움을 겪던 백성","correct":true},{"t":"임금님 한 사람","mis":"K1-2-u5-X05"},{"t":"다른 나라 사람들","mis":"K1-2-u5-X05"}],"explanation":["백성 누구나 쓰라고 만들었어요.","임금님이나 다른 나라 사람을 위한 것이 아니에요.","누구를 위해."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#3','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C3',1,'mc','auto','「곰」의 모음자만 바꾼 낱말은 어느 것인가요?',ARRAY['K1-2-u5-X01']::text[],false,'{"seq":3,"concept":"K1-2-u5-C3","difficulty":1,"kind":"mc","stem":"「곰」의 모음자만 바꾼 낱말은 어느 것인가요?","options":[{"t":"감","correct":true},{"t":"솜","mis":"K1-2-u5-X01"},{"t":"공","mis":"K1-2-u5-X01"}],"explanation":["ㅗ → ㅏ.","솜은 첫 자음자, 공은 받침을 바꾸었어요.","가운데 소리만."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#4','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C4',1,'mc','auto','책에서 느끼는 재미로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u5-X08']::text[],false,'{"seq":4,"concept":"K1-2-u5-C4","difficulty":1,"kind":"mc","stem":"책에서 느끼는 재미로 알맞은 것은 어느 것인가요?","options":[{"t":"마음이 뭉클해지는 것","correct":true},{"t":"쪽수가 아주 적은 것","mis":"K1-2-u5-X08"},{"t":"글자가 아주 큰 것","mis":"K1-2-u5-X08"}],"explanation":["뭉클함도 책의 재미예요.","쪽수·글자 크기는 재미가 아니에요.","웃음·뭉클·새로 앎."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#5','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C5',1,'mc','auto','「할머니께 쓴 편지」에서 소율이가 하기로 한 일은 무엇인가요?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":5,"concept":"K1-2-u5-C5","difficulty":1,"kind":"mc","stem":"「할머니께 쓴 편지」에서 소율이가 하기로 한 일은 무엇인가요?","options":[{"t":"할머니께 편지를 쓰기","correct":true},{"t":"할머니께 꽃을 사 드리기","mis":"K1-2-u5-X13"},{"t":"할머니 댁에 놀러 가기","mis":"K1-2-u5-X13"}],"explanation":["첫 줄에 있어요.","나머지는 글에 없어요.","「~하기로 했다」."],"asset":{"type":"passage","lines":["할머니 생신이 다가와서 나는 편지를 쓰기로 했다.","처음 쓴 편지는 글씨가 삐뚤빼뚤했다.","다시 읽어 보니 조금 창피했다.","나는 연필을 바르게 쥐고 한 글자씩 천천히 다시 썼다.","할머니께서 편지를 읽으시고 내 손을 꼭 잡아 주셨다.","내 마음이 할머니께 닿은 것 같아 뿌듯했다."],"title":"「할머니께 쓴 편지」 — 소율이가 쓴 글(「나」는 소율)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#6','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C6',1,'mc','auto','글을 읽고 비슷한 경험을 떠올리는 알맞은 방법은 어느 것인가요?',ARRAY['K1-2-u5-X16']::text[],false,'{"seq":6,"concept":"K1-2-u5-C6","difficulty":1,"kind":"mc","stem":"글을 읽고 비슷한 경험을 떠올리는 알맞은 방법은 어느 것인가요?","options":[{"t":"글쓴이와 마음이 닮은 내 일을 떠올린다","correct":true},{"t":"글에 나온 물건과 같은 물건만 찾는다","mis":"K1-2-u5-X16"},{"t":"아무 일이나 떠올린다","mis":"K1-2-u5-X16"}],"explanation":["일이나 마음이 닮으면 비슷한 경험이에요.","물건만 같다고 비슷한 것이 아니에요.","무슨 일, 어떤 마음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#7','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C7',1,'mc','auto','책을 읽는 알맞은 방법은 어느 것인가요?',ARRAY['K1-2-u5-X19']::text[],false,'{"seq":7,"concept":"K1-2-u5-C7","difficulty":1,"kind":"mc","stem":"책을 읽는 알맞은 방법은 어느 것인가요?","options":[{"t":"한 권을 처음부터 끝까지 읽는다","correct":true},{"t":"여러 권을 건너뛰며 넘긴다","mis":"K1-2-u5-X19"},{"t":"그림만 보고 넘긴다","mis":"K1-2-u5-X19"}],"explanation":["끝까지 읽어야 이야기가 이어져요.","건너뛰면 무슨 이야기인지 몰라요.","끝까지."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
