INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#9','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C3',2,'match','auto','낱말과 알맞은 뜻을 선으로 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u5-C3","difficulty":2,"kind":"match","stem":"낱말과 알맞은 뜻을 선으로 이어 보세요.","pairs":[{"l":"달","r":"밤하늘에 뜨는 둥근 것"},{"l":"말","r":"네 다리로 달리는 동물"},{"l":"돌","r":"단단한 작은 바위 조각"}],"mis":"K1-2-u5-X03","explanation":["한 자리만 달라도 뜻이 달라요.","달·말·돌.","소리 내어 읽고 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#10','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C5',2,'match','auto','「할머니께 쓴 편지」에서 차례와 소율이가 한 일을 선으로 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u5-C5","difficulty":2,"kind":"match","stem":"「할머니께 쓴 편지」에서 차례와 소율이가 한 일을 선으로 이어 보세요.","pairs":[{"l":"첫째","r":"편지를 쓰기로 했다"},{"l":"둘째","r":"삐뚤빼뚤한 글씨를 다시 읽어 보았다"},{"l":"셋째","r":"한 글자씩 천천히 다시 썼다"}],"mis":"K1-2-u5-X13","explanation":["쓰기로 함 → 다시 읽음 → 다시 씀.","줄 차례를 따라가요.","줄 차례."],"asset":{"type":"passage","lines":["할머니 생신이 다가와서 나는 편지를 쓰기로 했다.","처음 쓴 편지는 글씨가 삐뚤빼뚤했다.","다시 읽어 보니 조금 창피했다.","나는 연필을 바르게 쥐고 한 글자씩 천천히 다시 썼다.","할머니께서 편지를 읽으시고 내 손을 꼭 잡아 주셨다.","내 마음이 할머니께 닿은 것 같아 뿌듯했다."],"title":"「할머니께 쓴 편지」 — 소율이가 쓴 글(「나」는 소율)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#11','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C1',2,'mc','auto','받침만 다른 짝은 어느 것인가요?',ARRAY['K1-2-u5-X01','K1-2-u5-X02']::text[],false,'{"seq":11,"concept":"K1-2-u5-C1","difficulty":2,"kind":"mc","stem":"받침만 다른 짝은 어느 것인가요?","options":[{"t":"공 — 곰","correct":true},{"t":"공 — 강","mis":"K1-2-u5-X01"},{"t":"공 — 밤","mis":"K1-2-u5-X02"}],"explanation":["ㅇ과 ㅁ만 달라요.","강은 모음자가, 밤은 세 자리가 달라요.","다른 칸 하나."],"asset":{"type":"passage","lines":["놀이터에서는 공을 살살 차요.","곰 인형은 그네에 두지 말아요."],"title":"놀이터 안내판","hi":["공","곰"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#12','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C2',2,'mc','auto','「ㅂ」에 획을 하나 더하면 어떤 글자가 될까요?',ARRAY['K1-2-u5-X06']::text[],false,'{"seq":12,"concept":"K1-2-u5-C2","difficulty":2,"kind":"mc","stem":"「ㅂ」에 획을 하나 더하면 어떤 글자가 될까요?","options":[{"t":"ㅍ","correct":true},{"t":"ㅁ","mis":"K1-2-u5-X06"},{"t":"ㅎ","mis":"K1-2-u5-X06"}],"explanation":["ㅁ → ㅂ → ㅍ.","ㅁ은 ㅂ보다 획이 적고, ㅎ은 다른 줄기예요.","획 더하기."],"asset":{"type":"scene","icon":"ㅂ → ?","text":"획을 하나 더해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#13','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C4',2,'mc','auto','「모자를 쫓는 곰」을 읽은 윤슬이가 느낀 재미는 어떤 재미인가요?',ARRAY['K1-2-u5-X13','K1-2-u5-X08']::text[],false,'{"seq":13,"concept":"K1-2-u5-C4","difficulty":2,"kind":"mc","stem":"「모자를 쫓는 곰」을 읽은 윤슬이가 느낀 재미는 어떤 재미인가요?","options":[{"t":"웃음이 나는 재미","correct":true},{"t":"마음이 뭉클해지는 재미","mis":"K1-2-u5-X13"},{"t":"책이 얇아서 좋은 재미","mis":"K1-2-u5-X08"}],"explanation":["깔깔 웃었어요.","뭉클한 장면은 이 글에 없어요.","윤슬이의 몸짓."],"asset":{"type":"passage","lines":["윤슬이는 바람에 날아간 모자를 쫓는 곰이 나오는 책을 읽었다.","곰은 모자만 보고 달리다가 연못에 풍덩 빠졌다.","윤슬이는 배를 잡고 깔깔 웃었다.","윤슬이는 그 장면을 짝에게 소리 내어 읽어 주었다."],"title":"「모자를 쫓는 곰」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#14','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C7',2,'mc','auto','첫 책이 너무 어려울 때 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u5-X19']::text[],false,'{"seq":14,"concept":"K1-2-u5-C7","difficulty":2,"kind":"mc","stem":"첫 책이 너무 어려울 때 알맞은 것은 어느 것인가요?","options":[{"t":"읽을 수 있는 책으로 바꾸어 이어 간다","correct":true},{"t":"읽기를 그만둔다","mis":"K1-2-u5-X19"},{"t":"어려운 곳은 건너뛴다","mis":"K1-2-u5-X19"}],"explanation":["계획은 고쳐도 돼요.","그만두거나 건너뛰지 않아요.","이어 가기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#15','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C3',2,'ox','auto','「달」의 받침을 바꾸어 만든 「닽」은 낱말이에요.',ARRAY['K1-2-u5-X07']::text[],false,'{"seq":15,"concept":"K1-2-u5-C3","difficulty":2,"kind":"ox","stem":"「달」의 받침을 바꾸어 만든 「닽」은 낱말이에요.","answer":"X","reason_options":[{"t":"소리는 나지만 아무 뜻이 없으니까","correct":true},{"t":"「달」과 모음자가 같으니까","mis":"K1-2-u5-X07"}],"mis":"K1-2-u5-X07","explanation":["뜻이 없으면 낱말이 아니에요.","모음자가 같아도 마찬가지예요.","뜻이 있는지."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#16','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C5',2,'mc','auto','「내 마음이 할머니께 닿은 것 같아 뿌듯했다」에서 알 수 있는 소율이의 마음은 어느 것인가요?',ARRAY['K1-2-u5-X14']::text[],false,'{"seq":16,"concept":"K1-2-u5-C5","difficulty":2,"kind":"mc","stem":"「내 마음이 할머니께 닿은 것 같아 뿌듯했다」에서 알 수 있는 소율이의 마음은 어느 것인가요?","options":[{"t":"마음을 전해서 기쁘고 자랑스러운 마음","correct":true},{"t":"글씨가 삐뚤빼뚤해 창피한 마음","mis":"K1-2-u5-X14"},{"t":"할머니께 서운한 마음","mis":"K1-2-u5-X14"}],"explanation":["「뿌듯했다」.","창피한 마음은 앞의 일이에요.","마음을 알려 주는 말."],"asset":{"type":"passage","lines":["할머니 생신이 다가와서 나는 편지를 쓰기로 했다.","처음 쓴 편지는 글씨가 삐뚤빼뚤했다.","다시 읽어 보니 조금 창피했다.","나는 연필을 바르게 쥐고 한 글자씩 천천히 다시 썼다.","할머니께서 편지를 읽으시고 내 손을 꼭 잡아 주셨다.","내 마음이 할머니께 닿은 것 같아 뿌듯했다."],"title":"「할머니께 쓴 편지」 — 소율이가 쓴 글(「나」는 소율)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
