INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#19','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C6',3,'ox','auto','같은 글을 읽고 친구와 생각이 달라도 서로 까닭을 들어 보면 돼요.',ARRAY['K1-2-u5-X11']::text[],false,'{"seq":19,"concept":"K1-2-u5-C6","difficulty":3,"kind":"ox","stem":"같은 글을 읽고 친구와 생각이 달라도 서로 까닭을 들어 보면 돼요.","answer":"O","reason_options":[{"t":"사람마다 마음이 움직이는 곳이 다르니까","correct":true},{"t":"친구 생각은 늘 틀리니까","mis":"K1-2-u5-X11"}],"mis":"K1-2-u5-X11","explanation":["다른 생각도 존중해요.","틀린 것이 아니라 다른 거예요.","까닭을 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#20','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C2',3,'mc','auto','한글날(10월 9일)은 어떤 날인가요?',ARRAY['K1-2-u5-X04']::text[],false,'{"seq":20,"concept":"K1-2-u5-C2","difficulty":3,"kind":"mc","stem":"한글날(10월 9일)은 어떤 날인가요?","options":[{"t":"한글을 만들어 널리 알린 것을 기념하는 날","correct":true},{"t":"세종 대왕이 태어난 날","mis":"K1-2-u5-X04"},{"t":"처음으로 글자를 배우는 날","mis":"K1-2-u5-X04"}],"explanation":["한글을 널리 알린 것을 기념해요.","언제 알렸는지도 알려진 글자라 한글날이 있어요.","언제."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#21','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C7',3,'error','auto','읽을 책을 고르는 기준을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#22','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C6',3,'mc','auto','「할머니께 쓴 편지」와 비슷한 경험으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u5-X16']::text[],false,'{"seq":22,"concept":"K1-2-u5-C6","difficulty":3,"kind":"mc","stem":"「할머니께 쓴 편지」와 비슷한 경험으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"서툴렀지만 다시 해서 마음을 전했던 일","correct":true},{"t":"편지 봉투 색깔을 고른 일","mis":"K1-2-u5-X16"},{"t":"할머니 댁 가는 길에 본 간판","mis":"K1-2-u5-X16"}],"explanation":["서툼 → 다시 → 마음 전함.","편지나 할머니만 나온다고 비슷한 것이 아니에요.","일과 마음."],"asset":{"type":"passage","lines":["할머니 생신이 다가와서 나는 편지를 쓰기로 했다.","처음 쓴 편지는 글씨가 삐뚤빼뚤했다.","다시 읽어 보니 조금 창피했다.","나는 연필을 바르게 쥐고 한 글자씩 천천히 다시 썼다.","할머니께서 편지를 읽으시고 내 손을 꼭 잡아 주셨다.","내 마음이 할머니께 닿은 것 같아 뿌듯했다."],"title":"「할머니께 쓴 편지」 — 소율이가 쓴 글(「나」는 소율)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#23','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C8',4,'sa','auto','그림을 보고 빈칸에 알맞은 세는 낱말을 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#24','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C4',4,'essay','teacher','「모자를 쫓는 곰」을 친구에게 추천하는 말을 쓰세요. 책 제목과 추천하는 까닭이 들어가게 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u5-C4","difficulty":4,"kind":"essay","stem":"「모자를 쫓는 곰」을 친구에게 추천하는 말을 쓰세요. 책 제목과 추천하는 까닭이 들어가게 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 이 책은 「모자를 쫓는 곰」이야. 곰이 모자만 보고 달리다 연못에 빠지는 장면이 웃겨서 추천해. — 제목과 내용에서 온 까닭이 있으면 맞아요.","scoring_points":["책 제목이 있는가","추천하는 까닭이 있는가","까닭이 책의 내용(장면·재미)에서 왔는가"]},"explanation":["제목 + 까닭.","웃음도 재미.","읽고 싶어지게."],"asset":{"type":"passage","lines":["윤슬이는 바람에 날아간 모자를 쫓는 곰이 나오는 책을 읽었다.","곰은 모자만 보고 달리다가 연못에 풍덩 빠졌다.","윤슬이는 배를 잡고 깔깔 웃었다.","윤슬이는 그 장면을 짝에게 소리 내어 읽어 주었다."],"title":"「모자를 쫓는 곰」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_c#25','kor',1,2,'u5','','g1_2_kor_u5_review_c','unit_review','K1-2-u5-C6',4,'essay','teacher','「할머니께 쓴 편지」를 읽고 든 생각이나 느낌을 글의 어느 부분 때문인지 넣어 한 문장, 비슷한 내 경험을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u5-C6","difficulty":4,"kind":"essay","stem":"「할머니께 쓴 편지」를 읽고 든 생각이나 느낌을 글의 어느 부분 때문인지 넣어 한 문장, 비슷한 내 경험을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 창피해도 한 글자씩 다시 쓴 것이 멋져 보였다. 나도 엄마 생신 카드를 다시 써서 드린 적이 있다. — 글의 부분과 내 생각, 일이나 마음이 닮은 경험이 있으면 맞아요.","scoring_points":["글의 어느 부분인지 있는가","내 생각·느낌을 내 말로 썼는가","일이나 마음이 닮은 경험인가"]},"explanation":["어느 부분 + 내 생각.","닮은 경험 하나.","옮기지 말고 내 말로."],"asset":{"type":"passage","lines":["할머니 생신이 다가와서 나는 편지를 쓰기로 했다.","처음 쓴 편지는 글씨가 삐뚤빼뚤했다.","다시 읽어 보니 조금 창피했다.","나는 연필을 바르게 쥐고 한 글자씩 천천히 다시 썼다.","할머니께서 편지를 읽으시고 내 손을 꼭 잡아 주셨다.","내 마음이 할머니께 닿은 것 같아 뿌듯했다."],"title":"「할머니께 쓴 편지」 — 소율이가 쓴 글(「나」는 소율)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#1','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C1',1,'mc','auto','「솜」에서 받침은 어느 것인가요?',ARRAY['K1-2-u5-X01']::text[],false,'{"seq":1,"concept":"K1-2-u5-C1","difficulty":1,"kind":"mc","stem":"「솜」에서 받침은 어느 것인가요?","options":[{"t":"ㅁ","correct":true},{"t":"ㅅ","mis":"K1-2-u5-X01"},{"t":"ㅗ","mis":"K1-2-u5-X01"}],"explanation":["솜 = ㅅ + ㅗ + ㅁ.","ㅅ은 첫 자음자, ㅗ는 모음자예요.","끝소리."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#2','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C2',1,'mc','auto','한글로 할 수 있는 일로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u5-X05']::text[],false,'{"seq":2,"concept":"K1-2-u5-C2","difficulty":1,"kind":"mc","stem":"한글로 할 수 있는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"내 생각을 글로 적어 나눌 수 있다","correct":true},{"t":"말을 하지 않아도 된다","mis":"K1-2-u5-X05"},{"t":"다른 나라 말을 저절로 안다","mis":"K1-2-u5-X05"}],"explanation":["읽고, 쓰고, 나눌 수 있어요.","말이 필요 없어지거나 외국말이 저절로 되지 않아요.","한글이 있어 좋은 점."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#3','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C3',1,'mc','auto','「손」의 받침만 바꾼 낱말은 어느 것인가요?',ARRAY['K1-2-u5-X01']::text[],false,'{"seq":3,"concept":"K1-2-u5-C3","difficulty":1,"kind":"mc","stem":"「손」의 받침만 바꾼 낱말은 어느 것인가요?","options":[{"t":"솜","correct":true},{"t":"산","mis":"K1-2-u5-X01"},{"t":"돈","mis":"K1-2-u5-X01"}],"explanation":["ㄴ → ㅁ.","산은 모음자, 돈은 첫 자음자를 바꾸었어요.","끝소리만."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#4','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C4',1,'mc','auto','재미있었던 부분을 말할 때 함께 말할 것은 어느 것인가요?',ARRAY['K1-2-u5-X10']::text[],false,'{"seq":4,"concept":"K1-2-u5-C4","difficulty":1,"kind":"mc","stem":"재미있었던 부분을 말할 때 함께 말할 것은 어느 것인가요?","options":[{"t":"그 부분이 재미있었던 까닭","correct":true},{"t":"그 부분이 몇 쪽인지","mis":"K1-2-u5-X10"},{"t":"책을 빌린 날짜","mis":"K1-2-u5-X10"}],"explanation":["어느 부분이 왜 재미있었는지.","쪽수·날짜는 마음을 알려 주지 않아요.","「~해서」."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#5','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C5',1,'mc','auto','「운동화 끈」에서 하람이가 해 보기로 한 일은 무엇인가요?',ARRAY['K1-2-u5-X13']::text[],false,'{"seq":5,"concept":"K1-2-u5-C5","difficulty":1,"kind":"mc","stem":"「운동화 끈」에서 하람이가 해 보기로 한 일은 무엇인가요?","options":[{"t":"혼자 운동화 끈을 묶기","correct":true},{"t":"새 운동화를 사기","mis":"K1-2-u5-X13"},{"t":"형의 끈을 묶어 주기","mis":"K1-2-u5-X13"}],"explanation":["첫 줄에 있어요.","나머지는 글에 없어요.","「~해 보기로 했다」."],"asset":{"type":"passage","lines":["나는 혼자 운동화 끈을 묶어 보기로 했다.","처음에는 끈이 자꾸 풀려서 짜증이 났다.","형이 \"고리를 두 개 만들어 봐.\" 하고 알려 주었다.","나는 고리 두 개를 만들어 천천히 엇갈려 묶었다.","다음 날 아침, 끈이 한 번도 풀리지 않고 학교까지 갔다.","신발을 내려다볼 때마다 어깨가 으쓱했다."],"title":"「운동화 끈」 — 하람이가 쓴 글(「나」는 하람)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#6','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C6',1,'mc','auto','친구와 느낌이 다를 때 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u5-X11']::text[],false,'{"seq":6,"concept":"K1-2-u5-C6","difficulty":1,"kind":"mc","stem":"친구와 느낌이 다를 때 알맞은 것은 어느 것인가요?","options":[{"t":"왜 그렇게 느꼈는지 까닭을 들어 본다","correct":true},{"t":"친구가 틀렸다고 말한다","mis":"K1-2-u5-X11"},{"t":"내 느낌으로 바꾸게 한다","mis":"K1-2-u5-X11"}],"explanation":["사람마다 느낌이 달라요.","틀렸다고 하거나 바꾸게 하지 않아요.","까닭을 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#7','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C7',1,'mc','auto','독서 계획 세 걸음 가운데 마지막 걸음은 무엇인가요?',ARRAY['K1-2-u5-X17','K1-2-u5-X18']::text[],false,'{"seq":7,"concept":"K1-2-u5-C7","difficulty":1,"kind":"mc","stem":"독서 계획 세 걸음 가운데 마지막 걸음은 무엇인가요?","options":[{"t":"한 권씩 끝까지 읽기","correct":true},{"t":"읽고 싶은 책 고르기","mis":"K1-2-u5-X17"},{"t":"친구와 권수 겨루기","mis":"K1-2-u5-X18"}],"explanation":["고르기 → 차례 → 끝까지 읽기.","겨루기는 걸음이 아니에요.","세 걸음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
