INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#10','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C5',2,'match','auto','「운동화 끈」에서 차례와 하람이가 한 일을 선으로 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u5-C5","difficulty":2,"kind":"match","stem":"「운동화 끈」에서 차례와 하람이가 한 일을 선으로 이어 보세요.","pairs":[{"l":"첫째","r":"혼자 끈을 묶어 보기로 했다"},{"l":"둘째","r":"고리 두 개를 만들어 엇갈려 묶었다"},{"l":"셋째","r":"풀리지 않은 신발로 학교까지 갔다"}],"mis":"K1-2-u5-X13","explanation":["마음먹음 → 묶음 → 학교까지.","「다음 날 아침」.","줄 차례."],"asset":{"type":"passage","lines":["나는 혼자 운동화 끈을 묶어 보기로 했다.","처음에는 끈이 자꾸 풀려서 짜증이 났다.","형이 \"고리를 두 개 만들어 봐.\" 하고 알려 주었다.","나는 고리 두 개를 만들어 천천히 엇갈려 묶었다.","다음 날 아침, 끈이 한 번도 풀리지 않고 학교까지 갔다.","신발을 내려다볼 때마다 어깨가 으쓱했다."],"title":"「운동화 끈」 — 하람이가 쓴 글(「나」는 하람)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#11','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C1',2,'mc','auto','받침만 다른 짝은 어느 것인가요?',ARRAY['K1-2-u5-X01','K1-2-u5-X02']::text[],false,'{"seq":11,"concept":"K1-2-u5-C1","difficulty":2,"kind":"mc","stem":"받침만 다른 짝은 어느 것인가요?","options":[{"t":"물 — 문","correct":true},{"t":"물 — 불","mis":"K1-2-u5-X01"},{"t":"물 — 감","mis":"K1-2-u5-X02"}],"explanation":["ㄹ과 ㄴ만 달라요.","불은 첫 자음자가, 감은 세 자리가 달라요.","다른 칸 하나."],"asset":{"type":"passage","lines":["물을 아껴 써요.","문을 꼭 닫아 주세요."],"title":"화장실 안내문","hi":["물","문"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#12','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C2',2,'mc','auto','「ㅏ」와 「ㅓ」는 무엇이 다른가요?',ARRAY['K1-2-u5-X06']::text[],false,'{"seq":12,"concept":"K1-2-u5-C2","difficulty":2,"kind":"mc","stem":"「ㅏ」와 「ㅓ」는 무엇이 다른가요?","options":[{"t":"짧은 획이 오른쪽과 왼쪽으로 붙은 방향이 다르다","correct":true},{"t":"긴 획이 서 있고 누워 있다","mis":"K1-2-u5-X06"},{"t":"아무 관계가 없다","mis":"K1-2-u5-X06"}],"explanation":["ㅏ는 오른쪽, ㅓ는 왼쪽.","긴 획은 둘 다 서 있어요.","방향."],"asset":{"type":"scene","icon":"ㅗ   ㅜ   ㅏ   ㅓ","text":"같은 짧은 획이 붙은 자리를 살펴봐요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#13','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C4',2,'mc','auto','채윤이가 하람이에게 한 말로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u5-X11']::text[],false,'{"seq":13,"concept":"K1-2-u5-C4","difficulty":2,"kind":"mc","stem":"채윤이가 하람이에게 한 말로 알맞은 것은 어느 것인가요?","options":[{"t":"그 부분은 왜 좋았어?","correct":true},{"t":"그건 잘못 고른 거야.","mis":"K1-2-u5-X11"},{"t":"내 부분으로 바꿔.","mis":"K1-2-u5-X11"}],"explanation":["까닭을 물었어요.","다른 부분은 틀린 게 아니에요.","존중."],"asset":{"type":"speech","turns":[{"who":"채윤","text":"나는 박쥐가 거꾸로 자는 부분이 제일 재미있었어."},{"who":"하람","text":"나는 예준이가 동생에게 이야기해 주는 부분이 좋았는데."},{"who":"채윤","text":"그 부분은 왜 좋았어?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#14','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C7',2,'mc','auto','태오의 계획표에서 고치면 좋은 것은 어느 것인가요?',ARRAY['K1-2-u5-X17']::text[],false,'{"seq":14,"concept":"K1-2-u5-C7","difficulty":2,"kind":"mc","stem":"태오의 계획표에서 고치면 좋은 것은 어느 것인가요?","options":[{"t":"가장 두껍고 어려운 책을 첫 칸에 놓은 것","correct":true},{"t":"책 제목을 적은 것","mis":"K1-2-u5-X17"},{"t":"칸을 세 개 그린 것","mis":"K1-2-u5-X17"}],"explanation":["첫 칸엔 쉬운 책.","제목과 칸은 잘했어요.","맨 아래 칸."],"asset":{"type":"passage","lines":["③ 맨 위 칸 — 「숲속 빵집」 (얇고 그림이 많은 책)","② 가운데 칸 — 「별빛 우체통」","① 맨 아래 칸 — 「공룡 큰 사전」 (가장 두껍고 어려운 책)"],"title":"태오의 계단 독서 계획표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#15','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C3',2,'ox','auto','「솜」의 받침을 바꾸어 만든 「솥」은 낱말이에요.',ARRAY['K1-2-u5-X07']::text[],false,'{"seq":15,"concept":"K1-2-u5-C3","difficulty":2,"kind":"ox","stem":"「솜」의 받침을 바꾸어 만든 「솥」은 낱말이에요.","answer":"O","reason_options":[{"t":"밥을 짓는 그릇이라는 뜻이 있으니까","correct":true},{"t":"「솜」과 첫 자음자가 같으니까","mis":"K1-2-u5-X07"}],"mis":"K1-2-u5-X07","explanation":["뜻이 있으니 낱말이에요.","첫 자음자가 같아서가 아니에요.","뜻이 있는지."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#16','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C5',2,'mc','auto','「신발을 내려다볼 때마다 어깨가 으쓱했다」에서 알 수 있는 하람이의 마음은 어느 것인가요?',ARRAY['K1-2-u5-X14']::text[],false,'{"seq":16,"concept":"K1-2-u5-C5","difficulty":2,"kind":"mc","stem":"「신발을 내려다볼 때마다 어깨가 으쓱했다」에서 알 수 있는 하람이의 마음은 어느 것인가요?","options":[{"t":"스스로 해내어 자랑스러운 마음","correct":true},{"t":"끈이 풀려 짜증 나는 마음","mis":"K1-2-u5-X14"},{"t":"형에게 미안한 마음","mis":"K1-2-u5-X14"}],"explanation":["「어깨가 으쓱」은 자랑스러움.","짜증은 처음 일이에요.","마음을 알려 주는 말."],"asset":{"type":"passage","lines":["나는 혼자 운동화 끈을 묶어 보기로 했다.","처음에는 끈이 자꾸 풀려서 짜증이 났다.","형이 \"고리를 두 개 만들어 봐.\" 하고 알려 주었다.","나는 고리 두 개를 만들어 천천히 엇갈려 묶었다.","다음 날 아침, 끈이 한 번도 풀리지 않고 학교까지 갔다.","신발을 내려다볼 때마다 어깨가 으쓱했다."],"title":"「운동화 끈」 — 하람이가 쓴 글(「나」는 하람)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
