INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#19','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C6',3,'ox','auto','「좋았다」 한마디로 끝내면 무엇이 왜 좋았는지 알 수 없어요.',ARRAY['K1-2-u5-X10']::text[],false,'{"seq":19,"concept":"K1-2-u5-C6","difficulty":3,"kind":"ox","stem":"「좋았다」 한마디로 끝내면 무엇이 왜 좋았는지 알 수 없어요.","answer":"O","reason_options":[{"t":"어느 부분 때문인지 까닭이 없으면 내 생각이 보이지 않으니까","correct":true},{"t":"한마디는 너무 짧아서 예의가 없으니까","mis":"K1-2-u5-X10"}],"mis":"K1-2-u5-X10","explanation":["어느 부분 + 까닭.","예의가 아니라 생각이 안 보여서예요.","선생님이 되물은 까닭."],"asset":{"type":"speech","turns":[{"who":"선생님","text":"「강낭콩 화분」을 읽고 어떤 생각이 들었나요?"},{"who":"예준","text":"좋았어요."},{"who":"선생님","text":"어느 부분이 어떻게 좋았나요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#20','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C2',3,'mc','auto','한글이 생기기 전에는 어땠을까요?',ARRAY['K1-2-u5-X05','K1-2-u5-X04']::text[],false,'{"seq":20,"concept":"K1-2-u5-C2","difficulty":3,"kind":"mc","stem":"한글이 생기기 전에는 어땠을까요?","options":[{"t":"글을 읽고 쓸 줄 아는 사람이 아주 적었다","correct":true},{"t":"누구나 글을 쉽게 썼다","mis":"K1-2-u5-X05"},{"t":"모두 한글로 편지를 썼다","mis":"K1-2-u5-X04"}],"explanation":["배우기 어려운 글자뿐이었어요.","한글이 없으니 한글 편지도 없었어요.","그래서 만들었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
