INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#22','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C6',3,'mc','auto','「운동화 끈」과 비슷한 경험으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u5-X16']::text[],false,'{"seq":22,"concept":"K1-2-u5-C6","difficulty":3,"kind":"mc","stem":"「운동화 끈」과 비슷한 경험으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"어려워서 짜증 났지만 방법을 배워 스스로 해냈던 일","correct":true},{"t":"새 운동화를 산 일","mis":"K1-2-u5-X16"},{"t":"형과 텔레비전을 본 일","mis":"K1-2-u5-X16"}],"explanation":["짜증 → 방법 → 스스로 해냄.","신발이나 형만 같은 것은 비슷한 경험이 아니에요.","일과 마음."],"asset":{"type":"passage","lines":["나는 혼자 운동화 끈을 묶어 보기로 했다.","처음에는 끈이 자꾸 풀려서 짜증이 났다.","형이 \"고리를 두 개 만들어 봐.\" 하고 알려 주었다.","나는 고리 두 개를 만들어 천천히 엇갈려 묶었다.","다음 날 아침, 끈이 한 번도 풀리지 않고 학교까지 갔다.","신발을 내려다볼 때마다 어깨가 으쓱했다."],"title":"「운동화 끈」 — 하람이가 쓴 글(「나」는 하람)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#23','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C8',4,'sa','auto','그림을 보고 빈칸에 알맞은 세는 낱말을 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#24','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C4',4,'essay','teacher','내가 읽은 책 한 권을 친구에게 추천하는 말을 쓰세요. 책 제목과 추천하는 까닭이 들어가게 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u5-C4","difficulty":4,"kind":"essay","stem":"내가 읽은 책 한 권을 친구에게 추천하는 말을 쓰세요. 책 제목과 추천하는 까닭이 들어가게 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 이 책은 「숲속 빵집」이야. 동물들이 함께 빵을 굽는 장면이 따뜻해서 추천해. — 제목과 내용에서 온 까닭이 있으면 맞아요(어떤 책이든 좋아요).","scoring_points":["책 제목이 있는가","추천하는 까닭이 있는가","까닭이 책의 내용(장면·재미)에서 왔는가"]},"explanation":["제목 + 까닭.","어떤 책이든 좋아요.","읽고 싶어지게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_review_d#25','kor',1,2,'u5','','g1_2_kor_u5_review_d','unit_review','K1-2-u5-C6',4,'essay','teacher','「운동화 끈」을 읽고 든 생각이나 느낌을 글의 어느 부분 때문인지 넣어 한 문장, 비슷한 내 경험을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u5-C6","difficulty":4,"kind":"essay","stem":"「운동화 끈」을 읽고 든 생각이나 느낌을 글의 어느 부분 때문인지 넣어 한 문장, 비슷한 내 경험을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 짜증이 났는데도 형이 알려 준 대로 천천히 묶은 것이 대단해 보였다. 나도 단추 끼우기가 어려웠지만 혼자 해냈을 때 으쓱했다. — 글의 부분과 내 생각, 일이나 마음이 닮은 경험이 있으면 맞아요.","scoring_points":["글의 어느 부분인지 있는가","내 생각·느낌을 내 말로 썼는가","일이나 마음이 닮은 경험인가"]},"explanation":["어느 부분 + 내 생각.","닮은 경험 하나.","옮기지 말고 내 말로."],"asset":{"type":"passage","lines":["나는 혼자 운동화 끈을 묶어 보기로 했다.","처음에는 끈이 자꾸 풀려서 짜증이 났다.","형이 \"고리를 두 개 만들어 봐.\" 하고 알려 주었다.","나는 고리 두 개를 만들어 천천히 엇갈려 묶었다.","다음 날 아침, 끈이 한 번도 풀리지 않고 학교까지 갔다.","신발을 내려다볼 때마다 어깨가 으쓱했다."],"title":"「운동화 끈」 — 하람이가 쓴 글(「나」는 하람)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
